// MIT. Wire shapes for the existing Cryptoworth accountant workflow.
export const CRYPTOWORTH_TOOL_PREFIX='merchant_accounting_cryptoworth_';
export const CRYPTOWORTH_CLIENT_OPERATION_SCHEMA='stellar-forge.accounting-cryptoworth-operation.v1';
export const CRYPTOWORTH_FILE_SELECTORS=['profileId','captureId','returnId','rollbackId','scope'];
export const cryptoworthFileName={type:'string',pattern:'^[A-Za-z0-9][A-Za-z0-9._-]{0,239}$'};
const text={type:'string',maxLength:4000},alias={type:'string',pattern:'^[a-z0-9][a-z0-9_-]{0,63}$'};
export const cryptoworthNativeId={type:'string',pattern:'^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'};
const nativeId=cryptoworthNativeId,sha={type:'string',pattern:'^[a-f0-9]{64}$'};
const nullableId={anyOf:[nativeId,{type:'null'}]},instant={type:'string',minLength:1,maxLength:80};
const object=(properties,required=[],additionalProperties=false)=>({type:'object',properties,required,additionalProperties});
const page={offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:200}};
const filter={...page,status:{type:'string',maxLength:100},search:{type:'string',maxLength:500}};
const workspace={workspace:alias},bound={...workspace,workspaceId:sha};
const revision={type:'integer',minimum:1},who={id:nativeId,name:{type:'string',minLength:1,maxLength:240},actor:{type:'string',minLength:1,maxLength:1000},createdAt:instant};
const sourceFile=object({source:alias,name:{type:'string',minLength:1,maxLength:240},sha256:sha,bytes:{type:'integer',minimum:0,maximum:134217728}},['source','name']);
const roles=['date','cryptoId','type','amountOne','amountOneType','amountTwo','amountTwoType','transactionHash','connectionId','note','ledgerId','rowId'];
const columns=object(Object.fromEntries(roles.map(role=>[role,{type:'string',minLength:1,maxLength:1000}])));
const date=object({format:{type:'string',enum:['ISO_UTC','UTC_SECONDS','UTC_DATE','ZONE_SECONDS','ZONE_DATE']},timeZone:{type:'string',minLength:1,maxLength:100},precision:{type:'string',enum:['day','second','millisecond']}},['format','timeZone']);
const target=object({entityId:text,entityName:text,connectionId:text,connectionName:text,merchantAccount:text},['entityId','connectionId','merchantAccount']);
const profile={...who,previousProfileId:nullableId,file:sourceFile,delimiter:{type:'string',enum:[',',';','\t']},columns,
  constants:object({},[],true),target,date,assets:{type:'array',minItems:1,maxItems:500,items:object({
    network:{type:'string',enum:['stellar:testnet','stellar:pubnet']},assetDigest:sha,cryptoId:text,amountType:text,scale:{type:'integer',minimum:0,maximum:30}},
    ['network','assetDigest','cryptoId','amountType','scale'])}};
const plan={...who,profileId:nativeId,handoffId:nativeId,accountantRevisionId:{anyOf:[nativeId,{type:'string',enum:['initial']}]},previousPlanId:nullableId,
  decisions:{type:'array',maxItems:50000,items:object({movementId:sha,selectionId:{anyOf:[sha,{type:'null'}]},action:{type:'string',enum:['INCLUDE','EXCLUDE','ALREADY_IMPORTED']},reason:text,reference:text},['movementId','action'])},
  dateEvidence:{type:'array',maxItems:5000,items:object({movementId:sha,transferAt:instant,note:text,file:sourceFile},['movementId','transferAt','note','file'])}};
const nativeImport=object({id:text,entityId:text,connectionId:text,receivedAt:instant,reference:text,note:text},['id','entityId','connectionId','receivedAt','reference']);
const capture={...who,purpose:{type:'string',enum:['IMPORT_RETURN','BASELINE']},file:sourceFile,nativeImport,layout:object({
  kind:{type:'string',enum:['INPUT_FORMAT','MAPPED_EXPORT']},delimiter:{type:'string',enum:[',',';','\t']},columns,date,
  amountConvention:{type:'string',enum:['UNSIGNED','SEND_NEGATIVE']},amountTwoConvention:{type:'string',enum:['UNSIGNED','SEND_NEGATIVE']},groupSeparator:{type:'string',enum:['',',']}},['kind'])};
const returned={...who,captureId:nativeId,status:{type:'string',enum:['REVIEWED','BOOKED']},bookRef:text,
  accountCode:{anyOf:[text,{type:'null'}]},note:text,expectedParentId:nullableId};
export const CRYPTOWORTH_REQUEST_FIELDS={profile:Object.keys(profile),plan:Object.keys(plan),capture:Object.keys(capture),return:Object.keys(returned)};
const requests={profile,plan,capture,return:returned};
const required={profile:['name','actor','file','columns','constants','target','date','assets'],plan:['name','actor','profileId','handoffId','accountantRevisionId'],
  capture:['name','actor','purpose','file','nativeImport','layout'],return:['name','actor','captureId','status','expectedParentId']};
const readOnly={readOnly:true,idempotent:true};
export const cryptoworthDefinitions=[
  [CRYPTOWORTH_TOOL_PREFIX+'status','Read this original Cryptoworth owner, workspace ID and revision. Page saved mappings, receiving plans, original handoffs or complete import-unit rollbacks.',{...workspace,view:{type:'string',enum:['summary','profiles','plans','handoffs','rollbacks']},...page},['workspace'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'source','Page the selected frozen original handoff and native payment/refund source. Keep accountantRevisionId explicit; initial selects the unchanged first handoff.',{...workspace,handoffId:nativeId,accountantRevisionId:{anyOf:[nativeId,{type:'string',enum:['initial']}]},...filter},['workspace','handoffId','accountantRevisionId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'template','Inspect the actual customer-supplied native template from one configured input alias. Returns exact filename, byte count and SHA256 for review.',{...workspace,file:sourceFile,delimiter:{type:'string',enum:[',',';','\t']}},['workspace','file'],readOnly],
  ...Object.keys(requests).flatMap(kind=>[
    [CRYPTOWORTH_TOOL_PREFIX+kind+'_preview','Review the original '+kind+' operation. File aliases are expanded using actual bytes and returned with exact hashes; keep the complete normalized request, workspace ID, revision and native preview hash.',
      {...workspace,...(['capture','return'].includes(kind)?{planId:nativeId}:{}),request:object(requests[kind],required[kind]),...(['plan','capture'].includes(kind)?filter:{})},
      ['workspace',...(['capture','return'].includes(kind)?['planId']:[]),'request'],{readOnly:true}],
    [CRYPTOWORTH_TOOL_PREFIX+kind+'_save','Save the exact reviewed original '+kind+' request. Preserve the native ID, timestamp, file hashes, workspace ID and preview hash. A retained native ID recovers the original outcome; no new payment or vendor import is initiated.',
      {...bound,...(['capture','return'].includes(kind)?{planId:nativeId}:{}),request:object({...requests[kind],revision,previewSha256:sha},[...required[kind],'id','createdAt','revision','previewSha256'])},
      ['workspace','workspaceId',...(['capture','return'].includes(kind)?['planId']:[]),'request'],{idempotent:true}]
  ]),
  [CRYPTOWORTH_TOOL_PREFIX+'profile','Read one exact retained mapping, source template identity and original files.',{...workspace,profileId:nativeId},['workspace','profileId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'plan','Read one retained receiving plan or page its captures, returns, rollbacks, files, prior packet receipts, decisions or native date sources.',{...workspace,planId:nativeId,view:{type:'string',enum:['summary','captures','returns','rollbacks','files','receivedPackets','decisions','dateEvidence']},...page},['workspace','planId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'rows','Page exact source/import rows or a selected native receiving comparison without changing their atomic amounts, signs or opaque native IDs.',{...workspace,planId:nativeId,captureId:nativeId,...filter},['workspace','planId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'capture','Read one saved native receiving capture, its source bytes, comparison summary and import-unit rollbacks.',{...workspace,planId:nativeId,captureId:nativeId},['workspace','planId','captureId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'return','Read the original staged, committed or superseded accountant return by native ID. PREPARED keeps the exact request available for continuation; COMMITTED and SUPERSEDED are terminal outcomes.',{...workspace,planId:nativeId,returnId:nativeId},['workspace','planId','returnId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'rollback','Record an already completed rollback of the entire selected native import unit. This updates original receiving coverage; the operator supplies the real vendor completion time and reference.',
    {...bound,planId:nativeId,request:object({id:nativeId,captureId:nativeId,nativeImportId:text,completedAt:instant,actor:{...text,maxLength:1000},reason:text,reference:text,revision},['id','captureId','nativeImportId','completedAt','actor','reason','reference','revision'])},
    ['workspace','workspaceId','planId','request'],{idempotent:true}],
  [CRYPTOWORTH_TOOL_PREFIX+'rollback_record','Read one exact saved native import-unit rollback.',{...workspace,rollbackId:nativeId},['workspace','rollbackId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'packet_inspect','Inspect a complete original receiving packet from a configured source alias. Rebuild its original template, source, native comparison, accountant returns and coverage before returning its exact two hashes.',{...workspace,file:sourceFile},['workspace','file'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'packet_receive','Receive the exact reviewed source packet in this original owner. Pin the input SHA256 and sealed packet SHA256. Existing native IDs retain their original history and source files.',
    {...bound,file:sourceFile,revision,actor:{...text,maxLength:1000},name:{...text,maxLength:240},expectedSha256:sha,expectedPacketSha256:sha},
    ['workspace','workspaceId','file','revision','actor','expectedSha256','expectedPacketSha256'],{idempotent:true}],
];

export function cryptoworthPreviewBinding(value){return {kind:value.kind,workspaceId:value.workspaceId,planId:value.planId??null,request:value.request,workspaceRevision:value.workspaceRevision,previewSha256:value.previewSha256,requestSha256:value.requestSha256};}

// MIT. Original client-runbook tool and prepared-request contract.
import {createHash} from 'node:crypto';
export const RUNBOOK_TOOL_PREFIX='merchant_accounting_runbooks_';
export const RUNBOOK_HOST_REQUEST_SCHEMA='stellar-forge.accounting-runbook-host-request.v1';
export const RUNBOOK_FILE_SELECTORS=['cycleId','fileId'];
export const RUNBOOK_ACTIONS=Object.freeze({
  save:{kind:'edition_saved',method:'save'},
  attach:{kind:'file_retained',method:'addFile'},
  create:{kind:'cycle_created',method:'createCycle'},
  work:{kind:'procedure_saved',method:'saveWork',target:true},
  submit:{kind:'preparation_submitted',method:'submit',target:true},
  review:{kind:'review_saved',method:'review',target:true},
  receive:{kind:'packet_received',method:'receive'},
});
export const RUNBOOK_INPUT_FIELDS=Object.freeze({
  save:['actor','runbookId','expectedEditionId','name','client','description','resources','steps'],
  attach:['actor','name','type'],
  create:['actor','runbookId','editionId','label','preparer','reviewer','dueDate','previousCycleId','sourceKind','handoffId','accountantRevisionId','periodCloseId','sourceLabel','sourceNote','sourceFileIds'],
  work:['actor','stepId','status','note','fileIds'],
  submit:['actor','note'],
  review:['actor','decision','note','acceptedExceptions'],
  receive:['actor'],
});
const plain=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
const UUID=/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/;
const SHA=/^[a-f0-9]{64}$/;
function need(ok,message,code='RUNBOOK_HOST_REQUEST_CHANGED'){if(!ok)throw Object.assign(new Error(message),{code});}
function exact(value,fields){need(plain(value)&&Object.keys(value).every(key=>fields.includes(key)),'Keep the declared original request fields.');}
/** Same ordinary-JSON representation as the native runbooks controller; no trailing newline. */
export function runbookWireCanonical(value){
  if(Array.isArray(value))return '['+value.map(runbookWireCanonical).join(',')+']';
  if(plain(value))return '{'+Object.keys(value).filter(key=>value[key]!==undefined).sort().map(key=>JSON.stringify(key)+':'+runbookWireCanonical(value[key])).join(',')+'}';
  need(value===null||typeof value==='string'||typeof value==='boolean'||typeof value==='number'&&Number.isFinite(value),'Use ordinary JSON request values.');
  return JSON.stringify(value);
}
export const runbookWireHash=value=>createHash('sha256').update(runbookWireCanonical(value)).digest('hex');
export function runbookHostBinding(value){
  const {wireSha256,...binding}=value;return binding;
}
export function runbookHostRequest(value){
  exact(value,['schema','action','kind','target','input','file','requestSha256','wireSha256']);
  need(value.schema===RUNBOOK_HOST_REQUEST_SCHEMA&&Object.hasOwn(RUNBOOK_ACTIONS,value.action),'Choose the original saved client-runbook request.');
  const route=RUNBOOK_ACTIONS[value.action],withFile=['attach','receive'].includes(value.action);
  need(value.kind===route.kind&&(route.target?UUID.test(value.target??''):value.target===null),'Keep the original action and period selection.');
  exact(value.input,['workspaceId','requestId','revision',...RUNBOOK_INPUT_FIELDS[value.action]]);
  need(SHA.test(value.input.workspaceId??'')&&UUID.test(value.input.requestId??'')&&
    Number.isSafeInteger(value.input.revision)&&value.input.revision>=1,'Keep the original workspace, request UUID and revision.');
  need(typeof value.input.actor==='string'&&value.input.actor.trim().length>0&&value.input.actor.length<=160&&!value.input.actor.includes('\0'),'Supply the responsible operator, up to160 characters.');
  need(SHA.test(value.requestSha256??'')&&SHA.test(value.wireSha256??''),'Keep both complete prepared-request hashes.');
  if(withFile){
    exact(value.file,['source','name','bytes','sha256']);
    need(/^[a-z0-9][a-z0-9_-]{0,63}$/.test(value.file.source??'')&&
      typeof value.file.name==='string'&&value.file.name.trim()&&value.file.name.length<=160&&
      !/[\\/\r\n\0"]/.test(value.file.name)&&!['.','..'].includes(value.file.name),'Keep the original configured file alias and name.');
    const maximum=(value.action==='receive'?64:8)*1024*1024;
    need(Number.isSafeInteger(value.file.bytes)&&value.file.bytes>0&&value.file.bytes<=maximum&&SHA.test(value.file.sha256??''),'Keep the reviewed complete file size and SHA256.');
    if(value.action==='attach')need(value.input.name===value.file.name,'The retained filename differs from the reviewed original file.');
  }else{
    need(value.file===undefined,'This action does not select an uploaded file.');
    need(runbookWireHash({kind:value.kind,target:value.target,input:value.input})===value.requestSha256,'The original native request changed.');
  }
  need(runbookWireHash(runbookHostBinding(value))===value.wireSha256,'The complete saved request or file selection changed.');
  return value;
}
export function runbookOperationMatches(prepared,operation){
  runbookHostRequest(prepared);
  need(plain(operation)&&operation.id===prepared.input.requestId&&operation.kind===prepared.kind&&
    operation.target===prepared.target&&operation.requestSha256===prepared.requestSha256&&
    operation.result?.workspaceId===prepared.input.workspaceId&&operation.result?.requestId===prepared.input.requestId,
    'This request UUID belongs to different saved client work.','RUNBOOK_REQUEST_CONFLICT');
  return operation.result;
}
const alias={type:'string',pattern:'^[a-z0-9][a-z0-9_-]{0,63}$'};
const uuid={type:'string',pattern:'^[0-9a-f-]{36}$'},sha256={type:'string',pattern:'^[a-f0-9]{64}$'};
const revision={type:'integer',minimum:1};
const base={workspace:alias,workspaceId:sha256,expectedRevision:revision};
const page={offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:50}};
const choice=values=>({type:'string',enum:values});
const nativeInput={type:'object',properties:{},additionalProperties:true};
const sourceFile={type:'object',properties:{source:alias,name:{type:'string',minLength:1,maxLength:160},sha256,bytes:{type:'integer',minimum:1,maximum:64*1024*1024}},required:['source','name'],additionalProperties:false};
const readOnly={readOnly:true,idempotent:true};
export const runbookDefinitions=[
  [RUNBOOK_TOOL_PREFIX+'status','Inspect the original client-runbook workspace. Page client books, periods, retained files or received packets; summary reports counts. Complete procedures and preparation history remain in their selected book and cycle views.',{...base,view:choice(['summary','books','cycles','files','received']),...page},['workspace'],readOnly],
  [RUNBOOK_TOOL_PREFIX+'sources','Inspect actual accountant handoffs and their retained return revisions, period closes or original client files. File-based periods select retained runbook file IDs. Handoff revisions require handoffId.',{...base,view:choice(['handoffs','revisions','closes','files']),handoffId:uuid,...page},['workspace'],readOnly],
  [RUNBOOK_TOOL_PREFIX+'book','Read an original client book and a selected immutable procedure edition. Page edition headers, full steps or complete supporting resources. Omitted editionId selects the current edition; later pages can pin expectedRevision.',{...base,runbookId:uuid,editionId:uuid,view:choice(['summary','editions','steps','resources']),...page},['workspace','runbookId'],readOnly],
  [RUNBOOK_TOOL_PREFIX+'cycle','Inspect a frozen client period with its actual close source. Page full procedures/current work, resources, original source-file metadata, preparation rounds, selected submission work, reviews or complete history. A received period stays read-only; its procedures can start a new local period.',{...base,cycleId:uuid,submissionId:uuid,view:choice(['summary','steps','resources','source_files','submissions','submission_work','reviews','history']),...page},['workspace','cycleId'],readOnly],
  [RUNBOOK_TOOL_PREFIX+'operation','Recover one original saved request by UUID, including its action, period target, native request digest and committed result.',{...base,requestId:uuid},['workspace','requestId'],readOnly],
  [RUNBOOK_TOOL_PREFIX+'prepare','Construct the complete original request for save, attach, create, work, submit, review or receive. input holds actor and native action fields; the tool supplies the current workspace/revision and a request UUID. attach/receive read one runbookInputs alias and pin its actual bytes. Save the complete returned request before execute. Preparation does not commit work.',{...base,action:choice(Object.keys(RUNBOOK_ACTIONS)),cycleId:uuid,requestId:uuid,input:nativeInput,file:sourceFile},['workspace','action','input'],{readOnly:true}],
  [RUNBOOK_TOOL_PREFIX+'execute','Execute the unchanged saved request through the original client-runbook writer. An already committed request recovers its original result before re-reading a source file. Changed UUID content conflicts; after a lost reply use reconcile or replay this exact request.',{workspace:alias,prepared:nativeInput},['workspace','prepared'],{idempotent:true}],
  [RUNBOOK_TOOL_PREFIX+'reconcile','Find the original committed result for the complete saved request without requiring its configured input file to survive. NOT_FOUND keeps the same request available for exact execution.',{workspace:alias,prepared:nativeInput},['workspace','prepared'],readOnly],
];

// MIT. Typed wire contract for the existing API-pass customer workspace.
import {createHash} from 'node:crypto';
export const API_PASS_PREFIX='merchant_api_pass_';
export const API_PASS_CONNECTION_SCHEMA='stellar-forge.sf101.api-pass-mcp-connection.v1';
export const API_PASS_EXPORT_SCHEMA='stellar-forge.sf101.api-pass-mcp-export.v1';
export const API_PASS_EXPORT_MANIFEST='api-pass-export.json';
export const API_PASS_MAX_FILE_BYTES=128*1024*1024;
export const API_PASS_ALIAS=/^[a-z0-9][a-z0-9_-]{0,63}$/;
export const API_PASS_ID=/^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/;
export const API_PASS_UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;
export const API_PASS_SHA=/^[a-f0-9]{64}$/;
export const apiPassPlain=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
export const apiPassFailure=(code,message,extra={})=>Object.assign(new Error(message),{code,apiPassPublic:true,...extra});
export const apiPassHash=value=>createHash('sha256').update(value).digest('hex');
export const apiPassCanonical=value=>Array.isArray(value)?value.map(apiPassCanonical):apiPassPlain(value)?Object.fromEntries(Object.keys(value).sort().map(key=>[key,apiPassCanonical(value[key])])):value;
export const apiPassFingerprint=value=>apiPassHash(JSON.stringify(apiPassCanonical(value)));
export function apiPassNeed(condition,message,code='INVALID_PARAMS'){if(!condition)throw apiPassFailure(code,message);}
export function apiPassExact(value,keys,required=[]){apiPassNeed(apiPassPlain(value)&&Object.keys(value).every(key=>keys.includes(key))&&required.every(key=>Object.hasOwn(value,key)),'Supply only the declared fields and every required field.');}
export function apiPassChecked(value,pattern,label){apiPassNeed(typeof value==='string'&&pattern.test(value),'Supply the exact '+label+'.');return value;}
export function apiPassInteger(value,minimum,maximum,label){apiPassNeed(Number.isSafeInteger(value)&&value>=minimum&&value<=maximum,'Supply '+label+' within its declared range.');return value;}
export function apiPassText(value,maximum,label,{empty=false}={}){apiPassNeed(typeof value==='string'&&(empty||value.trim().length>0)&&value.length<=maximum&&!/[\u0000-\u001f\u007f]/.test(value),'Supply the original '+label+'.');return value;}
const alias={type:'string',pattern:API_PASS_ALIAS.source},uuid={type:'string',pattern:API_PASS_UUID.source},sha={type:'string',pattern:API_PASS_SHA.source},identity={type:'string',pattern:API_PASS_ID.source};
const text=(max=160)=>({type:'string',minLength:1,maxLength:max});
const revision={type:'integer',minimum:1,maximum:Number.MAX_SAFE_INTEGER};
const page={offset:{type:'integer',minimum:0,maximum:10000},limit:{type:'integer',minimum:1,maximum:200},expectedRevision:revision};
const mutation={operationId:identity,expectedRevision:revision};
export const API_PASS_TASK_KINDS=Object.freeze(['refresh','call','recover','prepare-purchase','review-purchase','execute-purchase','recover-purchase','finalize-purchase','report-purchase','inspect-lost-output','recover-lost-output','read-lost-output','export-lost-output']);
const selectionSchema={type:'object',additionalProperties:false,properties:{kind:{type:'string',enum:['response','review','proof','report','history']},profileId:uuid,callId:uuid,taskId:uuid},required:['kind']};
const definitions=[];
function define(name,description,properties={},required=[],annotations={readOnly:true,idempotent:true}){definitions.push({name:API_PASS_PREFIX+name,description,properties,required,annotations});}
define('workspaces','List configured original API-pass workspace aliases, pinned public identities and declared input/purchase handles. Private launch capabilities and host paths remain on the host.');
define('open','Authenticate the existing private launch record and the original running workspace. Returns its current session and public launch identity.',{workspace:alias},['workspace']);
define('status','Read the original workspace revision, pass counts, claim environment names and recent task/history windows; includes complete-history and retained-export availability.',{workspace:alias},['workspace']);
define('passes','Page public pass summaries from one original workspace snapshot. Pin expectedRevision when continuing the same observed inventory.',{workspace:alias,...page},['workspace']);
define('pass','Read one original pass, purchased routes, allowance and a real page of saved calls. Native detail includes its latest 100 tasks; history reads all retained tasks.',{workspace:alias,profileId:uuid,...page},['workspace','profileId']);
define('call','Read an original saved request and retained result identity without dispatching it.',{workspace:alias,callId:uuid},['workspace','callId']);
define('call_preview','Read the original bounded UTF-8/binary response preview. Use capture and complete file download for the original bytes.',{workspace:alias,callId:uuid},['workspace','callId']);
define('body_preview','Read the original saved request-body preview and its explicit truncation/byte metadata.',{workspace:alias,callId:uuid},['workspace','callId']);
define('remote_calls','Read the original merchant call page and its exact nextAfter cursor. This does not adopt or execute a request.',{workspace:alias,profileId:uuid,after:text(256),limit:page.limit},['workspace','profileId']);
define('history','Page all saved calls or tasks from the original complete customer-history export. Pin expectedRevision across pages; use capture(kind=history) for the whole original file.',{workspace:alias,profileId:uuid,view:{type:'string',enum:['calls','tasks']},...page},['workspace','profileId','view']);
define('task','Find one exact retained task in the original complete profile history, including tasks outside the recent UI window.',{workspace:alias,profileId:uuid,taskId:uuid},['workspace','profileId','taskId']);
define('operation','Reopen one host-retained exact HTTP operation, its dispatch history and complete saved response before any retry. Original argument handles and native IDs remain bound.',{workspace:alias,operationId:identity},['workspace','operationId']);
define('approval','Read the original browser-broker approval envelope or original-terminal mode for this purchase.',{workspace:alias,profileId:uuid},['workspace','profileId']);
define('input','Inspect the complete byte count and SHA256 of one host-declared original handoff, request body or approved-request file.',{workspace:alias,file:alias},['workspace','file']);
define('connect','Connect an existing purchased pass through the original model. Keep operationId and all fields on an interrupted retry.',{workspace:alias,...mutation,label:text(),gatewayBaseUrl:text(2048),orderReference:identity,manifestSha256:sha,claimEnv:text(65)},['workspace','operationId','expectedRevision','label','gatewayBaseUrl','orderReference','manifestSha256','claimEnv'],{idempotent:true});
define('purchase_prepare','Retain an original purchase using a host-declared complete checkout handoff and its reviewed SHA. The original Buyer/Inbox perform later preparation, review and payment tasks.',{workspace:alias,...mutation,label:text(),gatewayBaseUrl:text(2048),intentId:identity,claimEnv:text(65),handoff:alias,expectedHandoffSha256:sha},['workspace','operationId','expectedRevision','label','gatewayBaseUrl','intentId','claimEnv','handoff','expectedHandoffSha256'],{idempotent:true});
define('purchase_attach','Adopt the host-declared existing original purchase directory with pinned customer metadata and original intent/order; the original workspace validates Buyer custody.',{workspace:alias,...mutation,label:text(),purchase:alias},['workspace','operationId','expectedRevision','label','purchase'],{idempotent:true});
