        documentId:descriptor.documentId,bodySha256:descriptor.bodySha256,bodyBytes:descriptor.bodyBytes,
        sourceMatchesDescriptor:result.sha256===descriptor.bodySha256&&result.bytes===descriptor.bodyBytes});
