    return '"' + text.replaceAll('"', '""') + '"';
  };
  return [columns, ...report.days.flatMap(entry => entry.routes.map(row =>
    columns.map(key => key === 'day' ? entry.day : row[key])))].map(row => row.map(cell).join(','))
    .join('\r\n') + '\r\n';
