      pendingConnect.once('response', (response) => {
        response.resume();
        complete(proxyError('PROXY_CONNECT_NOT_ESTABLISHED'));
      });
      pendingConnect.once('error', (error) => complete(error));
      pendingConnect.end();
      if (signal.aborted) onAbort();
    } catch (error) { complete(error); }
  };
  return { agent, stop };
}

