  requireTruth(Number.isSafeInteger(maxEventPages) && maxEventPages >= 1 &&
    maxEventPages <= 100, 'INVALID_EVENT_PAGE_BUDGET');
  requireTruth(typeof decodeContractEvent === 'function', 'STELLAR_SDK_DECODER_REQUIRED');
  let networkResult;
  if(live) {
