    filters:value.filters, ...(ranges.length || sort ? {ranges:contract.ranges, order:sort} : {}),
    total:p.total, returned:p.returned, offset, nextOffset,
    nextCursor:p.nextCursor, sha256:digest(bytes), bytes:bytes.length,
