    created = await file.stat();
    await file.writeFile(JSON.stringify(identity, null, 2) + '\n');
    await file.sync();
    await syncDirectory(dirname(path));
  } catch (error) {
    // A failed exclusive write must not leave a false running-session marker.
    if (created) {
