      r.network === t.network && r.reservedAtomicUnits === t.amount, 'DATASET_NATIVE_RESERVATION_MISMATCH');
  } else need(b.status === 'NO_PAYMENT_REQUIRED' && e.operatorReservation === null, 'DATASET_NATIVE_OUTCOME_UNRESOLVED');
