  return (options, callback) => {
    need(options.method === 'GET' && !Object.keys(options.headers).some(name =>
      /^(payment-signature|x-payment|authorization|cookie|proxy-authorization)$/i.test(name)),
    'CATALOG_TRANSPORT_UNSIGNED_GET_ONLY');
