    const explicit = normalizeOperationHeaders({'Content-Type':flags.get('--content-type')});
    need(headers['Content-Type'] === undefined || headers['Content-Type'] === explicit['Content-Type'],
      'PREPARE_CONTENT_TYPE_HEADER_CONFLICT');
