    edition.sheet=index;
    edition.catalog=await api('/api/workbooks/'+encodeURIComponent(w.loaded.definition.name)+'/refresh?revision='+
      w.edition.base_revision+'&sheet='+index+(before?'&before='+before:''));
    edition.before=before;edition.pages=pages;
