"""LangChain tools for the original Buyer customer workflow.

No model provider is required. Pass these tools to a LangChain agent or ToolNode,
or invoke them with a normal ToolCall envelope. Full response pages remain in
ToolMessage.artifact; model-visible content has an explicit cap.
"""
from __future__ import annotations

import asyncio
import json
from typing import Literal

from .agent_workflow import CustomerWorkflow, _error, _url
from .errors import BuyerError, StateError

try:
    from langchain_core.tools import StructuredTool
    from pydantic import BaseModel, ConfigDict, Field
except ImportError:
    raise StateError("INSTALL_STELLAR_FORGE_BUYER_AGENTS_EXTRA") from None


class _Arguments(BaseModel):
    model_config = ConfigDict(extra="forbid")


class PageArguments(_Arguments):
    offset: int = Field(default=0, ge=0)
    limit: int = Field(default=20, ge=1, le=100)


class IntentArguments(_Arguments):
    intent_id: str = Field(min_length=1, max_length=160,
                           description="The existing original Buyer intent identifier.")


class RunArguments(_Arguments):
    run_id: str = Field(min_length=1, max_length=160,
                       description="The stable customer run identifier; reuse it after restart.")


class RegisterArguments(RunArguments, IntentArguments):
    format: Literal["auto", "json", "csv", "binary", "sse", "ndjson", "paid-file"] = "auto"
    allow_partial: bool = Field(default=False,
        description="Allow the native reader's retained complete-record prefix of an interrupted stream.")


class ResumeArguments(RunArguments):
    action: Literal["execute", "recover", "review", "cancel"] = "recover"
    review_key: str | None = Field(default=None, pattern=r"^[0-9a-f]{64}$",
        description="Exact key from the current original-review interruption; required for execute.")


class ReadArguments(RunArguments, PageArguments):
    pointer: str = Field(default="", max_length=2048,
        description="JSON Pointer into each NDJSON/CSV value or JSON document; default returns whole values.")
    event_json: bool = Field(default=False,
        description="For SSE only: explicitly parse each event's data as JSON before applying pointer.")


def _operation_summary(record):
    request = record.get("request") or {}
    result = {"intent_id": record["intentId"], "state": record["state"],
              "method": request.get("method"), **_url(request.get("url")),
              "native_status": record.get("nativeStatus"),
              "delivery_status": record.get("deliveryStatus"),
              "result_recoverable": record.get("resultRecoverable", False),
              "file_promise": record.get("filePromise")}
    if record.get("fileDelivery"):
        original = record["fileDelivery"]
        native = original.get("native") or {}
        result["file_delivery"] = {"state": original.get("state"), "status": native.get("status"),
                                   "returncode": original.get("returncode"),
                                   "runtime_error": original.get("runtimeError"),
                                   "http_requests": native.get("httpRequests")}
    return result


def create_tools(workflow: CustomerWorkflow, *, prefix="stellar_forge", max_content_chars=6000,
                 file_options_by_intent=None):
    """Return typed tools bound to one private customer workspace.

    The host prepares requests with Buyer.prepare/from_workspace/from_paid_file,
    including its private native operator profile. Tools select those original
    intents and exact saved reviews. Bind file destinations and claim environment
    variable names through file_options_by_intent; secret values are never tool
    arguments. Async tools use a worker thread, preserving original SQLite and
    operation locks. A busy operation is returned as an ordinary error.
    """
    if (not isinstance(prefix, str) or not prefix or len(prefix) > 80
            or any(character not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-" for character in prefix)):
        raise StateError("AGENT_TOOL_PREFIX_INVALID")
    if type(max_content_chars) is not int or not 1000 <= max_content_chars <= 50000:
        raise StateError("AGENT_TOOL_CONTENT_LIMIT_INVALID")
    file_options = {key: dict(value) for key, value in dict(file_options_by_intent or {}).items()}

    def reply(artifact):
        raw = json.dumps(artifact, ensure_ascii=True, allow_nan=False, separators=(",", ":"))
        if len(raw) <= max_content_chars:
            return raw, artifact
        summary = {"content_truncated": True, "artifact_available": True,
                   "characters": len(raw), "preview": raw[:max_content_chars - 400]}
        content = json.dumps(summary, ensure_ascii=True, separators=(",", ":"))
        while len(content) > max_content_chars:
            excess = len(content) - max_content_chars
            summary["preview"] = summary["preview"][:max(0, len(summary["preview"]) - excess)]
            content = json.dumps(summary, ensure_ascii=True, separators=(",", ":"))
        return content, artifact

    def expose(function):
        def call(**arguments):
            try:
                return reply(function(**arguments))
            except (BuyerError, OSError) as error:
                return reply({"status": "ERROR", "error": _error(error)})
        return call

    def tool(name, description, schema, function):
        call = expose(function)

        async def async_call(**arguments):
            return await asyncio.to_thread(call, **arguments)

        return StructuredTool.from_function(func=call, coroutine=async_call,
            name=prefix + "_" + name, description=description, args_schema=schema,
            infer_schema=False, response_format="content_and_artifact")

    def operations(offset=0, limit=20):
        items = [_operation_summary(operation.inspect()) for operation in workflow.buyer.list_operations()]
        if offset > len(items):
            raise StateError("AGENT_RECORD_PAGE_INVALID")
        page = items[offset:offset + limit]
        return {"operations": page, "total": len(items), "offset": offset,
                "next_offset": offset + len(page) if offset + len(page) < len(items) else None}

    def operation(intent_id):
        return _operation_summary(workflow.buyer.operation(intent_id).inspect())

    def runs(offset=0, limit=20):
        items = list(workflow.list_runs())
        if offset > len(items):
            raise StateError("AGENT_RECORD_PAGE_INVALID")
        page = items[offset:offset + limit]
        return {"runs": page, "total": len(items), "offset": offset,
                "next_offset": offset + len(page) if offset + len(page) < len(items) else None}

    def register(run_id, intent_id, format="auto", allow_partial=False):
        return workflow.register(run_id, intent_id=intent_id, format=format,
                                 allow_partial=allow_partial,
                                 file_options=file_options.get(intent_id))

    return [
        tool("operations", "List retained original Buyer intents and delivery state; no network call.",
             PageArguments, operations),
        tool("operation", "Inspect one retained original intent, request route and native delivery state.",
             IntentArguments, operation),
        tool("runs", "List persistent customer graph runs and their pending decisions.", PageArguments, runs),
        tool("register", "Bind a stable customer run to an existing original intent and a response format. "
             "The same identifier reopens the same binding. Use paid-file for its native product delivery.",
             RegisterArguments, register),
        tool("start", "Start or reopen the customer workflow. Recover completed original data first; "
             "a prepared intent returns its exact native review for selection before execution.",
             RunArguments, workflow.start),
        tool("inspect", "Read saved graph status, native outcome and the current review or recovery interruption.",
             RunArguments, workflow.inspect),
        tool("resume", "Continue a pending customer decision. Execute uses the exact selected review key "
             "and original configured payment/operator authority. Recover reopens the same original "
             "attempt or retained transfer. Cancel ends this customer graph.", ResumeArguments, workflow.resume),
        tool("read", "Read a page of verified retained JSON, CSV, NDJSON, SSE events or file metadata. "
             "Reading never repeats the request. Complete=false preserves a selected interrupted prefix.",
             ReadArguments, workflow.read),
        tool("export", "Copy the retained response, original native receipt and typed records into the private "
             "customer handoff directory. Return file and manifest digests; repeated calls reopen it.",
             RunArguments, workflow.export),
    ]

"""Persistent agent customer workflows over the original Buyer and readers.

The graph checkpoints application progress. Original Buyer intents, reviews,
attempts, file transfers and response receipts remain the effect authority.
Optional framework imports occur only when a CustomerWorkflow is opened.
"""
from __future__ import annotations

from contextlib import contextmanager
from dataclasses import asdict
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import shutil
import sqlite3
import stat
import tempfile
from typing import TypedDict
from urllib.parse import urlsplit, urlunsplit

from .client import Buyer, Review, intent
from .errors import BuyerError, DeliveryError, StateError
from .storage import digest, dump, lock, parse, private_directory, read, sync_directory, write
from .streams import StreamDelivery, export_saved_stream

SCHEMA = "stellar-forge.agent-workflow.v1"
ARTIFACT_SCHEMA = "stellar-forge.agent-artifact.v1"
FORMATS = {"auto", "json", "csv", "binary", "sse", "ndjson", "paid-file"}
MAX_EXPORT_BYTES = 256 * 1024 * 1024


def _json(value):
    return (json.dumps(value, sort_keys=True, ensure_ascii=True, allow_nan=False,
                       separators=(",", ":")) + "\n").encode("utf-8")


def _time():
    return datetime.now(timezone.utc).isoformat()


def _error(error):
    return {"code": getattr(error, "code", None) or type(error).__name__,
            "returncode": getattr(error, "returncode", None)}


def _url(value):
    """Model-visible route; credentials and query values stay in native state."""
    try:
        parsed = urlsplit(value or "")
        host = parsed.hostname or ""
        if ":" in host:
            host = "[" + host + "]"
        if parsed.port:
            host += ":" + str(parsed.port)
        return {"url": urlunsplit((parsed.scheme, host, parsed.path, "", "")),
                "query_present": bool(parsed.query)}
    except ValueError:
        return {"url": "", "query_present": False}


def _review_summary(review):
    native = review.native
    return {"intent_id": review.intent_id, "configuration_sha256": review.config_sha256,
            "body_sha256": review.body_sha256, "body_bytes": native.get("bodyBytes"),
            "method": native.get("method"), **_url(native.get("sellerUrl")),
            "terms": native.get("acceptedTerms"), "request_timeout_ms": native.get("requestTimeoutMs"),
            "file_promise": review.file_promise,
            "operation_ticket_sha256": review.operation_ticket_sha256}


def _file(path, *, name, content_type=None):
    path = Path(path)
    checksum = hashlib.sha256()
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
    with os.fdopen(fd, "rb") as source:
        info = os.fstat(source.fileno())
        if not stat.S_ISREG(info.st_mode):
            raise DeliveryError("ARTIFACT_FILE_TYPE_INVALID")
        total = 0
        while data := source.read(65536):
            checksum.update(data)
            total += len(data)
        if total != info.st_size:
            raise DeliveryError("ARTIFACT_FILE_CHANGED")
    return {"name": name, "path": str(path), "bytes": total, "sha256": checksum.hexdigest(),
            "content_type": content_type}


@contextmanager
def _open_file(metadata):
    """Hash the retained file before exposing that same descriptor."""
    fd = os.open(metadata["path"], os.O_RDONLY | os.O_NOFOLLOW)
    with os.fdopen(fd, "rb") as source:
        info = os.fstat(source.fileno())
        if not stat.S_ISREG(info.st_mode) or info.st_size != metadata["bytes"]:
            raise DeliveryError("ARTIFACT_FILE_CHANGED")
        checksum = hashlib.sha256()
        while data := source.read(65536):
            checksum.update(data)
        if checksum.hexdigest() != metadata["sha256"]:
            raise DeliveryError("ARTIFACT_FILE_CHANGED")
        source.seek(0)
        yield source


def _pointer(value, pointer):
    if not pointer:
        return value
    if not isinstance(pointer, str) or not pointer.startswith("/"):
        raise StateError("JSON_POINTER_REQUIRED")
    for part in pointer[1:].split("/"):
        index = 0
        while index < len(part):
            if part[index] == "~":
                if index + 1 == len(part) or part[index + 1] not in "01":
                    raise StateError("JSON_POINTER_INVALID")
                index += 1
            index += 1
        part = part.replace("~1", "/").replace("~0", "~")
        try:
            if isinstance(value, list):
                if not part.isdigit() or (len(part) > 1 and part.startswith("0")):
                    raise ValueError()
                value = value[int(part)]
            elif isinstance(value, dict):
                value = value[part]
            else:
                raise ValueError()
        except (KeyError, IndexError, ValueError):
            raise StateError("JSON_POINTER_NOT_FOUND") from None
    return value


def _read_artifact(artifact, *, offset=0, limit=20, pointer="", event_json=False):
    if type(offset) is not int or offset < 0 or type(limit) is not int or not 1 <= limit <= 100:
        raise StateError("AGENT_RECORD_PAGE_INVALID")
    files = {item["name"]: item for item in artifact["files"]}
    format = artifact["format"]
    if type(event_json) is not bool or (event_json and format != "sse"):
        raise StateError("EVENT_JSON_REQUIRES_SSE")
    if format in ("binary", "paid-file"):
        with _open_file(files["response.bin"]):
            pass
        return {"format": format, "complete": artifact["complete"], "file": files["response.bin"]}
    if format == "json":
        with _open_file(files["data.json"]) as source:
            value = _pointer(parse(source.read()), pointer)
        if isinstance(value, list):
            if offset > len(value):
                raise StateError("AGENT_RECORD_PAGE_INVALID")
            selected = value[offset:offset + limit]
            return {"format": format, "pointer": pointer, "offset": offset, "records": selected,
                    "total": len(value), "next_offset": offset + len(selected) if offset + len(selected) < len(value) else None}
        if offset:
            raise StateError("AGENT_RECORD_PAGE_INVALID")
        return {"format": format, "pointer": pointer, "value": value, "next_offset": None}
    count = artifact["records"]
    if offset > count:
        raise StateError("AGENT_RECORD_PAGE_INVALID")
    selected = []
    if format in ("sse", "ndjson"):
        stream = StreamDelivery(Path(files["records.jsonl"]["path"]).parent, artifact["stream_manifest"])
        records = stream.records(start=offset)
        try:
            for record in records:
                if len(selected) == limit:
                    break
                if format == "sse":
                    if event_json:
                        value = {"index": record.index, "event": record.event, "id": record.id,
                                 "value": _pointer(record.json(), pointer)}
                    else:
                        value = asdict(record) if not pointer else {
                            "index": record.index, "value": _pointer(asdict(record), pointer)}
                else:
                    value = {"index": record.index, "value": _pointer(record.value, pointer)}
                selected.append(value)
        finally:
            records.close()
    else:
        with _open_file(files["records.jsonl"]) as source:
            for index, raw in enumerate(source):
                if index < offset:
                    continue
                if len(selected) == limit:
                    break
                value = parse(raw)
                if value.get("index") != index:
                    raise DeliveryError("AGENT_RECORD_INDEX_CHANGED")
                selected.append({"index": index, "value": _pointer(value["value"], pointer)})
    return {"format": format, "complete": artifact["complete"], "offset": offset, "records": selected,
            "total": count, "next_offset": offset + len(selected) if offset + len(selected) < count else None}


class _State(TypedDict, total=False):
    run_id: str
    status: str
    review_key: str | None
    review: dict | None
    action: str | None
    error: dict | None
    native: dict | None
    artifact: dict | None


class CustomerWorkflow:
    """One persistent LangGraph customer application using an existing Buyer.

    Registration selects an existing original intent, or an original SF31
    response-writer receipt. It never creates or replaces a payment attempt.
    Native request preparation remains available through ``workflow.buyer``.
    """

    def __init__(self, buyer: Buyer, *, directory=None):
        try:
            from langgraph.checkpoint.sqlite import SqliteSaver
            from langgraph.graph import END, START, StateGraph
            from langgraph.types import Command, interrupt
        except ImportError:
            raise StateError("INSTALL_STELLAR_FORGE_BUYER_AGENTS_EXTRA") from None
        self.buyer = buyer
        self.directory = private_directory(Path(directory) if directory else buyer.state_dir / "agents")
        self.runs = private_directory(self.directory / "runs")
        self.Command, self.interrupt = Command, interrupt
        binding = {"schema": SCHEMA, "buyer_state": str(buyer.state_dir)}
        with lock(self.directory):
            identity = self.directory / "workspace.json"
            if identity.exists():
                if parse(read(identity, 65536)) != binding:
                    raise StateError("AGENT_WORKSPACE_BUYER_CHANGED")
            else:
                dump(identity, binding, exclusive=True)
            database = self.directory / "checkpoints.sqlite3"
            fd = os.open(database, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
            try:
                info = os.fstat(fd)
                if not stat.S_ISREG(info.st_mode) or info.st_mode & 0o077:
                    raise StateError("PRIVATE_CHECKPOINT_FILE_REQUIRED")
            finally:
                os.close(fd)
            self.connection = sqlite3.connect(str(database), timeout=30, check_same_thread=False)
            self.connection.execute("PRAGMA synchronous=FULL")
            self.checkpointer = SqliteSaver(self.connection)
            self.checkpointer.setup()
        graph = StateGraph(_State)
        graph.add_node("assess", self._assess)
        graph.add_node("review", self._decision)
        graph.add_node("execute", self._execute)
        graph.add_node("consume", self._consume)
        graph.add_node("recover", self._recovery)
        graph.add_edge(START, "assess")
        graph.add_conditional_edges("assess", lambda s: s["status"], {
            "REVIEW_REQUIRED": "review", "CONSUMING": "consume", "RECOVERY_REQUIRED": "recover"})
        graph.add_conditional_edges("review", lambda s: s["status"], {
            "EXECUTING": "execute", "CANCELLED": END})
        graph.add_conditional_edges("execute", lambda s: s["status"], {
            "CONSUMING": "consume", "RECOVERY_REQUIRED": "recover"})
        graph.add_conditional_edges("consume", lambda s: s["status"], {
            "AVAILABLE": END, "RECOVERY_REQUIRED": "recover"})
        graph.add_conditional_edges("recover", lambda s: s["status"], {
            "ASSESSING": "assess", "CANCELLED": END})
        self.graph = graph.compile(checkpointer=self.checkpointer)

    def close(self):
        self.connection.close()

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()

    def _directory(self, run_id):
        return self.runs / digest(intent(run_id).encode("utf-8"))

    def _record(self, run_id):
        directory = private_directory(self._directory(run_id), create=False)
        value = parse(read(directory / "run.json", 4 * 1024 * 1024))
        if value.get("schema") != SCHEMA or value.get("run_id") != run_id:
            raise StateError("AGENT_RUN_IDENTITY_INVALID")
        return value

    def _config(self, run_id):
        # Explicit coordinates make this a separate checkpointed workflow when
        # invoked by a tool inside another LangGraph. Never merge an ambient
        # parent's configurable/__pregel_* values into this configuration.
        return {"configurable": {"thread_id": "stellar-forge:" + digest(run_id.encode("utf-8")),
                                  "checkpoint_ns": ""}, "recursion_limit": 32}

    def _register(self, run_id, source, options):
        record = {"schema": SCHEMA, "run_id": intent(run_id), "source": source, "options": options}
        directory = private_directory(self._directory(run_id))
        with lock(directory):
            path = directory / "run.json"
            if path.exists():
                if parse(read(path, 4 * 1024 * 1024)) != record:
                    raise StateError("AGENT_RUN_ALREADY_BOUND_TO_DIFFERENT_SOURCE")
            else:
                dump(path, record, exclusive=True)
                private_directory(directory / "reviews")
        return self.inspect(run_id)

    def register(self, run_id, *, intent_id, format="auto", allow_partial=False,
                 file_options=None, max_export_bytes=MAX_EXPORT_BYTES):
        if format not in FORMATS or type(allow_partial) is not bool:
            raise StateError("AGENT_CONSUMPTION_OPTIONS_INVALID")
        self._validate_limit(max_export_bytes)
        operation = self.buyer.operation(intent_id)
        operation.inspect()
        file_options = dict(file_options or {})
        if set(file_options) - {"destination", "claim_env", "timeout_ms"}:
            raise StateError("ORIGINAL_FILE_OPTIONS_INVALID")
        if "destination" in file_options:
            file_options["destination"] = os.path.abspath(os.path.expanduser(os.fspath(file_options["destination"])))
        return self._register(run_id, {"kind": "operation", "intent_id": intent_id}, {
            "format": format, "allow_partial": allow_partial, "file_options": file_options,
            "max_export_bytes": max_export_bytes})

    def register_saved_stream(self, run_id, *, response_file, saved, source=None,
                              allow_partial=False, max_export_bytes=MAX_EXPORT_BYTES):
        if not isinstance(response_file, dict) or not isinstance(saved, dict) or type(allow_partial) is not bool:
            raise StateError("ORIGINAL_RESPONSE_FILE_REQUIRED")
        self._validate_limit(max_export_bytes)
        format = (response_file.get("stream") or saved.get("stream") or {}).get("format")
        if format not in ("sse", "ndjson"):
            raise StateError("ORIGINAL_STREAM_FORMAT_REQUIRED")
        return self._register(run_id, {"kind": "native-stream", "response_file": response_file,
            "saved": saved, "provenance": source}, {"format": format, "allow_partial": allow_partial,
            "file_options": {}, "max_export_bytes": max_export_bytes})

    @staticmethod
    def _validate_limit(value):
        if type(value) is not int or not 1 <= value <= 1024 * 1024 * 1024:
            raise StateError("AGENT_EXPORT_BYTE_LIMIT_INVALID")

    def _snapshot(self, run_id):
        snapshot = self.graph.get_state(self._config(run_id))
        pending = []
        for task in snapshot.tasks:
            for item in task.interrupts:
                pending.append({"id": item.id, "value": item.value})
        return snapshot, pending

    def inspect(self, run_id):
        record = self._record(run_id)
        snapshot, pending = self._snapshot(run_id)
        return {"schema": SCHEMA, "run_id": run_id, "source_kind": record["source"]["kind"],
                "intent_id": record["source"].get("intent_id"),
                **dict(snapshot.values), "status": snapshot.values.get("status", "REGISTERED"),
                "pending": pending, "next": list(snapshot.next),
                "checkpoint_id": snapshot.config.get("configurable", {}).get("checkpoint_id") if snapshot.config else None}

    def list_runs(self):
        for directory in sorted(self.runs.iterdir()):
            if directory.is_dir() and (directory / "run.json").is_file():
                record = parse(read(directory / "run.json", 4 * 1024 * 1024))
                yield self.inspect(record["run_id"])

    def start(self, run_id):
        self._record(run_id)
        with lock(self._directory(run_id)):
            snapshot, pending = self._snapshot(run_id)
            if not snapshot.values:
                self.graph.invoke({"run_id": run_id, "status": "ASSESSING"}, self._config(run_id), durability="sync")
            elif snapshot.next and not pending:
                self.graph.invoke(None, self._config(run_id), durability="sync")
        return self.inspect(run_id)

    def resume(self, run_id, *, action="recover", review_key=None):
        self._record(run_id)
        with lock(self._directory(run_id)):
            snapshot, pending = self._snapshot(run_id)
            if not pending:
                if action != "recover":
                    raise StateError("AGENT_RUN_HAS_NO_PENDING_DECISION")
                if snapshot.next:
                    self.graph.invoke(None, self._config(run_id), durability="sync")
            else:
                if len(pending) != 1:
                    raise StateError("AGENT_PENDING_DECISION_COUNT_INVALID")
                kind = pending[0]["value"]["kind"]
                allowed = {"execute", "cancel"} if kind == "original-review" else {"recover", "review", "cancel"}
                if action not in allowed:
                    raise StateError("AGENT_DECISION_INVALID")
                if action == "execute" and review_key != snapshot.values.get("review_key"):
                    raise StateError("ORIGINAL_REVIEW_SELECTION_CHANGED")
                self.graph.invoke(self.Command(resume={"action": action, "review_key": review_key}),
                                 self._config(run_id), durability="sync")
        return self.inspect(run_id)

    def _assess(self, state):
        record = self._record(state["run_id"])
        if record["source"]["kind"] == "native-stream":
            return {"status": "CONSUMING", "error": None}
        operation = self.buyer.operation(record["source"]["intent_id"])
        try:
            if record["options"]["format"] == "paid-file" and operation.recover_file() is not None:
                return {"status": "CONSUMING", "error": None}
            result = operation.recover()
            if result is not None:
                return {"status": "CONSUMING", "error": None}
            inspected = operation.inspect()
            if inspected["state"] != "PREPARED":
                return {"status": "RECOVERY_REQUIRED", "error": {"code": "ORIGINAL_ATTEMPT_RESULT_NOT_YET_RECORDED"},
                        "native": {"state": inspected["state"]}}
            review = operation.review()
            raw = _json(asdict(review))
            key = digest(raw)
            path = self._directory(state["run_id"]) / "reviews" / (key + ".json")
            if not path.exists():
                write(path, raw, exclusive=True)
            return {"status": "REVIEW_REQUIRED", "review_key": key,
                    "review": _review_summary(review), "error": None}
        except BuyerError as error:
            return {"status": "RECOVERY_REQUIRED", "error": _error(error)}

    def _decision(self, state):
        # This entire node restarts on resume. All native review/prepare work is
        # in the preceding checkpointed node; no effect occurs before interrupt.
        answer = self.interrupt({"kind": "original-review", "run_id": state["run_id"],
                                 "review_key": state["review_key"], "review": state["review"]})
        if answer["action"] == "cancel":
            return {"status": "CANCELLED", "action": "cancel"}
        if answer["action"] != "execute" or answer.get("review_key") != state["review_key"]:
            raise StateError("ORIGINAL_REVIEW_SELECTION_CHANGED")
        return {"status": "EXECUTING", "action": "execute"}

    def _execute(self, state):
        record = self._record(state["run_id"])
        operation = self.buyer.operation(record["source"]["intent_id"])
        try:
            # A node may restart after the native process finished but before
            # LangGraph checkpointed. Recover the same original result first.
            result = operation.recover()
            if result is None:
                inspected = operation.inspect()
                if inspected["state"] != "PREPARED":
                    return {"status": "RECOVERY_REQUIRED", "error": {"code": "ORIGINAL_ATTEMPT_RESULT_NOT_YET_RECORDED"}}
                raw = read(self._directory(state["run_id"]) / "reviews" / (state["review_key"] + ".json"), 4 * 1024 * 1024)
                if digest(raw) != state["review_key"]:
                    raise StateError("ORIGINAL_REVIEW_SNAPSHOT_CHANGED")
                result = operation.execute(review=Review(**parse(raw)))
            return {"status": "CONSUMING", "error": None}
        except BuyerError as error:
            return {"status": "RECOVERY_REQUIRED", "error": _error(error)}

    def _recovery(self, state):
        answer = self.interrupt({"kind": "original-recovery", "run_id": state["run_id"],
                                 "error": state.get("error"), "native": state.get("native"),
                                 "actions": ["recover", "review", "cancel"]})
        if answer["action"] not in ("recover", "review", "cancel"):
            raise StateError("AGENT_DECISION_INVALID")
        return {"status": "CANCELLED" if answer["action"] == "cancel" else "ASSESSING",
                "action": answer["action"]}

    def _artifact(self, run_id):
        directory = self._directory(run_id) / "artifact"
        value = parse(read(directory / "manifest.json", 4 * 1024 * 1024))
        if (value.get("schema") != ARTIFACT_SCHEMA or value.get("run_id") != run_id
                or value.get("run_sha256") != digest(_json(self._record(run_id)))):
            raise DeliveryError("AGENT_ARTIFACT_BINDING_CHANGED")
        return value

    def _consume(self, state):
        run_id = state["run_id"]
        record = self._record(run_id)
        directory = self._directory(run_id) / "artifact"
        try:
            if (directory / "manifest.json").exists():
                artifact = self._artifact(run_id)
            else:
                artifact = self._create_artifact(run_id, record)
            return {"status": "AVAILABLE", "error": None, "native": artifact["native"],
                    "artifact": {key: artifact[key] for key in ("format", "complete", "records", "generated_at")}}
        except (BuyerError, OSError) as error:
            return {"status": "RECOVERY_REQUIRED", "error": _error(error)}

    def _create_artifact(self, run_id, record):
        run_directory = self._directory(run_id)
        temporary = Path(tempfile.mkdtemp(prefix=".artifact-", dir=run_directory))
        destination = run_directory / "artifact"
        source, options = record["source"], record["options"]
        maximum = options["max_export_bytes"]
        files = []
        stream = None
        try:
            if source["kind"] == "native-stream":
                stream = export_saved_stream(checkout=self.buyer.runtime.checkout,
                    response_file=source["response_file"], saved=source["saved"],
                    cache_dir=run_directory / "native-stream", node=self.buyer.runtime.node,
                    timeout=self.buyer.runtime.timeout, allow_partial=options["allow_partial"],
                    max_export_bytes=maximum)
                native_record = {"source_kind": "SF31_RESPONSE_FILE", "responseFile": source["saved"],
                                 "source": source.get("provenance")}
                native = {"source_kind": "SF31_RESPONSE_FILE", "status": source["saved"].get("status"),
                          "error": source["saved"].get("error")}
                original = source["saved"]
                format = stream.format
                result = None
            else:
                operation = self.buyer.operation(source["intent_id"])
                format = options["format"]
                delivered_file = operation.recover_file() if format == "paid-file" else None
                result = operation.recover()
                if result is None and delivered_file is None:
                    raise StateError("ORIGINAL_ATTEMPT_RESULT_NOT_YET_RECORDED")
                native_record = result.record if result is not None else None
                native = {"source_kind": "ORIGINAL_BUYER_OPERATION" if result is not None else "ORIGINAL_FILE_DELIVERY",
                          "intent_id": operation.intent_id, "purchase_attempt_recorded": result is not None}
                if result is not None:
                    native.update(status=result.status, http_status=result.native.get("httpStatus"),
                                  returncode=result.record.get("returncode"),
                                  runtime_error=result.record.get("runtimeError"), ok=result.ok,
                                  configuration_sha256=result.record.get("configSha256"))
                if format == "paid-file":
                    result = delivered_file or operation.retrieve_file(resume=True, **options["file_options"])
                    native_record = {"purchase": native_record, "file_delivery": result.record}
                    native["file_delivery_status"] = result.status
                    native["file_http_requests"] = result.http_requests
                original = result.delivery
                if format == "auto":
                    content_type = (original.get("contentType") or "").split(";", 1)[0].strip().lower()
                    format = (original.get("stream") or {}).get("format") or (
                        "json" if content_type == "application/json" or content_type.endswith("+json") else
                        "csv" if content_type in ("text/csv", "application/csv") else "binary")
                if format in ("sse", "ndjson"):
                    stream = result.export_stream(format=format, allow_partial=options["allow_partial"],
                                                  max_export_bytes=maximum)
            dump(temporary / "native.json", native_record, exclusive=True)
            files.append(_file(temporary / "native.json", name="native.json", content_type="application/json"))
            count = None
            complete = original.get("status") == "SAVED"
            stream_manifest = None
            if stream is not None:
                # The native reader has validated full retained bytes, framing,
                # and the published prefix before the typed export is returned.
                stream_manifest = stream.manifest
                complete, count = stream.complete, stream.count
                files.append({"name": "records.jsonl", "path": str(stream.directory / "records.jsonl"),
                              "bytes": stream.manifest["file"]["bytes"], "sha256": stream.manifest["file"]["sha256"],
                              "content_type": "application/x-ndjson"})
                raw_source = stream.source
                files.append({"name": "response.bin", "path": raw_source["path"], "bytes": raw_source["bytes"],
                              "sha256": raw_source["sha256"], "content_type": raw_source.get("contentType")})
            else:
                with result.open():
                    pass
                files.append({"name": "response.bin", "path": original["path"], "bytes": original["bytes"],
                              "sha256": original["sha256"], "content_type": original.get("contentType")})
                if format == "json":
                    raw = _json(result.json(limit=min(result.max_bytes, maximum)))
                    if len(raw) > maximum:
                        raise DeliveryError("AGENT_EXPORT_BYTE_LIMIT_EXCEEDED")
                    write(temporary / "data.json", raw, exclusive=True)
                    files.append(_file(temporary / "data.json", name="data.json", content_type="application/json"))
                elif format == "csv":
                    count = 0
                    with (temporary / "records.jsonl").open("xb") as target:
                        os.chmod(target.name, 0o600)
                        total = 0
                        for index, row in enumerate(result.csv_rows()):
                            raw = _json({"index": index, "value": row})
                            total += len(raw)
                            if total > maximum:
                                raise DeliveryError("AGENT_EXPORT_BYTE_LIMIT_EXCEEDED")
                            target.write(raw)
                            count += 1
                        target.flush()
                        os.fsync(target.fileno())
                    files.append(_file(temporary / "records.jsonl", name="records.jsonl", content_type="application/x-ndjson"))
            for item in files:
                if Path(item["path"]).parent == temporary:
                    item["path"] = str(destination / Path(item["path"]).name)
            manifest = {"schema": ARTIFACT_SCHEMA, "run_id": run_id, "run_sha256": digest(_json(record)),
                        "format": format, "complete": complete, "records": count, "native": native,
                        "generated_at": _time(), "files": files, "stream_manifest": stream_manifest}
            dump(temporary / "manifest.json", manifest, exclusive=True)
            os.rename(temporary, destination)
            sync_directory(run_directory)
            return manifest
        finally:
            if temporary.exists():
                shutil.rmtree(temporary)

    def read(self, run_id, *, offset=0, limit=20, pointer="", event_json=False):
        return _read_artifact(self._artifact(run_id), offset=offset, limit=limit,
                              pointer=pointer, event_json=event_json)

    def export(self, run_id, destination=None):
        artifact = self._artifact(run_id)
        identity = digest(_json(artifact))
        parent = private_directory(self._directory(run_id) / "deliveries")
        target = Path(os.path.abspath(os.path.expanduser(os.fspath(destination)))) if destination else parent / identity
        if target.exists():
            delivery = CustomerDelivery.open(target)
            saved = delivery.manifest
            if saved.get("artifact_sha256") != identity:
                raise StateError("AGENT_DELIVERY_DESTINATION_ALREADY_EXISTS")
            return {**saved, "manifest_sha256": delivery.manifest_sha256,
                    "directory": str(delivery.directory), "reused": True}
        private_directory(target.parent, create=False)
        temporary = Path(tempfile.mkdtemp(prefix=".delivery-", dir=target.parent))
        try:
            files = []
            for item in artifact["files"]:
                path = temporary / item["name"]
                with _open_file(item) as source:
                    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
                    with os.fdopen(fd, "wb") as output:
                        shutil.copyfileobj(source, output, 65536)
                        output.flush()
                        os.fsync(output.fileno())
                files.append({key: value for key, value in item.items() if key != "path"})
            manifest = {"schema": "stellar-forge.agent-delivery.v1", "run_id": run_id,
                        "artifact_sha256": identity, "format": artifact["format"], "complete": artifact["complete"],
                        "records": artifact["records"], "native": artifact["native"], "files": files,
                        "stream_manifest": artifact["stream_manifest"], "source_manifest": artifact,
                        "generated_at": artifact["generated_at"]}
            dump(temporary / "delivery.json", manifest, exclusive=True)
            os.rename(temporary, target)
            sync_directory(target.parent)
            return {**manifest, "manifest_sha256": digest(read(target / "delivery.json", 4 * 1024 * 1024)),
                    "directory": str(target), "reused": False}
        finally:
            if temporary.exists():
                shutil.rmtree(temporary)


class CustomerDelivery:
    """Portable retained data; reopening needs neither Node nor LangGraph.

    The optional expected manifest digest binds the exact package chosen by its
    sender. Source/record hashes detect changed files; they do not identify a
    trusted sender on their own. Original native status is retained separately
    from whether a response or its explicit complete-record prefix is readable.
    """

    def __init__(self, directory, manifest, manifest_sha256):
        self.directory = directory
        self.manifest = manifest
        self.manifest_sha256 = manifest_sha256
        self.artifact = {**manifest["source_manifest"], "files": [
            {**item, "path": str(directory / item["name"])} for item in manifest["files"]]}

    @classmethod
    def open(cls, directory, *, expected_manifest_sha256=None):
        root = private_directory(Path(directory), create=False)
        raw = read(root / "delivery.json", 4 * 1024 * 1024)
        fingerprint = digest(raw)
        if expected_manifest_sha256 is not None and fingerprint != expected_manifest_sha256:
            raise DeliveryError("AGENT_DELIVERY_MANIFEST_CHANGED")
        value = parse(raw)
        if not isinstance(value, dict):
            raise DeliveryError("AGENT_DELIVERY_MANIFEST_INVALID")
        source = value.get("source_manifest")
        if (value.get("schema") != "stellar-forge.agent-delivery.v1" or not isinstance(source, dict)
                or source.get("schema") != ARTIFACT_SCHEMA
                or digest(_json(source)) != value.get("artifact_sha256")
                or any(value.get(key) != source.get(key) for key in
                       ("run_id", "format", "complete", "records", "native", "stream_manifest", "generated_at"))):
            raise DeliveryError("AGENT_DELIVERY_MANIFEST_INVALID")
        files = value.get("files")
        originals = source.get("files")
        if (not isinstance(files, list) or not isinstance(originals, list)
                or not 2 <= len(files) <= 4 or len(files) != len(originals)):
            raise DeliveryError("AGENT_DELIVERY_MANIFEST_INVALID")
        seen = set()
        for item, original in zip(files, originals):
            if (not isinstance(item, dict) or not isinstance(original, dict)
                    or item != {key: val for key, val in original.items() if key != "path"}
                    or item.get("name") not in {"native.json", "response.bin", "records.jsonl", "data.json"}
                    or item["name"] in seen or type(item.get("bytes")) is not int or item["bytes"] < 0):
                raise DeliveryError("AGENT_DELIVERY_MANIFEST_INVALID")
            seen.add(item["name"])
            with _open_file({**item, "path": str(root / item["name"])}):
                pass
        required = {"native.json", "response.bin"}
        if value["format"] == "json":
            required.add("data.json")
        elif value["format"] in {"csv", "sse", "ndjson"}:
            required.add("records.jsonl")
        elif value["format"] not in {"binary", "paid-file"}:
            raise DeliveryError("AGENT_DELIVERY_MANIFEST_INVALID")
        if seen != required:
            raise DeliveryError("AGENT_DELIVERY_MANIFEST_INVALID")
        return cls(root, value, fingerprint)

    def read(self, *, offset=0, limit=20, pointer="", event_json=False):
        return _read_artifact(self.artifact, offset=offset, limit=limit,
                              pointer=pointer, event_json=event_json)

    def metadata(self):
        return {key: self.manifest[key] for key in
                ("schema", "run_id", "format", "complete", "records", "native", "artifact_sha256")}


def main(argv=None):
    """The installed CLI drives the same graph and portable data reader."""
    import argparse
    parser = argparse.ArgumentParser(description="Persistent customer workflow on the original Stellar Forge Buyer")
    parser.add_argument("--checkout", help="Original Stellar Forge checkout root")
    parser.add_argument("--state", help="Existing private Python Buyer state directory")
    parser.add_argument("--directory", help="Private graph/checkpoint directory; defaults to STATE/agents")
    parser.add_argument("--node", default="node")
    parser.add_argument("--timeout", type=int, default=360, help="Native parent process timeout in seconds")
    commands = parser.add_subparsers(dest="command", required=True)
    register = commands.add_parser("register", help="Bind an existing original intent to a stable customer run")
    register.add_argument("run_id")
    register.add_argument("intent_id")
    register.add_argument("--format", choices=sorted(FORMATS), default="auto")
    register.add_argument("--allow-partial", action="store_true")
    register.add_argument("--file-options", help="JSON with original destination/claim_env/timeout_ms options")
    attach = commands.add_parser("attach-stream", help="Register an actual retained native SF31 writer response")
    attach.add_argument("run_id")
    attach.add_argument("native_response", help="JSON containing writerOptions, responseFile and optional source")
    attach.add_argument("--allow-partial", action="store_true")
    for name in ("start", "inspect"):
        commands.add_parser(name).add_argument("run_id")
    commands.add_parser("list")
    resume = commands.add_parser("resume")
    resume.add_argument("run_id")
    resume.add_argument("--action", choices=("execute", "recover", "review", "cancel"), default="recover")
    resume.add_argument("--review-key")
    read_command = commands.add_parser("read")
    read_command.add_argument("run_id")
    delivery = commands.add_parser("read-delivery", help="Read an exported package without Node, Buyer or LangGraph")
    delivery.add_argument("delivery")
    delivery.add_argument("--manifest-sha256")
    for command in (read_command, delivery):
        command.add_argument("--offset", type=int, default=0)
        command.add_argument("--limit", type=int, default=20)
        command.add_argument("--pointer", default="")
        command.add_argument("--event-json", action="store_true")
    export = commands.add_parser("export")
    export.add_argument("run_id")
    export.add_argument("--destination")
    arguments = parser.parse_args(argv)
    try:
        if arguments.command == "read-delivery":
            customer = CustomerDelivery.open(arguments.delivery,
                expected_manifest_sha256=arguments.manifest_sha256)
            result = {"delivery": customer.metadata(), "manifest_sha256": customer.manifest_sha256,
                      "page": customer.read(offset=arguments.offset, limit=arguments.limit,
                                            pointer=arguments.pointer, event_json=arguments.event_json)}
        else:
            if not arguments.checkout or not arguments.state:
                parser.error("--checkout and --state are required for a customer graph")
            buyer = Buyer(checkout=arguments.checkout, state_dir=arguments.state,
                          node=arguments.node, timeout=arguments.timeout)
            with CustomerWorkflow(buyer, directory=arguments.directory) as workflow:
                command = arguments.command
                if command == "register":
                    options = parse(read(Path(arguments.file_options), 65536)) if arguments.file_options else None
                    result = workflow.register(arguments.run_id, intent_id=arguments.intent_id,
                        format=arguments.format, allow_partial=arguments.allow_partial, file_options=options)
                elif command == "attach-stream":
                    response = parse(read(Path(arguments.native_response), 4 * 1024 * 1024))
                    result = workflow.register_saved_stream(arguments.run_id,
                        response_file=response["writerOptions"], saved=response["responseFile"],
                        source=response.get("source"), allow_partial=arguments.allow_partial)
                elif command == "list":
                    result = {"runs": list(workflow.list_runs())}
                elif command == "resume":
                    result = workflow.resume(arguments.run_id, action=arguments.action,
                                             review_key=arguments.review_key)
                elif command == "read":
                    result = workflow.read(arguments.run_id, offset=arguments.offset, limit=arguments.limit,
                                           pointer=arguments.pointer, event_json=arguments.event_json)
                elif command == "export":
                    result = workflow.export(arguments.run_id, arguments.destination)
                else:
                    result = getattr(workflow, command)(arguments.run_id)
        print(json.dumps(result, ensure_ascii=True, allow_nan=False, indent=2))
        return 0
    except (BuyerError, OSError, KeyError) as error:
        print(json.dumps({"status": "ERROR", "error": _error(error)}))
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

"""Complete SQL exports operated by the existing analysis workspace job owner."""
from __future__ import annotations

from contextlib import contextmanager
from datetime import datetime, timezone
import io
import json
from pathlib import Path
import re
import threading

from .errors import BuyerError, StateError
from .query_export import QueryExport
from .storage import digest, dump, parse, private_directory, read

_SCHEMA = "stellar-forge.analysis-query-export.v1"
_CONTROL = "stellar-forge.analysis-query-export-control.v1"
_ID = re.compile(r"[a-f0-9]{32}")
_SHA = re.compile(r"[a-f0-9]{64}")
_FORMATS = {"jsonl": "rows.jsonl", "csv": "rows.csv", "sqlite": "rows.sqlite3"}
_MIMES = {"rows.jsonl": "application/x-ndjson", "rows.csv": "text/csv;charset=utf-8",
          "rows.sqlite3": "application/vnd.sqlite3", "manifest.json": "application/json"}


def _now():
    return datetime.now(timezone.utc).isoformat()


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"))


def _identifier(value):
    if not isinstance(value, str) or not _ID.fullmatch(value):
        raise StateError("ANALYSIS_EXPORT_ID_INVALID")
    return value


class AnalysisExports:
    """Use original jobs, query reviews, native exporter and retained-file reader.

    Progress and cancellation use small private control files. They never write
    to the analytical SQLite database while its export read transaction is open.
    The workspace's existing single executor remains the only dispatch owner.
    """

    def __init__(self, database, *, identity, read_job, parse_parameters):
        self.database, self.identity = database, identity
        self.read_job, self.parse_parameters = read_job, parse_parameters
        self.directory = private_directory(database.directory / "analysis-query-exports")
        self.controls = private_directory(self.directory / "control")
        self._mutex = threading.RLock()
        self._signals = {}
        self._observations = {}
        self._closed = False

    def prepare(self, request):
        allowed = {"id", "query_id", "result_sha256", "label", "formats", "timeout",
                   "max_rows", "max_output_bytes", "spreadsheet_safe"}
        if set(request) - allowed:
            raise StateError("ANALYSIS_EXPORT_FIELDS_INVALID")
        query_id = _identifier(request.get("query_id"))
        checksum = request.get("result_sha256")
        if not isinstance(checksum, str) or not _SHA.fullmatch(checksum):
            raise StateError("ANALYSIS_EXPORT_REVIEW_DIGEST_REQUIRED")
        label = request.get("label", "")
        if not isinstance(label, str) or len(label) > 160 or any(ord(c) < 32 for c in label):
            raise StateError("ANALYSIS_EXPORT_LABEL_INVALID")
        formats = request.get("formats", list(_FORMATS))
        if (not isinstance(formats, list) or not formats
                or any(not isinstance(v, str) or v not in _FORMATS for v in formats)
                or len(set(formats)) != len(formats)):
            raise StateError("QUERY_EXPORT_OPTIONS_INVALID")
        timeout = request.get("timeout", 300)
        if type(timeout) not in (int, float) or not 0 < timeout <= 86400:
            raise StateError("ANALYSIS_EXPORT_TIMEOUT_INVALID")
        limits = {key: request.get(key) for key in ("max_rows", "max_output_bytes")}
        if any(value is not None and (type(value) is not int or value < 1) for value in limits.values()):
            raise StateError("QUERY_EXPORT_OPTIONS_INVALID")
        safe = request.get("spreadsheet_safe", True)
        if type(safe) is not bool:
            raise StateError("QUERY_EXPORT_OPTIONS_INVALID")
        spec = {"query_id": query_id, "result_sha256": checksum, "label": label.strip(),
                "formats": formats, "timeout": timeout, **limits, "spreadsheet_safe": safe}
        self._review(spec)
        return spec

    def _review(self, spec):
        # _job returns the full, digest-checked original result before paging.
        job = self.read_job(spec["query_id"])
        if job["kind"] != "query" or job["status"] != "COMPLETE":
            raise StateError("ANALYSIS_EXPORT_COMPLETE_QUERY_REQUIRED")
        if job["result"].get("result_sha256") != spec["result_sha256"]:
            raise StateError("ANALYSIS_EXPORT_REVIEW_CHANGED")
        return job

    def _record(self, job_id):
        job_id = _identifier(job_id)
        with self.database._connection(readonly=True) as db:
            row = db.execute("SELECT * FROM sf_analysis_jobs WHERE id=? AND kind='query-export'", (job_id,)).fetchone()
        if row is None:
            raise StateError("ANALYSIS_EXPORT_NOT_FOUND")
        item = dict(row)
        item["request"] = parse(item["request"].encode())
        item["result"] = parse(item["result"].encode()) if item["result"] else None
        return item

    def _control(self, job_id):
        with self._mutex:
            if job_id not in self._observations:
                path = self.controls / (job_id + ".json")
                if path.exists():
                    value = parse(read(path, 16384))
                    if (value.get("schema") != _CONTROL or value.get("workspace_id") != self.identity
                            or value.get("id") != job_id):
                        raise StateError("ANALYSIS_EXPORT_CONTROL_CHANGED")
                else:
                    value = {"schema": _CONTROL, "workspace_id": self.identity, "id": job_id,
                             "rows": 0, "outputBytes": 0, "complete": False, "cancel_requested": False}
                self._observations[job_id] = value
            return dict(self._observations[job_id])

    def _progress(self, job_id, values):
        with self._mutex:
            value = self._control(job_id)
            value.update(values, updated_at=_now())
            dump(self.controls / (job_id + ".json"), value)
            self._observations[job_id] = value
            return dict(value)

    def progress(self, job_id):
        return {key: value for key, value in self._control(_identifier(job_id)).items()
                if key not in {"schema", "workspace_id", "id"}}

    def cancel(self, job_id):
        job = self._record(job_id)
        if job["status"] == "RUNNING":
            with self._mutex:
                self._signals.setdefault(job_id, threading.Event()).set()
                self._progress(job_id, {"cancel_requested": True})
        return self.read_job(job_id)

    def close(self):
        # Signal first; the original workspace then waits for its executor.
        with self._mutex:
            self._closed = True
            for job_id, signal in self._signals.items():
                signal.set()
                try:
                    self._progress(job_id, {"cancel_requested": True})
                except OSError:
                    pass

    def _completed(self, job_id, spec, review):
        result = QueryExport(self.directory / job_id)
        manifest = result.inspect()
        binding = manifest["binding"]
        expected = self.parse_parameters(review["request"]["parameters_text"])
        if (binding.get("sql") != review["request"]["sql"] or binding.get("parameters") != expected
                or binding.get("views") != review["result"]["views"]
                or set(manifest["outputs"]) != {_FORMATS[k] for k in spec["formats"]}
                or manifest.get("csv", {}).get("spreadsheetSafe") is not spec["spreadsheet_safe"]):
            raise StateError("ANALYSIS_EXPORT_BINDING_CHANGED")
        if (spec["max_rows"] is not None and manifest["rowCount"] > spec["max_rows"]
                or spec["max_output_bytes"] is not None
                and sum(v["bytes"] for v in manifest["outputs"].values()) > spec["max_output_bytes"]):
            raise StateError("ANALYSIS_EXPORT_LIMIT_BINDING_CHANGED")
        raw = read(result.directory / "manifest.json", 16 * 1024 * 1024)
        files = [{"name": name, **record, "mime": _MIMES[name]} for name, record in manifest["outputs"].items()]
        files.append({"name": "manifest.json", "bytes": len(raw), "sha256": digest(raw), "mime": _MIMES["manifest.json"]})
        return {"schema": _SCHEMA, "label": spec["label"], "directory": str(result.directory),
                "manifest_sha256": digest(raw), "manifest": manifest,
                "manifest_text": raw.decode("utf-8"), "files": files,
                "source_query": {"id": review["id"], "result_sha256": spec["result_sha256"],
                                 "parameters_text": review["request"]["parameters_text"],
                                 "finished_at": review["finished_at"], "preview_rows": len(review["result"]["rows"]),
                                 "preview_truncated": review["result"]["truncated"]}}

    def _finish(self, job_id, status, *, result=None, error=None):
        with self.database._connection() as db:
            db.execute("UPDATE sf_analysis_jobs SET status=?,result=?,error=?,finished_at=? WHERE id=? AND kind='query-export'",
                       (status, _json(result) if result else None, error, _now(), job_id))

    def run(self, job_id, spec):
        job_id = _identifier(job_id)
        review = self._review(spec)
        with self._mutex:
            signal = self._signals.setdefault(job_id, threading.Event())
            if self._closed or self._control(job_id)["cancel_requested"]:
                signal.set()
        try:
            self._progress(job_id, {"started_at": _now()})
            if signal.is_set():
                raise StateError("DATASET_SQL_QUERY_CANCELLED")
            self.database.export_query(review["request"]["sql"],
                self.parse_parameters(review["request"]["parameters_text"]),
                destination=self.directory / job_id, expected_views=review["result"]["views"],
                formats=spec["formats"], timeout=spec["timeout"], cancel=signal.is_set,
                max_rows=spec["max_rows"], max_output_bytes=spec["max_output_bytes"],
                spreadsheet_safe=spec["spreadsheet_safe"], progress=lambda value: self._progress(job_id, value))
            result = self._completed(job_id, spec, review)
            self._finish(job_id, "COMPLETE", result=result)
        except BaseException as exc:
            # A final callback or DB update can fail after native publication.
            # The complete original manifest wins over late cancel/error state.
            try:
                result = self._completed(job_id, spec, review)
            except (BuyerError, OSError, ValueError, TypeError):
                code = getattr(exc, "code", None) or str(exc) if isinstance(exc, BuyerError) else type(exc).__name__
                status = "CANCELLED" if code == "DATASET_SQL_QUERY_CANCELLED" else "FAILED"
                self._finish(job_id, status, error=str(code)[:256])
            else:
                self._finish(job_id, "COMPLETE", result=result)
        finally:
            with self._mutex:
                self._signals.pop(job_id, None)

    def recover_completed(self):
        """Adopt original complete outputs after interruption without SQL replay."""
        with self.database._connection(readonly=True) as db:
            ids = [row[0] for row in db.execute("SELECT id FROM sf_analysis_jobs WHERE kind='query-export' AND status IN ('INTERRUPTED','FAILED','CANCELLED')")]
        for job_id in ids:
            if not (self.directory / job_id / "manifest.json").exists():
                continue
            record = self._record(job_id)
            try:
                result = self._completed(job_id, record["request"], self._review(record["request"]))
            except (BuyerError, OSError, ValueError, TypeError):
                continue
            self._finish(job_id, "COMPLETE", result=result)

    def history(self, *, before=None, limit=25):
        if type(limit) is not int or not 1 <= limit <= 100 or before is not None and (type(before) is not int or before < 1):
            raise StateError("ANALYSIS_EXPORT_PAGE_INVALID")
        with self.database._connection(readonly=True) as db:
            rows = db.execute("SELECT sequence,id,status,created_at,finished_at,error,request,result FROM sf_analysis_jobs "
                              "WHERE kind='query-export' AND (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?",
                              (before, before, limit + 1)).fetchall()
        items = []
        for row in rows[:limit]:
            item = dict(row)
            spec = parse(item.pop("request").encode())
            result = parse(item.pop("result").encode()) if row["result"] else None
            manifest = result["manifest"] if result else {}
            item.update(label=spec["label"], query_id=spec["query_id"], row_count=manifest.get("rowCount"),
                        output_bytes=sum(v["bytes"] for v in manifest.get("outputs", {}).values()) if result else None,
                        progress=self.progress(row["id"]))
            items.append(item)
        return {"items": items, "next_before": items[-1]["sequence"] if len(rows) > limit else None}

    @contextmanager
    def download(self, job_id, name):
        job = self._record(job_id)
        if job["status"] != "COMPLETE" or not job["result"]:
            raise StateError("ANALYSIS_EXPORT_COMPLETE_REQUIRED")
        if name not in _MIMES:
            raise StateError("ANALYSIS_EXPORT_FILE_INVALID")
        result = QueryExport(self.directory / job_id)
        raw = read(result.directory / "manifest.json", 16 * 1024 * 1024)
        if digest(raw) != job["result"]["manifest_sha256"]:
            raise StateError("ANALYSIS_EXPORT_MANIFEST_CHANGED")
        record = next((f for f in job["result"]["files"] if f["name"] == name), None)
        if record is None:
            raise StateError("QUERY_EXPORT_OUTPUT_NOT_SELECTED")
        if name == "manifest.json":
            if len(raw) != record["bytes"] or digest(raw) != record["sha256"]:
                raise StateError("ANALYSIS_EXPORT_MANIFEST_CHANGED")
            with io.BytesIO(raw) as stream:
                yield stream, record
        else:
            # The native reader validates the chosen output before HTTP headers,
            # and owns this same descriptor through the whole streamed download.
            with result.open(name) as stream:
                yield stream, record

"""Retained customer reports on the original analytical database and SQL reader."""
from __future__ import annotations

import csv
from datetime import datetime, timezone
import hashlib
import html
import io
import json
import os
from pathlib import Path
import re
import stat
import tempfile
import time
import zipfile

from .errors import StateError
from .storage import digest, parse, private_directory

_SCHEMA = "stellar-forge.customer-report.v1"
_DEFINITION = "stellar-forge.customer-report-definition.v1"
_PUBLICATION = "stellar-forge.customer-report-publication.v1"
_NAME = re.compile(r"[a-zA-Z][a-zA-Z0-9_-]{0,63}")
_ID = re.compile(r"[a-f0-9]{32}")
_HASH = re.compile(r"[a-f0-9]{64}")
_TEMP = re.compile(r"\.reports-[a-zA-Z0-9_-]+")
_MAX_ROWS_BYTES = 32 * 1024 * 1024
_MAX_EXPORT_BYTES = 128 * 1024 * 1024
_PRINT_STYLE = """
:root{font:14px/1.5 Arial,Helvetica,sans-serif;color:#202020;background:#fff}
body{max-width:1100px;margin:36px auto;padding:0 24px}h1{font-size:28px;line-height:1.2}
h2{font-size:20px;margin-top:32px}h3{font-size:15px}p{white-space:pre-wrap}
.eyebrow{font-size:11px;letter-spacing:.08em;color:#555}
.meta{font-size:12px;color:#555;overflow-wrap:anywhere}.table-scroll{overflow:auto}
table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:7px 9px;border:1px solid #ccc;text-align:left;vertical-align:top;white-space:pre-wrap;overflow-wrap:anywhere}
th{background:#eee}.null{font-style:italic;color:#666}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;border:1px solid #ccc;padding:12px}
nav a{display:inline-block;margin-right:16px}a{color:inherit}.note{border-left:3px solid #555;padding-left:12px}
@media print{body{margin:0;max-width:none;padding:0}nav{display:none}thead{display:table-header-group}tr{break-inside:avoid}.table-scroll{overflow:visible}h2,h3{break-after:avoid}pre{max-height:none}}
@media(max-width:600px){body{margin:18px auto;padding:0 14px}h1{font-size:24px}}
"""


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"))


def _now():
    return datetime.now(timezone.utc).isoformat()


def _text(value, label, maximum, *, required=False):
    if not isinstance(value, str) or len(value.encode()) > maximum or "\0" in value or required and not value.strip():
        raise StateError("ANALYSIS_REPORT_" + label + "_INVALID")
    return value


def _name(value):
    if not isinstance(value, str) or not _NAME.fullmatch(value):
        raise StateError("ANALYSIS_REPORT_NAME_INVALID")
    return value


def _id(value):
    if not isinstance(value, str) or not _ID.fullmatch(value):
        raise StateError("ANALYSIS_REPORT_REQUEST_ID_REQUIRED")
    return value


def _hash(value):
    if not isinstance(value, str) or not _HASH.fullmatch(value):
        raise StateError("ANALYSIS_REPORT_DIGEST_REQUIRED")
    return value


def _revision(value, *, zero=False):
    if type(value) is not int or value < (0 if zero else 1):
        raise StateError("ANALYSIS_REPORT_REVISION_REQUIRED")
    return value


def _unpack(row):
    if row is None:
        raise StateError("ANALYSIS_REPORT_NOT_FOUND")
    raw = row["record"].encode()
    if digest(raw) != row["sha256"]:
        raise StateError("ANALYSIS_REPORT_RETAINED_RECORD_CHANGED")
    return parse(raw)


def _page(before, limit):
    if type(limit) is not int or not 1 <= limit <= 100 or before is not None and (type(before) is not int or before < 1):
        raise StateError("ANALYSIS_REPORT_PAGE_INVALID")


class AnalysisReports:
    """Compose original saved SQL into reviewed, portable customer reports.

    The workspace supplies its existing scalar encoder and parameter parser.
    Queries all use one original read transaction. Rows are staged privately,
    then the complete report and all rows commit together in the original DB.
    """

    def __init__(self, database, *, encode_cell, parse_parameters, changes):
        self.database = database
        self.encode_cell = encode_cell
        self.parse_parameters = parse_parameters
        self.changes = changes
        self.exports = private_directory(database.directory / "analysis-exports")
        # Called only after the original workspace's exclusive process lease.
        for path in self.exports.iterdir():
            if _TEMP.fullmatch(path.name):
                info = path.lstat()
                if stat.S_ISREG(info.st_mode) and not info.st_mode & 0o077:
                    path.unlink()
        with database._connection() as db:
            db.execute("BEGIN IMMEDIATE")
            db.execute("CREATE TABLE IF NOT EXISTS sf_analysis_reports(name TEXT PRIMARY KEY,revision INTEGER NOT NULL,record TEXT NOT NULL,sha256 TEXT NOT NULL)")
            db.execute("CREATE TABLE IF NOT EXISTS sf_analysis_report_history(sequence INTEGER PRIMARY KEY,name TEXT NOT NULL,revision INTEGER NOT NULL,request_id TEXT NOT NULL UNIQUE,request_sha256 TEXT NOT NULL,record TEXT NOT NULL,sha256 TEXT NOT NULL,UNIQUE(name,revision))")
            db.execute("CREATE TABLE IF NOT EXISTS sf_analysis_report_rows(job_id TEXT NOT NULL REFERENCES sf_analysis_jobs(id),section INTEGER NOT NULL,row_number INTEGER NOT NULL,record TEXT NOT NULL,sha256 TEXT NOT NULL,PRIMARY KEY(job_id,section,row_number))")
            db.execute("CREATE TABLE IF NOT EXISTS sf_analysis_report_publications(sequence INTEGER PRIMARY KEY,id TEXT NOT NULL UNIQUE,name TEXT NOT NULL,revision INTEGER NOT NULL,job_id TEXT NOT NULL REFERENCES sf_analysis_jobs(id),request_sha256 TEXT NOT NULL,record TEXT NOT NULL,sha256 TEXT NOT NULL,UNIQUE(name,revision))")
            db.commit()

    @staticmethod
    def state(db):
        if db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='sf_analysis_reports'").fetchone() is None:
            return []
        return [{"name": row["name"], "revision": row["revision"], "sha256": row["sha256"],
                 "title": _unpack(row)["title"]}
                for row in db.execute("SELECT * FROM sf_analysis_reports ORDER BY name")]

    def save(self, name, request):
        name = _name(name)
        request_id = _id(request.get("id"))
        expected = _revision(request.get("expected_revision"), zero=True)
        title = _text(request.get("title"), "TITLE", 300, required=True)
        introduction = _text(request.get("introduction", ""), "INTRODUCTION", 16000)
        sections = request.get("sections")
        if not isinstance(sections, list) or not 1 <= len(sections) <= 12:
            raise StateError("ANALYSIS_REPORT_ONE_TO_TWELVE_SECTIONS_REQUIRED")
        proposed = []
        for section in sections:
            if not isinstance(section, dict):
                raise StateError("ANALYSIS_REPORT_SECTION_INVALID")
            parameters = section.get("parameters_text")
            if parameters is not None:
                self.parse_parameters(parameters)
            proposed.append({
                "title": _text(section.get("title"), "SECTION_TITLE", 300, required=True),
                "note": _text(section.get("note", ""), "SECTION_NOTE", 8000),
                "query_name": _name(section.get("query_name")),
                "query_revision": _revision(section.get("query_revision")),
                "parameters_text": parameters,
            })
        normalized = {"id": request_id, "name": name, "expected_revision": expected,
                      "title": title, "introduction": introduction, "sections": proposed}
        request_sha = digest(_json(normalized).encode())
        with self.database._connection() as db:
            db.execute("BEGIN IMMEDIATE")
            existing = db.execute("SELECT * FROM sf_analysis_report_history WHERE request_id=?", (request_id,)).fetchone()
            if existing is not None:
                if existing["request_sha256"] != request_sha:
                    raise StateError("ANALYSIS_REPORT_REQUEST_ID_REUSED")
                result = _unpack(existing)
                db.commit()
                return result
            current = db.execute("SELECT revision FROM sf_analysis_reports WHERE name=?", (name,)).fetchone()
            if (current[0] if current else 0) != expected:
                raise StateError("ANALYSIS_REPORT_DEFINITION_CHANGED")
            pinned = []
            for ordinal, section in enumerate(proposed):
                row = db.execute("SELECT record FROM sf_analysis_query_history WHERE name=? AND revision=?",
                                 (section["query_name"], section["query_revision"])).fetchone()
                if row is None:
                    raise StateError("ANALYSIS_REPORT_SAVED_QUERY_NOT_FOUND")
                query = parse(row[0].encode())
                parameters = section["parameters_text"]
                if parameters is None:
                    parameters = query["parameters_text"]
                self.parse_parameters(parameters)
                pinned.append({**section, "ordinal": ordinal, "parameters_text": parameters,
                               "query": query, "query_sha256": digest(row[0].encode())})
            record = {"schema": _DEFINITION, "name": name, "revision": expected + 1,
                      "title": title, "introduction": introduction, "sections": pinned,
                      "saved_at": _now(), "request_id": request_id}
            raw = _json(record)
            sha = digest(raw.encode())
            db.execute("INSERT INTO sf_analysis_reports VALUES(?,?,?,?) ON CONFLICT(name) DO UPDATE SET revision=excluded.revision,record=excluded.record,sha256=excluded.sha256",
                       (name, expected + 1, raw, sha))
            db.execute("INSERT INTO sf_analysis_report_history(name,revision,request_id,request_sha256,record,sha256) VALUES(?,?,?,?,?,?)",
                       (name, expected + 1, request_id, request_sha, raw, sha))
            db.commit()
            return record

    def definition(self, name, *, revision=None):
        name = _name(name)
        if revision is not None:
            _revision(revision)
        with self.database._connection(readonly=True) as db:
            db.execute("BEGIN")
            if revision is None:
                row = db.execute("SELECT * FROM sf_analysis_reports WHERE name=?", (name,)).fetchone()
            else:
                row = db.execute("SELECT * FROM sf_analysis_report_history WHERE name=? AND revision=?", (name, revision)).fetchone()
            record = _unpack(row)
            current = db.execute("SELECT revision FROM sf_analysis_reports WHERE name=?", (name,)).fetchone()
            history = [dict(r) for r in db.execute("SELECT revision,sha256 FROM sf_analysis_report_history WHERE name=? ORDER BY revision DESC LIMIT 100", (name,))]
            head = db.execute("SELECT revision FROM sf_analysis_report_publications WHERE name=? ORDER BY revision DESC LIMIT 1", (name,)).fetchone()
            return {"definition": record, "sha256": row["sha256"], "head_revision": current[0],
                    "history": history, "publication_revision": head[0] if head else 0}

    def prepare(self, request):
        views = request.get("expected_views")
        if not isinstance(views, list) or len(_json(views).encode()) > 256 * 1024:
            raise StateError("ANALYSIS_REPORT_REVIEWED_VIEWS_REQUIRED")
        return {"name": _name(request.get("name")), "revision": _revision(request.get("revision")),
                "definition_sha256": _hash(request.get("definition_sha256")), "expected_views": views}

    def _input(self, db, spec):
        row = db.execute("SELECT * FROM sf_analysis_report_history WHERE name=? AND revision=?",
                         (spec["name"], spec["revision"])).fetchone()
        record = _unpack(row)
        if row["sha256"] != spec["definition_sha256"]:
            raise StateError("ANALYSIS_REPORT_DEFINITION_CHANGED")
        if self.database._views(db) != spec["expected_views"]:
            raise StateError("DATASET_SQL_VIEWS_CHANGED")
        return record

    def _data_reviews(self, db, views):
        """Carry the original comparison decision for each exact selected view."""
        selected = {(view["name"], view["revision"], view["version_id"]): view for view in views}
        result = []
        for row in db.execute("SELECT job_id FROM sf_analysis_change_selections ORDER BY rowid"):
            selection = self.changes._selection(db, row[0])
            activation = selection["activation"]
            key = (activation["name"], activation["revision"], activation["version"]["version_id"])
            if key not in selected:
                continue
            comparison = self.changes._report(db, row[0])
            if comparison["result_sha256"] != selection["result_sha256"]:
                raise StateError("ANALYSIS_REPORT_DATA_REVIEW_CHANGED")
            result.append({"view": selected[key], "comparison_id": row[0],
                           "comparison_result_sha256": comparison["result_sha256"],
                           "selection_id": selection["id"], "selection_sha256": digest(_json(selection).encode()),
                           "selected_at": selection["selected_at"], "review_note": selection["note"],
                           "previous_view": selection["previous_view"],
                           "baseline": {"version_id": comparison["baseline"]["version_id"], "dataset": comparison["baseline"]["dataset"]},
                           "candidate": {"version_id": comparison["candidate"]["version_id"], "dataset": comparison["candidate"]["dataset"]},
                           "schema_changes": comparison["schema_changes"], "counts": comparison["counts"],
                           "positions_changed": comparison["positions_changed"]})
        return result

    def run(self, job_id, spec):
        deadline = time.monotonic() + 60
        fd, temporary = tempfile.mkstemp(prefix=".reports-", dir=self.exports)
        temporary = Path(temporary)
        try:
            with os.fdopen(fd, "w+b") as spool:
                with self.database._connection(readonly=True) as db:
                    db.execute("BEGIN")
                    definition = self._input(db, spec)
                    workspace_id = db.execute("SELECT workspace_id FROM sf_analysis_format WHERE id=1").fetchone()[0]
                    sources, section_records, total_bytes, total_rows = {}, [], 0, 0
                    for section in definition["sections"]:
                        remaining = deadline - time.monotonic()
                        if remaining <= 0:
                            raise StateError("ANALYSIS_REPORT_TIME_LIMIT")
                        query = section["query"]
                        result = self.database._query(db, query["sql"], self.parse_parameters(section["parameters_text"]),
                            max_rows=query["max_rows"], max_result_bytes=4 * 1024 * 1024,
                            timeout=min(20, remaining), expected_views=spec["expected_views"])
                        if result.truncated:
                            raise StateError("ANALYSIS_REPORT_INCOMPLETE_SECTION_" + str(section["ordinal"] + 1) + "_INCREASE_SAVED_QUERY_LIMIT_OR_NARROW_QUERY")
                        checksum, section_bytes = hashlib.sha256(), 0
                        for number, values in enumerate(result.rows, 1):
                            raw = _json([self.encode_cell(value) for value in values]).encode()
                            checksum.update(raw + b"\n")
                            section_bytes += len(raw) + 1
                            total_bytes += len(raw) + 1
                            total_rows += 1
                            if total_bytes > _MAX_ROWS_BYTES or time.monotonic() >= deadline:
                                raise StateError("ANALYSIS_REPORT_RESULT_LIMIT")
                            spool.write(raw + b"\n")
                        section_records.append({"ordinal": section["ordinal"], "title": section["title"], "note": section["note"],
                            "query_name": section["query_name"], "query_revision": section["query_revision"],
                            "query_sha256": section["query_sha256"], "parameters_text": section["parameters_text"],
                            "columns": list(result.columns), "row_count": len(result.rows),
                            "rows_sha256": checksum.hexdigest(), "row_bytes": section_bytes,
                            "read_tables": list(result.read_tables)})
                        for table in result.read_tables:
                            if table.startswith("sf_dataset_rows_") and _HASH.fullmatch(table[16:]):
                                original = self.database._version(db, table[16:])
                                sources[original["version_id"]] = {key: value for key, value in original.items()
                                    if key not in {"sourceDirectory", "sequence", "created_at"}}
                    report = {"schema": _SCHEMA, "job_id": job_id, "workspace_id": workspace_id,
                        "definition": definition, "definition_sha256": spec["definition_sha256"],
                        "views": spec["expected_views"], "sources": [sources[key] for key in sorted(sources)],
                        "data_reviews": self._data_reviews(db, [view for view in spec["expected_views"] if view["version_id"] in sources]),
                        "sections": section_records, "total_rows": total_rows, "row_bytes": total_bytes,
                        "completed_at": _now()}
                    report["result_sha256"] = digest(_json(report).encode())
                # The source snapshot is closed before the short write transaction.
                # Later view changes do not rewrite this retained report.
                spool.flush()
                spool.seek(0)
                with self.database._connection() as db:
                    db.execute("BEGIN IMMEDIATE")
                    job = db.execute("SELECT kind,status,request FROM sf_analysis_jobs WHERE id=?", (job_id,)).fetchone()
                    if job is None or job["kind"] != "report" or job["status"] != "RUNNING" or parse(job["request"].encode()) != {"id": job_id, **spec}:
                        raise StateError("ANALYSIS_REPORT_JOB_CHANGED")
                    for section in section_records:
                        checksum = hashlib.sha256()
                        for number in range(1, section["row_count"] + 1):
                            line = spool.readline(_MAX_ROWS_BYTES + 1)
                            if not line.endswith(b"\n"):
                                raise StateError("ANALYSIS_REPORT_STAGING_CHANGED")
                            checksum.update(line)
                            raw = line[:-1]
                            db.execute("INSERT INTO sf_analysis_report_rows VALUES(?,?,?,?,?)",
                                       (job_id, section["ordinal"], number, raw.decode(), digest(raw)))
                        if checksum.hexdigest() != section["rows_sha256"]:
                            raise StateError("ANALYSIS_REPORT_STAGING_CHANGED")
                    if spool.read(1):
                        raise StateError("ANALYSIS_REPORT_STAGING_CHANGED")
                    db.execute("UPDATE sf_analysis_jobs SET status='COMPLETE',result=?,finished_at=? WHERE id=? AND status='RUNNING'",
                               (_json(report), report["completed_at"], job_id))
                    db.commit()
        finally:
            temporary.unlink(missing_ok=True)

    @staticmethod
    def _report(db, job_id):
        _id(job_id)
        row = db.execute("SELECT kind,status,result FROM sf_analysis_jobs WHERE id=?", (job_id,)).fetchone()
        if row is None or row["kind"] != "report" or row["status"] != "COMPLETE" or row["result"] is None:
            raise StateError("ANALYSIS_COMPLETE_REPORT_REQUIRED")
        report = parse(row["result"].encode())
        expected = digest(_json({key: value for key, value in report.items() if key != "result_sha256"}).encode())
        if report.get("schema") != _SCHEMA or report.get("job_id") != job_id or report.get("result_sha256") != expected:
            raise StateError("ANALYSIS_REPORT_RETAINED_RESULT_CHANGED")
        return report

    def history(self, *, name=None, before=None, limit=25):
        _page(before, limit)
        if name is not None:
            name = _name(name)
        with self.database._connection(readonly=True) as db:
            db.execute("BEGIN")
            rows = db.execute("SELECT sequence,id,status,created_at,finished_at,error,request,result FROM sf_analysis_jobs WHERE kind='report' AND (? IS NULL OR sequence<?) ORDER BY sequence DESC",
                              (before, before))
            items = []
            for row in rows:
                request = parse(row["request"].encode())
                if name is not None and request["name"] != name:
                    continue
                item = {key: row[key] for key in ("sequence", "id", "status", "created_at", "finished_at", "error")}
                item.update(name=request["name"], revision=request["revision"])
                if row["status"] == "COMPLETE":
                    report = self._report(db, row["id"])
                    item.update(title=report["definition"]["title"], total_rows=report["total_rows"],
                                sections=len(report["sections"]), result_sha256=report["result_sha256"])
                items.append(item)
                if len(items) > limit:
                    break
            return {"reports": items[:limit], "next_before": items[limit - 1]["sequence"] if len(items) > limit else None}

    @staticmethod
    def _rows(db, report, section):
        checksum, count, size = hashlib.sha256(), 0, 0
        for row in db.execute("SELECT row_number,record,sha256 FROM sf_analysis_report_rows WHERE job_id=? AND section=? ORDER BY row_number",
                              (report["job_id"], section["ordinal"])):
            raw = row["record"].encode()
            count += 1
            if row["row_number"] != count or digest(raw) != row["sha256"]:
                raise StateError("ANALYSIS_REPORT_RETAINED_ROWS_CHANGED")
            checksum.update(raw + b"\n")
            size += len(raw) + 1
            values = parse(raw)
            if len(values) != len(section["columns"]):
                raise StateError("ANALYSIS_REPORT_RETAINED_ROWS_CHANGED")
            yield values
        if count != section["row_count"] or size != section["row_bytes"] or checksum.hexdigest() != section["rows_sha256"]:
            raise StateError("ANALYSIS_REPORT_RETAINED_ROWS_CHANGED")

    def result(self, job_id, *, section=0, offset=0, limit=100):
        if type(section) is not int or section < 0 or type(offset) is not int or offset < 0 or type(limit) is not int or not 1 <= limit <= 250:
            raise StateError("ANALYSIS_REPORT_RESULT_PAGE_INVALID")
        with self.database._connection(readonly=True) as db:
            db.execute("BEGIN")
            report = self._report(db, job_id)
            if section >= len(report["sections"]):
                raise StateError("ANALYSIS_REPORT_SECTION_NOT_FOUND")
            selected = report["sections"][section]
            rows = []
            for row in db.execute("SELECT row_number,record,sha256 FROM sf_analysis_report_rows WHERE job_id=? AND section=? AND row_number>? ORDER BY row_number LIMIT ?",
                                  (job_id, section, offset, limit)):
                raw = row["record"].encode()
                if digest(raw) != row["sha256"] or row["row_number"] != offset + len(rows) + 1:
                    raise StateError("ANALYSIS_REPORT_RETAINED_ROWS_CHANGED")
                values = parse(raw)
                if len(values) != len(selected["columns"]):
                    raise StateError("ANALYSIS_REPORT_RETAINED_ROWS_CHANGED")
                rows.append(values)
            if len(rows) != min(limit, max(0, selected["row_count"] - offset)):
                raise StateError("ANALYSIS_REPORT_RETAINED_ROWS_CHANGED")
            publications = [{"publication": _unpack(row), "sha256": row["sha256"]}
                            for row in db.execute("SELECT * FROM sf_analysis_report_publications WHERE job_id=? ORDER BY revision DESC LIMIT 20", (job_id,))]
            head = db.execute("SELECT revision FROM sf_analysis_report_publications WHERE name=? ORDER BY revision DESC LIMIT 1", (report["definition"]["name"],)).fetchone()
            return {"report": report, "section": selected, "rows": rows, "offset": offset,
                    "next_offset": offset + limit if offset + limit < selected["row_count"] else None,
                    "publications": publications, "publication_revision": head[0] if head else 0}

    def publish(self, job_id, request):
        request_id = _id(request.get("id"))
        normalized = {"id": request_id, "job_id": _id(job_id), "result_sha256": _hash(request.get("result_sha256")),
                      "expected_revision": _revision(request.get("expected_revision"), zero=True),
                      "note": _text(request.get("note", ""), "PUBLICATION_NOTE", 16000)}
        request_sha = digest(_json(normalized).encode())
        with self.database._connection() as db:
            db.execute("BEGIN IMMEDIATE")
            old = db.execute("SELECT * FROM sf_analysis_report_publications WHERE id=?", (request_id,)).fetchone()
            if old is not None:
                if old["request_sha256"] != request_sha:
                    raise StateError("ANALYSIS_REPORT_REQUEST_ID_REUSED")
                record = _unpack(old)
                db.commit()
                return record
            report = self._report(db, job_id)
            if report["result_sha256"] != normalized["result_sha256"]:
                raise StateError("ANALYSIS_REPORT_RESULT_CHANGED")
            name = report["definition"]["name"]
            head = db.execute("SELECT revision FROM sf_analysis_report_publications WHERE name=? ORDER BY revision DESC LIMIT 1", (name,)).fetchone()
            if (head[0] if head else 0) != normalized["expected_revision"]:
                raise StateError("ANALYSIS_REPORT_PUBLICATION_CHANGED")
            for section in report["sections"]:
                for _ in self._rows(db, report, section):
                    pass
            record = {"schema": _PUBLICATION, "id": request_id, "name": name,
                      "revision": normalized["expected_revision"] + 1, "job_id": job_id,
                      "title": report["definition"]["title"], "definition_revision": report["definition"]["revision"],
                      "definition_sha256": report["definition_sha256"], "result_sha256": report["result_sha256"],
                      "note": normalized["note"], "published_at": _now(),
                      "report_views": report["views"], "current_views_at_publication": self.database._views(db)}
            raw = _json(record)
            db.execute("INSERT INTO sf_analysis_report_publications(id,name,revision,job_id,request_sha256,record,sha256) VALUES(?,?,?,?,?,?,?)",
                       (request_id, name, record["revision"], job_id, request_sha, raw, digest(raw.encode())))
            db.commit()
            return record

    def publications(self, *, name=None, before=None, limit=25):
        _page(before, limit)
        if name is not None:
            name = _name(name)
        with self.database._connection(readonly=True) as db:
            rows = db.execute("SELECT * FROM sf_analysis_report_publications WHERE (? IS NULL OR name=?) AND (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?",
                              (name, name, before, before, limit + 1)).fetchall()
            items = [{"sequence": row["sequence"], "publication": _unpack(row), "sha256": row["sha256"]} for row in rows[:limit]]
            return {"publications": items, "next_before": rows[limit - 1]["sequence"] if len(rows) > limit else None}

    def prepare_export(self, request):
        format = request.get("format")
        if format not in {"html", "json", "csv"}:
            raise StateError("ANALYSIS_REPORT_EXPORT_FORMAT_INVALID")
        return {"publication_id": _id(request.get("publication_id")),
                "publication_sha256": _hash(request.get("publication_sha256")), "format": format}

    def _export_input(self, db, spec):
        row = db.execute("SELECT * FROM sf_analysis_report_publications WHERE id=?", (spec["publication_id"],)).fetchone()
        publication = _unpack(row)
        if row["sha256"] != spec["publication_sha256"]:
            raise StateError("ANALYSIS_REPORT_PUBLICATION_CHANGED")
        report = self._report(db, publication["job_id"])
        if report["result_sha256"] != publication["result_sha256"]:
            raise StateError("ANALYSIS_REPORT_RESULT_CHANGED")
        return publication, report

    def _json_blocks(self, db, publication, report):
        yield ('{"schema":' + _json(_SCHEMA) + ',"publication":' + _json(publication) + ',"report":' + _json(report) + ',"tables":[').encode()
        for index, section in enumerate(report["sections"]):
            if index:
                yield b","
            yield ('{"ordinal":' + str(index) + ',"columns":' + _json(section["columns"]) + ',"rows":[').encode()
            first = True
            for values in self._rows(db, report, section):
                if not first:
                    yield b","
                yield _json(values).encode()
                first = False
            yield b"]}"
        yield b"]}\n"

    def _html_blocks(self, db, publication, report):
        esc = lambda value: html.escape(str(value), quote=True)
        definition = report["definition"]
        yield ('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' +
            esc(definition["title"]) + '</title><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; base-uri \'none\'; form-action \'none\'"><style>' +
            _PRINT_STYLE + '</style></head><body><p class="eyebrow">STELLAR FORGE / CUSTOMER REPORT</p><h1>' +
            esc(definition["title"]) + '</h1><p class="meta">Published edition ' + str(publication["revision"]) +
            ' · ' + esc(publication["published_at"]) + ' · Report definition ' + str(definition["revision"]) +
            '</p><p>' + esc(definition["introduction"]) + '</p><p class="note">' + esc(publication["note"]) + '</p><nav>').encode()
        for section in report["sections"]:
            yield ('<a href="#section-' + str(section["ordinal"]) + '">' + esc(section["title"]) + '</a>').encode()
        yield b'<a href="#sources">Data and methods</a></nav>'
        for section in report["sections"]:
            yield ('<section id="section-' + str(section["ordinal"]) + '"><h2>' + esc(section["title"]) + '</h2><p>' +
                   esc(section["note"]) + '</p><p class="meta">' + str(section["row_count"]) +
                   ' complete rows · ' + esc(section["query_name"]) + ' revision ' + str(section["query_revision"]) +
                   '</p><div class="table-scroll"><table><thead><tr>').encode()
            for column in section["columns"]:
                yield ('<th scope="col">' + esc(column) + '</th>').encode()
            yield b"</tr></thead><tbody>"
            for values in self._rows(db, report, section):
                yield b"<tr>"
                for value in values:
                    null = value["type"] == "null"
                    yield ('<td' + (' class="null"' if null else "") + ' title="' + esc(value["type"]) + '">' +
                           esc("NULL" if null else value["text"]) + '</td>').encode()
                yield b"</tr>"
            if not section["row_count"]:
                yield ('<tr><td colspan="' + str(max(1, len(section["columns"]))) + '">No rows returned.</td></tr>').encode()
            yield b"</tbody></table></div></section>"
        yield b'<section id="sources"><h2>Data and methods</h2><p>Every section used the same retained database snapshot. Source queries, projections and ordering describe the acquired editions; differences between selected editions do not by themselves establish changes at the provider.</p>'
        for review in report["data_reviews"]:
            yield ('<h3>Data selection: ' + esc(review["view"]["name"]) + '</h3><p class="note">' +
                   esc(review["review_note"]) + '</p><pre>' + esc(json.dumps(review, ensure_ascii=False, indent=2)) + '</pre>').encode()
        for source in report["sources"]:
            dataset = source.get("dataset", {})
            yield ('<h3>' + esc(dataset.get("name") or "Acquired dataset") + '</h3><p class="meta">Version ' +
                   esc(source["version_id"]) + ' · ' + str(source["row_count"]) + ' acquired rows</p><pre>' +
                   esc(json.dumps({"dataset": dataset, "column_types": source["column_types"],
                                   "manifestSha256": source["manifestSha256"], "jsonl": source["jsonl"]},
                                  ensure_ascii=False, indent=2)) + '</pre>').encode()
            if source.get("semantic_dictionary") is not None:
                dictionary = source["semantic_dictionary"]
                metadata = source["semantics"]
                meanings = {column["name"]: column for column in dictionary["columns"]}
                yield ('<h4>Reviewed source meanings</h4><p>These definitions belong to the imported source fields and their SQL aliases. The saved SQL describes calculations and aggregation in this report.</p><p class="meta">Meaning ' +
                       esc(metadata["semantic_sha256"]) + ' · Definition ' + esc(metadata["definition_sha256"]) +
                       '</p><div class="table-scroll"><table><thead><tr><th>Source field</th><th>SQL column</th><th>Definition</th></tr></thead><tbody>').encode()
                for column in metadata["columns"]:
                    meaning = meanings[column["source"]]
                    yield ('<tr><td>' + esc(column["source"]) + '</td><td>' + esc(column["column"]) +
                           '</td><td><pre>' + esc(json.dumps(meaning["projectedDefinition"], ensure_ascii=False, indent=2)) +
                           '</pre></td></tr>').encode()
                yield ('</tbody></table></div><details><summary>Source identity and attribution</summary><pre>' +
                       esc(json.dumps({"source": dictionary["source"], "primaryKey": dictionary["primaryKey"],
                                       "aboutUrl": dictionary["aboutUrl"], "virtualColumns": dictionary["virtualColumns"],
                                       "issues": dictionary["issues"], "originalDictionary": metadata["file"]},
                                      ensure_ascii=False, indent=2)) + '</pre></details>').encode()
        for section, recipe in zip(report["sections"], definition["sections"]):
            yield ('<h3>' + esc(section["title"]) + ' — query</h3><pre>' + esc(recipe["query"]["sql"]) +
                   '\n\nParameters: ' + esc(section["parameters_text"]) + '</pre>').encode()
        yield ('<h3>Retained report</h3><pre>' + esc(json.dumps({"publication": publication,
            "workspace_id": report["workspace_id"], "job_id": report["job_id"], "completed_at": report["completed_at"],
            "views": report["views"], "definition_sha256": report["definition_sha256"],
            "result_sha256": report["result_sha256"]}, ensure_ascii=False, indent=2)) +
            '</pre></section></body></html>\n').encode()

    @staticmethod
    def _zip_info(name):
        entry = zipfile.ZipInfo(name, date_time=(1980, 1, 1, 0, 0, 0))
        entry.compress_type = zipfile.ZIP_DEFLATED
        entry.external_attr = 0o100600 << 16
        entry._compresslevel = 6
        return entry

    def _csv_archive(self, stream, db, publication, report):
        with zipfile.ZipFile(stream, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=6) as archive:
            with archive.open(self._zip_info("report.json"), "w") as member:
                for block in self._json_blocks(db, publication, report):
                    member.write(block)
            with archive.open(self._zip_info("report.html"), "w") as member:
                for block in self._html_blocks(db, publication, report):
                    member.write(block)
            for section in report["sections"]:
                name = "sections/" + str(section["ordinal"] + 1).zfill(2) + "-" + section["query_name"] + ".csv"
                with archive.open(self._zip_info(name), "w") as member:
                    with io.TextIOWrapper(member, encoding="utf-8", newline="") as writer_stream:
                        writer = csv.writer(writer_stream)
                        writer.writerow(section["columns"])
                        for values in self._rows(db, report, section):
                            writer.writerow([value["text"] if value["type"] != "null" else "" for value in values])
                            if stream.tell() > _MAX_EXPORT_BYTES:
                                raise StateError("ANALYSIS_REPORT_EXPORT_LIMIT")
            for source in report["sources"]:
                if source.get("semantics") is None:
                    continue
                raw = self.database.semantics_bytes(source["version_id"])
                expected = source["semantics"]["file"]
                if raw is None or len(raw) != expected["bytes"] or digest(raw) != expected["sha256"]:
                    raise StateError("ANALYSIS_REPORT_SOURCE_SEMANTICS_CHANGED")
                name = "sources/" + source["version_id"] + "-semantics.json"
                with archive.open(self._zip_info(name), "w") as member:
                    member.write(raw)
                if stream.tell() > _MAX_EXPORT_BYTES:
                    raise StateError("ANALYSIS_REPORT_EXPORT_LIMIT")
            with archive.open(self._zip_info("README.txt"), "w") as member:
                member.write(("Customer report: " + report["definition"]["title"] + "\n" +
                    "Each sections/*.csv file contains the complete table in report order. report.json retains scalar types, NULL, exact source queries and the original reviewed publication. report.html is the complete offline printable report. CSV uses original values; NULL and an empty string both appear as an empty CSV field.\n" +
                    "Where reviewed source meanings exist, sources/*-semantics.json retains each exact original dictionary. report.json binds it to the imported source and reviewed SQL aliases; derived output meaning follows the saved SQL.\n" +
                    "Publication: " + publication["id"] + "\nResult SHA-256: " + report["result_sha256"] + "\n").encode())

    def export(self, spec):
        fd, temporary = tempfile.mkstemp(prefix=".reports-", dir=self.exports)
        temporary = Path(temporary)
        try:
            with os.fdopen(fd, "w+b") as stream, self.database._connection(readonly=True) as db:
                db.execute("BEGIN")
                # Publication, report, and all table rows use one frozen snapshot.
                publication, report = self._export_input(db, spec)
                if spec["format"] == "csv":
                    self._csv_archive(stream, db, publication, report)
                else:
                    blocks = self._json_blocks(db, publication, report) if spec["format"] == "json" else self._html_blocks(db, publication, report)
                    for block in blocks:
                        stream.write(block)
                        if stream.tell() > _MAX_EXPORT_BYTES:
                            raise StateError("ANALYSIS_REPORT_EXPORT_LIMIT")
                stream.flush()
                os.fsync(stream.fileno())
                info = os.fstat(stream.fileno())
                if info.st_size > _MAX_EXPORT_BYTES:
                    raise StateError("ANALYSIS_REPORT_EXPORT_LIMIT")
                stream.seek(0)
                sha = hashlib.file_digest(stream, "sha256").hexdigest()
            extension, mime = {"html": ("html", "text/html;charset=utf-8"),
                               "json": ("json", "application/json"),
                               "csv": ("zip", "application/zip")}[spec["format"]]
            filename = "report-" + sha + "." + extension
            target = self.exports / filename
            try:
                os.link(temporary, target)
            except FileExistsError:
                existing = os.open(target, os.O_RDONLY | os.O_NOFOLLOW)
                with os.fdopen(existing, "rb") as reader:
                    saved = os.fstat(reader.fileno())
                    if not stat.S_ISREG(saved.st_mode) or saved.st_nlink != 1 or saved.st_mode & 0o077 or saved.st_size != info.st_size or hashlib.file_digest(reader, "sha256").hexdigest() != sha:
                        raise StateError("ANALYSIS_REPORT_RETAINED_EXPORT_CHANGED")
            temporary.unlink()
            directory_fd = os.open(self.exports, os.O_RDONLY | os.O_DIRECTORY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
            return {"schema": _SCHEMA, "publication_id": publication["id"], "publication_sha256": spec["publication_sha256"],
                    "job_id": report["job_id"], "result_sha256": report["result_sha256"],
                    "format": spec["format"], "filename": filename, "mime": mime,
                    "path": str(target), "bytes": info.st_size, "sha256": sha}
        finally:
            temporary.unlink(missing_ok=True)

"""Saved Excel deliveries from original complete customer query/report results.

The existing AnalysisWorkspace owns the database lease, executor and job log.
This module reads retained results; it never executes SQL or an acquisition.
"""
from __future__ import annotations

import argparse
import base64
from contextlib import contextmanager
from datetime import date, datetime, timezone
from decimal import Decimal, InvalidOperation
import hashlib
import io
import json
import math
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import stat
import tempfile
import threading
import time
import zipfile

from .analysis_reports import AnalysisReports
from .errors import BuyerError, StateError
from .query_export import QueryExport
from .storage import digest, lock, parse, private_directory, read, sync_directory, write

_SCHEMA = "stellar-forge.customer-workbook.v1"
_DEFINITION = "stellar-forge.customer-workbook-definition.v1"
_NAME = re.compile(r"[A-Za-z][A-Za-z0-9_-]{0,63}")
_ID = re.compile(r"[a-f0-9]{32}")
_HASH = re.compile(r"[a-f0-9]{64}")
_BAD_SHEET = re.compile(r"[\\/*?:\[\]]")
_TYPES = {"native", "text", "integer", "number", "decimal-text", "boolean", "date", "datetime-utc", "datetime-local", "binary-base64"}
_ROWS_PER_SHEET = 1_048_575  # One additional row is reserved for column headings.
_MAX_COLUMNS = 16_384
_MAX_MANIFEST = 4 * 1024 * 1024
_MIMES = {"workbook.xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
          "handoff.zip": "application/zip", "manifest.json": "application/json"}


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"))


def _now():
    return datetime.now(timezone.utc).isoformat()


def _error(code):
    raise StateError("ANALYSIS_WORKBOOK_" + code)


def _name(value):
    if not isinstance(value, str) or not _NAME.fullmatch(value):
        _error("NAME_INVALID")
    return value


def _id(value):
    if not isinstance(value, str) or not _ID.fullmatch(value):
        _error("REQUEST_ID_REQUIRED")
    return value


def _hash(value):
    if not isinstance(value, str) or not _HASH.fullmatch(value):
        _error("DIGEST_REQUIRED")
    return value


def _text(value, maximum, *, required=False):
    if not isinstance(value, str) or len(value.encode("utf-8")) > maximum or "\0" in value or required and not value.strip():
        _error("TEXT_INVALID")
    return value


def _unpack(row):
    if row is None:
        _error("NOT_FOUND")
    raw = row["record"].encode()
    if digest(raw) != row["sha256"]:
        _error("RETAINED_RECORD_CHANGED")
    return parse(raw)


def _page(before, limit):
    if type(limit) is not int or not 1 <= limit <= 100 or before is not None and (type(before) is not int or before < 1):
        _error("PAGE_INVALID")


def _source_key(source, column):
    """Select report cells by position while preserving original column labels."""
    if not isinstance(column, dict) or column.get("source") not in source["columns"]:
        _error("SOURCE_COLUMN_CHANGED")
    if source["kind"] != "report":
        return column["source"]
    index = column.get("source_index")
    if index is None:
        matches = [index for index, name in enumerate(source["columns"]) if name == column["source"]]
        if len(matches) != 1:
            _error("SOURCE_COLUMN_INDEX_REQUIRED")
        return matches[0]
    if (type(index) is not int or not 0 <= index < len(source["columns"])
            or source["columns"][index] != column["source"]):
        _error("SOURCE_COLUMN_CHANGED")
    return index


def _relative(value):
    if not isinstance(value, str) or "\\" in value or "\0" in value:
        _error("FILE_INVALID")
    path = PurePosixPath(value)
    if path.is_absolute() or not path.parts or any(part in {".", "..", ""} for part in path.parts) or str(path) != value:
        _error("FILE_INVALID")
    if value in {"workbook.xlsx", "definition.json"}:
        return value
    if len(path.parts) == 2 and path.parts[0] == "history" and re.fullmatch(r"definition-[1-9][0-9]*\.json", path.parts[1]):
        return value
    if (len(path.parts) == 3 and path.parts[0] == "sources"
            and re.fullmatch(r"(?:query-export|report)-[a-f0-9]{32}", path.parts[1])
            and path.parts[2] in {"manifest.json", "rows.jsonl", "rows.csv", "rows.sqlite3", "report.json"}):
        return value
    _error("FILE_INVALID")


@contextmanager
def _open_private(path):
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
    with os.fdopen(fd, "rb") as stream:
        info = os.fstat(stream.fileno())
        if (not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_mode & 0o077
                or hasattr(os, "getuid") and info.st_uid != os.getuid()):
            _error("PRIVATE_FILE_REQUIRED")
        yield stream


def _file_record(path):
    with _open_private(path) as stream:
        return {"bytes": os.fstat(stream.fileno()).st_size, "sha256": hashlib.file_digest(stream, "sha256").hexdigest()}



def _publish_received_directory(source, target):
    """Atomically publish a complete directory without replacing any destination."""
    import ctypes
    import sys

    libc = ctypes.CDLL(None, use_errno=True)
    if sys.platform.startswith("linux") and hasattr(libc, "renameat2"):
        rename = libc.renameat2
        rename.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint]
        rename.restype = ctypes.c_int
        result = rename(-100, os.fsencode(source), -100, os.fsencode(target), 1)  # RENAME_NOREPLACE
    elif sys.platform == "darwin" and hasattr(libc, "renamex_np"):
        rename = libc.renamex_np
        rename.argtypes = [ctypes.c_char_p, ctypes.c_char_p, ctypes.c_uint]
        rename.restype = ctypes.c_int
        result = rename(os.fsencode(source), os.fsencode(target), 4)  # RENAME_EXCL
    else:
        _error("ATOMIC_DIRECTORY_PUBLICATION_UNAVAILABLE")
    if result:
        code = ctypes.get_errno()
        raise OSError(code, os.strerror(code), os.fspath(target))
    sync_directory(target.parent)


def _literal(value):
    """Check before openpyxl's string binding can truncate an Excel cell."""
    try:
        length = len(value.encode("utf-16-le")) // 2
    except UnicodeError:
        _error("CELL_UNICODE_INVALID")
    if length > 32_767:
        _error("CELL_TEXT_EXCEEDS_EXCEL_LIMIT")
    if any(ord(c) < 32 and c not in "\t\n\r" or ord(c) in {0xFFFE, 0xFFFF} for c in value):
        _error("CELL_XML_CHARACTER_INVALID")
    return value


def _display(value):
    if isinstance(value, bytes):
        return "base64:" + base64.b64encode(value).decode("ascii")
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, float) and not math.isfinite(value):
        return "NaN" if math.isnan(value) else "Infinity" if value > 0 else "-Infinity"
    return str(value)


def project_cell(value, column):
    """Return (value, Excel number format, conversion), with explicit precision."""
    kind = column["type"]
    if value is None:
        return (None if column["null"] == "blank" else _literal(column["null_text"]), None, "null")
    if kind == "text":
        return _literal(_display(value)), "@", "empty-string" if value == "" else None
    if kind == "binary-base64":
        if not isinstance(value, bytes):
            _error("BINARY_CELL_REQUIRED")
        return _literal(base64.b64encode(value).decode("ascii")), "@", "binary-text"
    if kind == "decimal-text":
        if isinstance(value, bool) or not isinstance(value, (str, int, float, Decimal)):
            _error("DECIMAL_CELL_REQUIRED")
        text = str(value)
        try:
            number = Decimal(text)
        except InvalidOperation:
            _error("DECIMAL_CELL_REQUIRED")
        if not number.is_finite():
            _error("FINITE_DECIMAL_REQUIRED")
        return _literal(text), "@", "decimal-text"
    if kind == "boolean":
        if type(value) is bool:
            return value, None, None
        if type(value) is int and value in {0, 1}:
            return bool(value), None, "boolean"
        if isinstance(value, str) and value.casefold() in {"true", "false"}:
            return value.casefold() == "true", None, "boolean"
        _error("BOOLEAN_CELL_REQUIRED")
    if kind in {"date", "datetime-utc", "datetime-local"}:
        if not isinstance(value, str):
            _error("ISO_DATE_TEXT_REQUIRED")
        try:
            if kind == "date":
                if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
                    _error("ISO_DATE_TEXT_REQUIRED")
                parsed = date.fromisoformat(value)
                if parsed < date(1900, 1, 1):
                    return _literal(value), "@", "date-text"
                return parsed, "yyyy-mm-dd", "date"
            parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
            if "T" not in value and " " not in value:
                _error("ISO_DATETIME_TEXT_REQUIRED")
            if kind == "datetime-utc":
                if parsed.tzinfo is None:
                    _error("DATETIME_TIMEZONE_REQUIRED")
                parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
            elif parsed.tzinfo is not None:
                _error("LOCAL_DATETIME_MUST_BE_NAIVE")
            if parsed.year < 1900 or parsed.microsecond % 1000:
                return _literal(value), "@", "datetime-text"
            return parsed, 'yyyy-mm-dd hh:mm:ss.000" UTC"' if kind == "datetime-utc" else "yyyy-mm-dd hh:mm:ss.000", "datetime"
        except (ValueError, OverflowError):
            _error("ISO_DATE_TEXT_REQUIRED")
    if kind == "integer":
        if type(value) is int:
            pass
        elif isinstance(value, str) and re.fullmatch(r"[+-]?\d+", value):
            value = int(value)
        else:
            _error("INTEGER_CELL_REQUIRED")
    elif kind == "number":
        if isinstance(value, bool) or not isinstance(value, (str, int, float, Decimal)):
            _error("NUMERIC_CELL_REQUIRED")
        text = str(value)
        try:
            number = Decimal(text)
        except InvalidOperation:
            _error("NUMERIC_CELL_REQUIRED")
        if not number.is_finite():
            _error("FINITE_NUMBER_REQUIRED")
        if column["precision"] == "preserve" and (len(number.as_tuple().digits) > 15 or number.adjusted() > 307 or number.adjusted() < -307):
            return _literal(text), "@", "precision-text"
        value = float(number)
        if not math.isfinite(value) or value == 0 and number != 0:
            _error("NUMBER_OUTSIDE_EXCEL_RANGE")
    if isinstance(value, bytes):
        return _literal(_display(value)), "@", "binary-text"
    if isinstance(value, str):
        return _literal(value), "@", "empty-string" if value == "" else None
    if isinstance(value, bool):
        return value, None, None
    if type(value) is int:
        if len(str(abs(value))) > 15 and column["precision"] == "preserve":
            return str(value), "@", "precision-text"
        return value, "0", "numeric-choice" if len(str(abs(value))) > 15 else None
    if isinstance(value, float):
        if not math.isfinite(value):
            return _display(value), "@", "nonfinite-text"
        decimal = Decimal(repr(value))
        if column["precision"] == "preserve" and (len(decimal.as_tuple().digits) > 15 or decimal.adjusted() > 307 or decimal.adjusted() < -307):
            return repr(value), "@", "precision-text"
        return value, "General", "numeric-choice" if column["precision"] == "excel-number" else None
    _error("CELL_TYPE_UNSUPPORTED")


def _sheet_layout(sheets):
    used = {"readme", "sources"}
    result = []
    for sheet in sheets:
        names = []
        count = max(1, (sheet["source"]["row_count"] + _ROWS_PER_SHEET - 1) // _ROWS_PER_SHEET)
        for index in range(count):
            suffix = "" if index == 0 else f" ({index + 1})"
            name = sheet["name"][:31 - len(suffix)] + suffix
            if name.casefold() in used:
                _error("SHEET_NAMES_COLLIDE_AFTER_SPLIT")
            used.add(name.casefold())
            names.append(name)
        result.append(names)
    return result


class WorkbookDelivery:
    """Open, inspect, copy or receive a complete workbook without a live workspace."""

    def __init__(self, directory, *, expected_manifest_sha256=None):
        self.directory = Path(directory).absolute()
        if self.directory.resolve() != self.directory or not self.directory.is_dir():
            _error("CANONICAL_DELIVERY_DIRECTORY_REQUIRED")
        self.raw = read(self.directory / "manifest.json", _MAX_MANIFEST)
        if expected_manifest_sha256 is not None and digest(self.raw) != _hash(expected_manifest_sha256):
            _error("MANIFEST_CHANGED")
        self.manifest = parse(self.raw)
        manifest = self.manifest
        if (manifest.get("schema") != _SCHEMA or manifest.get("complete") is not True
                or not isinstance(manifest.get("files"), dict) or not {"workbook.xlsx", "definition.json"} <= set(manifest["files"])):
            _error("COMPLETE_DELIVERY_REQUIRED")
        _id(manifest.get("id"))
        _hash(manifest.get("definition_sha256"))
        for name, record in manifest["files"].items():
            _relative(name)
            if not isinstance(record, dict) or type(record.get("bytes")) is not int or record["bytes"] < 0:
                _error("FILE_METADATA_INVALID")
            _hash(record.get("sha256"))

    @contextmanager
    def open(self, name):
        if name == "manifest.json":
            with io.BytesIO(self.raw) as stream:
                yield stream
            return
        if name not in self.manifest["files"]:
            _error("FILE_INVALID")
        path = self.directory / _relative(name)
        if path.resolve() != path:
            _error("FILE_LOCATION_CHANGED")
        with _open_private(path) as stream:
            expected = self.manifest["files"][name]
            if (os.fstat(stream.fileno()).st_size != expected["bytes"]
                    or hashlib.file_digest(stream, "sha256").hexdigest() != expected["sha256"]):
                _error("FILE_CHANGED")
            stream.seek(0)
            yield stream

    def inspect(self):
        for name in self.manifest["files"]:
            with self.open(name):
                pass
        with self.open("definition.json") as stream:
            raw = stream.read(_MAX_MANIFEST + 1)
        if len(raw) > _MAX_MANIFEST or digest(raw) != self.manifest["definition_sha256"]:
            _error("DEFINITION_CHANGED")
        current = parse(raw)
        while current.get("refresh_origin"):
            origin = current["refresh_origin"]
            revision = origin.get("base_revision")
            if type(revision) is not int or not 1 <= revision < current["revision"]:
                _error("REFRESH_HISTORY_CHANGED")
            name = "history/definition-" + str(revision) + ".json"
            if origin.get("base_definition_file") != name:
                _error("REFRESH_HISTORY_CHANGED")
            with self.open(name) as stream:
                previous_raw = stream.read(_MAX_MANIFEST + 1)
            if len(previous_raw) > _MAX_MANIFEST or digest(previous_raw) != origin.get("base_definition_sha256"):
                _error("REFRESH_HISTORY_CHANGED")
            previous = parse(previous_raw)
            if (previous.get("name") != current["name"] or previous.get("revision") != revision
                    or previous.get("workspace_id") != current["workspace_id"]):
                _error("REFRESH_HISTORY_CHANGED")
            current = previous
        return {**self.manifest, "manifest_sha256": digest(self.raw)}

    def verify_archive(self, path):
        """A recovered ZIP must contain the complete original manifest and files."""
        with _open_private(path) as stream, zipfile.ZipFile(stream) as package:
            names = [entry.filename for entry in package.infolist()]
            if len(names) != len(set(names)) or set(names) != set(self.manifest["files"]) | {"manifest.json"}:
                _error("ARCHIVE_MEMBERS_INVALID")
            meta = package.getinfo("manifest.json")
            if meta.file_size != len(self.raw) or package.read(meta) != self.raw:
                _error("ARCHIVE_MANIFEST_CHANGED")
            for name, expected in self.manifest["files"].items():
                entry = package.getinfo(name)
                if entry.file_size != expected["bytes"] or stat.S_ISLNK(entry.external_attr >> 16):
                    _error("ARCHIVE_MEMBER_CHANGED")
                with package.open(entry) as member:
                    if hashlib.file_digest(member, "sha256").hexdigest() != expected["sha256"]:
                        _error("ARCHIVE_MEMBER_CHANGED")

    def copy_to(self, destination):
        target = Path(destination).absolute()
        parent = private_directory(target.parent)
        if parent / target.name != target:
            _error("CANONICAL_DELIVERY_DIRECTORY_REQUIRED")
        target.mkdir(mode=0o700)
        try:
            for name in self.manifest["files"]:
                path = target / name
                private_directory(path.parent)
                with self.open(name) as source, path.open("xb") as output:
                    os.fchmod(output.fileno(), 0o600)
                    shutil.copyfileobj(source, output, 1024 * 1024)
                    output.flush()
                    os.fsync(output.fileno())
            write(target / "manifest.json", self.raw)
            sync_directory(target)
        except BaseException:
            shutil.rmtree(target)
            raise
        return WorkbookDelivery(target, expected_manifest_sha256=digest(self.raw))

    @classmethod
    def receive(cls, archive, destination, *, expected_sha256=None, max_bytes=1024 * 1024 * 1024):
        """Receive into private staging, then publish one verified complete directory."""
        if type(max_bytes) is not int or max_bytes < 1:
            _error("RECEIVING_LIMIT_REQUIRED")
        target = Path(destination).absolute()
        parent = private_directory(target.parent)
        target = parent / target.name
        if os.path.lexists(target):
            raise FileExistsError(str(target))
        with _open_private(Path(archive).absolute()) as source:
            archive_sha = hashlib.file_digest(source, "sha256").hexdigest()
            if expected_sha256 is not None and archive_sha != _hash(expected_sha256):
                _error("ARCHIVE_CHANGED")
            source.seek(0)
            # The original operation can reclaim its own unfinished staging after
            # process termination. The retained archive remains the only input.
            control = private_directory(parent / (".workbook-receive-" + digest(os.fsencode(target.name))[:24]))
            with lock(control):
                if os.path.lexists(target):
                    raise FileExistsError(str(target))
                intent_path, staging = control / "source.json", control / "content"
                intent = {"schema": "stellar-forge.workbook-receiving.v1", "destination": str(target),
                          "archive_sha256": archive_sha}
                if intent_path.exists():
                    with _open_private(intent_path) as retained:
                        old = retained.read(64 * 1024 + 1)
                    if len(old) > 64 * 1024 or parse(old) != intent:
                        _error("RECEIVING_OPERATION_CHANGED")
                else:
                    if os.path.lexists(staging):
                        _error("RECEIVING_STATE_INVALID")
                    write(intent_path, _json(intent).encode(), exclusive=True)
                if os.path.lexists(staging):
                    private_directory(staging, create=False)
                    shutil.rmtree(staging)
                staging.mkdir(mode=0o700)
                try:
                    with zipfile.ZipFile(source) as package:
                        infos = package.infolist()
                        names = [entry.filename for entry in infos]
                        if len(names) != len(set(names)) or "manifest.json" not in names:
                            _error("ARCHIVE_MEMBERS_INVALID")
                        meta = package.getinfo("manifest.json")
                        if meta.file_size > _MAX_MANIFEST:
                            _error("MANIFEST_TOO_LARGE")
                        raw = package.read(meta)
                        manifest = parse(raw)
                        if manifest.get("schema") != _SCHEMA or manifest.get("complete") is not True or not isinstance(manifest.get("files"), dict):
                            _error("COMPLETE_DELIVERY_REQUIRED")
                        if set(names) != set(manifest["files"]) | {"manifest.json"}:
                            _error("ARCHIVE_MEMBERS_INVALID")
                        if sum(entry.file_size for entry in infos) > max_bytes:
                            _error("RECEIVING_BYTE_LIMIT_EXCEEDED")
                        for name, expected in manifest["files"].items():
                            _relative(name)
                            entry = package.getinfo(name)
                            if entry.file_size != expected["bytes"] or stat.S_ISLNK(entry.external_attr >> 16):
                                _error("ARCHIVE_MEMBER_CHANGED")
                            path = staging / name
                            private_directory(path.parent)
                            sha, size = hashlib.sha256(), 0
                            with package.open(entry) as input_stream, path.open("xb") as output:
                                os.fchmod(output.fileno(), 0o600)
                                for block in iter(lambda: input_stream.read(1024 * 1024), b""):
                                    sha.update(block)
                                    size += len(block)
                                    if size > expected["bytes"]:
                                        _error("ARCHIVE_MEMBER_CHANGED")
                                    output.write(block)
                                output.flush()
                                os.fsync(output.fileno())
                            if size != expected["bytes"] or sha.hexdigest() != expected["sha256"]:
                                _error("ARCHIVE_MEMBER_CHANGED")
                        write(staging / "manifest.json", raw)
                        for directory in sorted((p for p in staging.rglob("*") if p.is_dir()),
                                                key=lambda p: len(p.parts), reverse=True):
                            sync_directory(directory)
                        sync_directory(staging)
                    result = cls(staging)
                    result.inspect()
                    _publish_received_directory(staging, target)
                    sync_directory(control)
                    return cls(target)
                except BaseException:
                    if staging.exists():
                        shutil.rmtree(staging)
                    raise


class AnalysisWorkbooks:
    def __init__(self, database, *, identity, reports=None, initialize=True):
        self.database, self.identity, self.reports = database, identity, reports
        from .workbook_refresh import WorkbookRefresh
        self.refresh = WorkbookRefresh(self)
        self.directory = database.directory / "analysis-workbooks"
        self._mutex = threading.Lock()
        self._signals = {}
        self._closed = False
        if initialize:
            private_directory(self.directory)
            with database._connection() as db:
                db.execute("BEGIN IMMEDIATE")
                db.execute("CREATE TABLE IF NOT EXISTS sf_analysis_workbooks(name TEXT PRIMARY KEY,revision INTEGER NOT NULL,record TEXT NOT NULL,sha256 TEXT NOT NULL)")
                db.execute("CREATE TABLE IF NOT EXISTS sf_analysis_workbook_history(sequence INTEGER PRIMARY KEY,name TEXT NOT NULL,revision INTEGER NOT NULL,request_id TEXT NOT NULL UNIQUE,request_sha256 TEXT NOT NULL,record TEXT NOT NULL,sha256 TEXT NOT NULL,UNIQUE(name,revision))")
                db.execute("CREATE TABLE IF NOT EXISTS sf_analysis_workbook_control(id TEXT PRIMARY KEY REFERENCES sf_analysis_jobs(id),cancel_requested INTEGER NOT NULL DEFAULT 0,progress TEXT NOT NULL)")
                db.commit()

    @staticmethod
    def state(db):
        if db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='sf_analysis_workbooks'").fetchone() is None:
            return []
        return [{"name": row["name"], "revision": row["revision"], "sha256": row["sha256"],
                 "title": _unpack(row)["title"], "sheets": len(_unpack(row)["sheets"])}
                for row in db.execute("SELECT * FROM sf_analysis_workbooks ORDER BY name")]

    def source(self, request):
        if not isinstance(request, dict) or request.get("kind") not in {"query-export", "report"}:
            _error("SOURCE_REQUIRED")
        kind, identifier = request["kind"], _id(request.get("id"))
        with self.database._connection(readonly=True) as db:
            db.execute("BEGIN")
            if kind == "query-export":
                row = db.execute("SELECT request,result FROM sf_analysis_jobs WHERE id=? AND kind='query-export' AND status='COMPLETE'", (identifier,)).fetchone()
                if row is None or row["result"] is None:
                    _error("COMPLETE_TYPED_QUERY_EXPORT_REQUIRED")
                result = parse(row["result"].encode())
                export = QueryExport(self.database.directory / "analysis-query-exports" / identifier)
                raw = read(export.directory / "manifest.json", 16 * 1024 * 1024)
                sha = digest(raw)
                manifest = export.manifest
                if result.get("manifest_sha256") != sha:
                    _error("SOURCE_MANIFEST_CHANGED")
                if "rows.jsonl" not in manifest["outputs"]:
                    _error("ORIGINAL_TYPED_JSONL_REQUIRED")
                item = {"kind": kind, "id": identifier, "sha256": sha, "label": result.get("label", identifier),
                        "columns": manifest["columns"], "row_count": manifest["rowCount"],
                        "binding_sha256": manifest["bindingSha256"]}
            else:
                if self.reports is None:
                    _error("ORIGINAL_REPORT_READER_REQUIRED")
                row = db.execute("SELECT * FROM sf_analysis_report_publications WHERE id=?", (identifier,)).fetchone()
                publication = _unpack(row)
                report = AnalysisReports._report(db, publication["job_id"])
                if report["result_sha256"] != publication["result_sha256"]:
                    _error("SOURCE_REPORT_CHANGED")
                section = request.get("section")
                if type(section) is not int or not 0 <= section < len(report["sections"]):
                    _error("REPORT_SECTION_REQUIRED")
                selected = report["sections"][section]
                item = {"kind": kind, "id": identifier, "sha256": row["sha256"], "section": section,
                        "job_id": report["job_id"], "result_sha256": report["result_sha256"],
                        "label": publication["title"] + " / " + selected["title"],
                        "columns": selected["columns"], "row_count": selected["row_count"]}
        if request.get("sha256") is not None and request["sha256"] != item["sha256"]:
            _error("SOURCE_CHANGED")
        return item

    def sources(self, *, kind="query-export", before=None, limit=25):
        _page(before, limit)
        with self.database._connection(readonly=True) as db:
            if kind == "query-export":
                rows = db.execute("SELECT sequence,id FROM sf_analysis_jobs WHERE kind='query-export' AND status='COMPLETE' AND (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?", (before, before, limit + 1)).fetchall()
            elif kind == "report" and self.reports is not None:
                rows = db.execute("SELECT sequence,id,job_id FROM sf_analysis_report_publications WHERE (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?", (before, before, limit + 1)).fetchall()
            else:
                _error("SOURCE_KIND_INVALID")
        items = []
        for row in rows[:limit]:
            if kind == "report":
                with self.database._connection(readonly=True) as db:
                    sections = len(AnalysisReports._report(db, row["job_id"])["sections"])
                items.extend(self.source({"kind": kind, "id": row["id"], "section": section}) for section in range(sections))
            else:
                try:
                    items.append(self.source({"kind": kind, "id": row["id"]}))
                except StateError as exc:
                    if exc.code != "ANALYSIS_WORKBOOK_ORIGINAL_TYPED_JSONL_REQUIRED":
                        raise
                    items.append({"kind": kind, "id": row["id"], "available": False, "error": exc.code})
        return {"items": items, "next_before": rows[limit - 1]["sequence"] if len(rows) > limit else None}

    def compose(self, name, request):
        """Normalize a complete definition before its compare-and-swap save."""
        name = _name(name)
        title = _text(request.get("title"), 300, required=True)
        notes = _text(request.get("notes", ""), 16_000)
        sheets = request.get("sheets")
        if not isinstance(sheets, list) or not 1 <= len(sheets) <= 32:
            _error("ONE_TO_32_SHEETS_REQUIRED")
        result = []
        for sheet in sheets:
            if not isinstance(sheet, dict):
                _error("SHEET_REQUIRED")
            label = _text(sheet.get("name"), 124, required=True)
            if len(label) > 31 or _BAD_SHEET.search(label) or label.startswith("'") or label.endswith("'") or any(ord(c) < 32 for c in label):
                _error("EXCEL_SHEET_NAME_INVALID")
            source = self.source(sheet.get("source"))
            columns = sheet.get("columns")
            if not isinstance(columns, list) or not 1 <= len(columns) <= _MAX_COLUMNS:
                _error("COLUMNS_REQUIRED")
            projected, headers = [], set()
            for column in columns:
                source_key = _source_key(source, column)
                header = _literal(_text(column.get("header", column["source"]), 2000, required=True))
                if header.casefold() in headers:
                    _error("COLUMN_HEADERS_MUST_BE_UNIQUE")
                headers.add(header.casefold())
                kind = column.get("type", "native")
                null, precision = column.get("null", "text"), column.get("precision", "preserve")
                if kind not in _TYPES or null not in {"blank", "text"} or precision not in {"preserve", "excel-number"}:
                    _error("COLUMN_PROJECTION_INVALID")
                projected.append({"source": column["source"], "header": header, "type": kind, "null": null,
                                  "null_text": _literal(_text(column.get("null_text", "NULL"), 1000)), "precision": precision,
                                  **({"source_index": source_key} if source["kind"] == "report" and "source_index" in column else {})})
            result.append({"name": label, "source": source, "columns": projected})
        _sheet_layout(result)
        return {"schema": _DEFINITION, "name": name, "title": title, "notes": notes, "sheets": result}

    def save(self, name, request, *, refresh_origin=None):
        request_id = _id(request.get("id"))
        expected = request.get("expected_revision")
        if type(expected) is not int or expected < 0:
            _error("REVISION_REQUIRED")
        normalized = self.compose(name, request)
        if refresh_origin is not None:
            normalized["refresh_origin"] = refresh_origin
        request_sha = digest(_json({"id": request_id, "expected_revision": expected, **normalized}).encode())
        with self.database._connection() as db:
            db.execute("BEGIN IMMEDIATE")
            old = db.execute("SELECT * FROM sf_analysis_workbook_history WHERE request_id=?", (request_id,)).fetchone()
            if old is not None:
                if old["request_sha256"] != request_sha:
                    _error("REQUEST_ID_REUSED")
                return {**_unpack(old), "definition_sha256": old["sha256"]}
            head = db.execute("SELECT revision FROM sf_analysis_workbooks WHERE name=?", (name,)).fetchone()
            if (head[0] if head else 0) != expected:
                _error("DEFINITION_CHANGED")
            record = {**normalized, "revision": expected + 1, "saved_at": _now(), "workspace_id": self.identity}
            raw = _json(record)
            sha = digest(raw.encode())
            db.execute("INSERT INTO sf_analysis_workbooks VALUES(?,?,?,?) ON CONFLICT(name) DO UPDATE SET revision=excluded.revision,record=excluded.record,sha256=excluded.sha256", (name, record["revision"], raw, sha))
            db.execute("INSERT INTO sf_analysis_workbook_history(name,revision,request_id,request_sha256,record,sha256) VALUES(?,?,?,?,?,?)", (name, record["revision"], request_id, request_sha, raw, sha))
            db.commit()
            return {**record, "definition_sha256": sha}

    def definition(self, name, *, revision=None):
        name = _name(name)
        if revision is not None and (type(revision) is not int or revision < 1):
            _error("REVISION_REQUIRED")
        with self.database._connection(readonly=True) as db:
            db.execute("BEGIN")
            if revision is None:
                row = db.execute("SELECT * FROM sf_analysis_workbooks WHERE name=?", (name,)).fetchone()
            else:
                row = db.execute("SELECT * FROM sf_analysis_workbook_history WHERE name=? AND revision=?", (name, revision)).fetchone()
            record = _unpack(row)
            return {"definition": record, "definition_sha256": row["sha256"],
                    "head_revision": db.execute("SELECT revision FROM sf_analysis_workbooks WHERE name=?", (name,)).fetchone()[0],
                    "history": [dict(r) for r in db.execute("SELECT revision,sha256 FROM sf_analysis_workbook_history WHERE name=? ORDER BY revision DESC LIMIT 100", (name,))]}

    def prepare(self, request):
        result = self.definition(request.get("name"), revision=request.get("revision"))
        if request.get("definition_sha256") != result["definition_sha256"]:
            _error("DEFINITION_CHANGED")
        return {"name": result["definition"]["name"], "revision": result["definition"]["revision"],
                "definition_sha256": result["definition_sha256"]}

    @contextmanager
    def _rows(self, source):
        current = self.source(source)
        if current != source:
            _error("SOURCE_CHANGED")
        if source["kind"] == "query-export":
            iterator = QueryExport(self.database.directory / "analysis-query-exports" / source["id"]).rows()
            try:
                yield iterator
            finally:
                iterator.close()
        else:
            with self.database._connection(readonly=True) as db:
                db.execute("BEGIN")
                publication, report = self.reports._export_input(db, {"publication_id": source["id"], "publication_sha256": source["sha256"]})
                selected = report["sections"][source["section"]]
                def values():
                    for cells in AnalysisReports._rows(db, report, selected):
                        result = []
                        for cell in cells:
                            kind, text = cell["type"], cell["text"]
                            result.append(None if kind == "null" else int(text) if kind == "integer" else float(text) if kind in {"number", "sqlite-real"} else base64.b64decode(text, validate=True) if kind == "blob" else text)
                        yield result
                yield values()

    def preview(self, name, *, revision=None, sheet=0, limit=20):
        result = self.definition(name, revision=revision)
        sheets = result["definition"]["sheets"]
        if type(sheet) is not int or not 0 <= sheet < len(sheets) or type(limit) is not int or not 1 <= limit <= 100:
            _error("PREVIEW_PAGE_INVALID")
        selected, rows = sheets[sheet], []
        keys = [_source_key(selected["source"], column) for column in selected["columns"]]
        with self._rows(selected["source"]) as stream:
            for row in stream:
                values = []
                for column, key in zip(selected["columns"], keys):
                    value, number_format, conversion = project_cell(row[key], column)
                    values.append({"value": value.isoformat() if isinstance(value, (date, datetime)) else str(value) if type(value) is int and abs(value) >= 2**53 else value,
                                   "excel_type": "blank" if value is None else "text" if isinstance(value, str) else "date" if isinstance(value, (date, datetime)) else "boolean" if isinstance(value, bool) else "number",
                                   "format": number_format, "conversion": conversion})
                rows.append(values)
                if len(rows) >= limit:
                    break
        return {"definition_sha256": result["definition_sha256"], "sheet": selected, "rows": rows,
                "row_count": selected["source"]["row_count"], "preview_only": len(rows) < selected["source"]["row_count"]}

    def _retain_source(self, source, target):
        target = target / "sources" / (source["kind"] + "-" + source["id"])
        if target.exists():
            return
        private_directory(target.parent)
        if source["kind"] == "query-export":
            QueryExport(self.database.directory / "analysis-query-exports" / source["id"]).copy_to(target)
            if digest(read(target / "manifest.json", 16 * 1024 * 1024)) != source["sha256"]:
                _error("SOURCE_CHANGED")
        else:
            private_directory(target)
            with self.database._connection(readonly=True) as db, (target / "report.json").open("xb") as output:
                os.fchmod(output.fileno(), 0o600)
                db.execute("BEGIN")
                publication, report = self.reports._export_input(db, {"publication_id": source["id"], "publication_sha256": source["sha256"]})
                for block in self.reports._json_blocks(db, publication, report):
                    output.write(block)
                output.flush()
                os.fsync(output.fileno())

    def build(self, definition, job_id, destination, *, cancel=lambda: False, progress=lambda value: None):
        """Build an entire portable delivery from pinned native results, without DB writes."""
        try:
            from openpyxl import Workbook
            from openpyxl.cell import WriteOnlyCell
            from openpyxl.styles import Alignment, Font, PatternFill
            from openpyxl.utils import get_column_letter
        except ImportError:
            _error("INSTALL_WORKBOOKS_EXTRA")
        job_id = _id(job_id)
        if definition.get("schema") != _DEFINITION or type(definition.get("revision")) is not int:
            _error("SAVED_DEFINITION_REQUIRED")
        raw = _json(definition).encode()
        definition_sha = digest(raw)
        layout = _sheet_layout(definition["sheets"])
        target = Path(destination).absolute()
        private_directory(target.parent)
        target.mkdir(mode=0o700)
        workbook = Workbook(write_only=True, iso_dates=True)
        workbook.properties.title = definition["title"]
        workbook.properties.creator = "Stellar Forge"
        workbook.properties.description = "Customer workbook with original typed results and source bindings in its handoff."
        header_fill = PatternFill("solid", fgColor="E7E7E7")
        header_font = Font(name="Calibri", size=11, bold=True, color="202020")
        outputs, total_rows = [], 0

        def stopped():
            if cancel():
                _error("CANCELLED")

        def cell(sheet, value, number_format=None, heading=False):
            item = WriteOnlyCell(sheet, value=value)
            if isinstance(value, str):
                item.data_type = "s"  # '=' remains original text, never a formula.
            if number_format:
                item.number_format = number_format
            if heading:
                item.fill, item.font = header_fill, header_font
                item.alignment = Alignment(vertical="top", wrap_text=True)
            return item

        def new_sheet(name, columns, row_count):
            sheet = workbook.create_sheet(name)
            sheet.freeze_panes = "A2"
            sheet.sheet_view.showGridLines = True
            sheet.auto_filter.ref = f"A1:{get_column_letter(len(columns))}{row_count + 1}"
            for index, column in enumerate(columns, 1):
                sheet.column_dimensions[get_column_letter(index)].width = min(48, max(14, len(column["header"]) + 3))
            sheet.append([cell(sheet, _literal(column["header"]), heading=True) for column in columns])
            return sheet

        try:
            write(target / "definition.json", raw)
            definition_history = self.refresh.retain_history(definition, target, cancel=cancel)
            for ordinal, logical in enumerate(definition["sheets"]):
                stopped()
                source = logical["source"]
                keys = [_source_key(source, column) for column in logical["columns"]]
                if self.source(source) != source:
                    _error("SOURCE_CHANGED")
                self._retain_source(source, target)
                expected = source["row_count"]
                counts, row_count, physical_index = {}, 0, 0
                sheet = new_sheet(layout[ordinal][0], logical["columns"], min(expected, _ROWS_PER_SHEET))
                with self._rows(source) as stream:
                    for values in stream:
                        stopped()
                        if row_count and row_count % _ROWS_PER_SHEET == 0:
                            physical_index += 1
                            sheet = new_sheet(layout[ordinal][physical_index], logical["columns"], min(expected - row_count, _ROWS_PER_SHEET))
                        cells = []
                        for index, (column, key) in enumerate(zip(logical["columns"], keys)):
                            value, format, conversion = project_cell(values[key], column)
                            cells.append(cell(sheet, value, format))
                            if conversion:
                                key = str(index) + ":" + conversion
                                counts[key] = counts.get(key, 0) + 1
                        sheet.append(cells)
                        row_count += 1
                        total_rows += 1
                        if row_count % 1000 == 0:
                            progress({"sheet": logical["name"], "sheet_rows": row_count, "total_rows": total_rows, "expected_rows": sum(s["source"]["row_count"] for s in definition["sheets"])})
                if row_count != expected:
                    _error("SOURCE_ROW_COUNT_CHANGED")
                outputs.append({"name": logical["name"], "worksheets": layout[ordinal], "row_count": row_count,
                                "source": source, "columns": logical["columns"], "conversions": counts})
                progress({"sheet": logical["name"], "sheet_rows": row_count, "total_rows": total_rows})
            readme = workbook.create_sheet("Readme")
            readme.column_dimensions["A"].width = 28
            readme.column_dimensions["B"].width = 110
            for key, value in [("Workbook", definition["title"]), ("Notes", definition["notes"]),
                               ("Saved definition", definition["name"] + " / revision " + str(definition["revision"])),
                               ("Definition SHA-256", definition_sha), ("Delivery", job_id),
                               ("Text and formulas", "All source strings are literal Excel text, including strings beginning with =. Source formulas are not evaluated."),
                               ("Precision", "Preserve keeps values beyond Excel's numeric precision as text. Excel-number is an explicit column choice. Decimal-text preserves original decimal spelling and scale."),
                               ("Null and empty text", "Each column selects a null label or an empty cell. Excel can display nulls and empty strings alike; the handoff retains their original typed values."),
                               ("Dates", "ISO dates use the 1900 date system. UTC timestamps require a timezone. Values before 1900 or beyond millisecond precision remain original text."),
                               ("Complete rows", "Each data sheet includes every selected source row. Larger results continue on numbered sheets, with a header repeated on each sheet."),
                               ("Offline handoff", "Open manifest.json and the original source exports alongside this workbook to recover exact input types, query bindings, and projections.")]:
                readme.append([cell(readme, key, heading=True), cell(readme, _literal(value))])
            if definition.get("refresh_origin"):
                origin = definition["refresh_origin"]
                readme.append([cell(readme, "Edition note", heading=True), cell(readme, _literal(origin["reason"]))])
                readme.append([cell(readme, "Previous definition", heading=True), cell(readme, origin["base_definition_file"])])
            meta = new_sheet("Sources", [{"header": h} for h in ["Sheet", "Source kind", "Source ID", "Source SHA-256", "Rows", "Input column", "Input ordinal", "Excel heading", "Type", "Null", "Precision"]], sum(len(s["columns"]) for s in outputs))
            for logical in outputs:
                for column in logical["columns"]:
                    values = [logical["name"], logical["source"]["kind"], logical["source"]["id"], logical["source"]["sha256"], logical["row_count"], column["source"], _source_key(logical["source"], column) + 1 if logical["source"]["kind"] == "report" else "", column["header"], column["type"], "blank" if column["null"] == "blank" else column["null_text"], column["precision"]]
                    meta.append([cell(meta, value) for value in values])
            stopped()
            workbook_path = target / "workbook.xlsx"
            with workbook_path.open("xb") as output:
                os.fchmod(output.fileno(), 0o600)
                workbook.save(output)
                output.flush()
                os.fsync(output.fileno())
            files = {}
            for path in sorted(target.rglob("*")):
                if path.is_file():
                    relative = path.relative_to(target).as_posix()
                    _relative(relative)
                    files[relative] = _file_record(path)
            manifest = {"schema": _SCHEMA, "complete": True, "id": job_id, "workspace_id": self.identity,
                        "name": definition["name"], "revision": definition["revision"], "title": definition["title"],
                        "definition_sha256": definition_sha, "created_at": _now(), "row_count": total_rows,
                        "sheets": outputs, "files": files, "definition_history": definition_history, "excel": {"date_system": "1900", "date_encoding": "ISO8601", "strings": "literal", "data_rows_per_sheet": _ROWS_PER_SHEET}}
            manifest_raw = _json(manifest).encode()
            if len(manifest_raw) > _MAX_MANIFEST:
                _error("MANIFEST_TOO_LARGE")
            write(target / "manifest.json", manifest_raw)
            stopped()
            with (target / "handoff.zip").open("xb") as output:
                os.fchmod(output.fileno(), 0o600)
                with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=6, allowZip64=True) as package:
                    for name in [*files, "manifest.json"]:
                        stopped()
                        info = zipfile.ZipInfo(name)
                        info.compress_type = zipfile.ZIP_DEFLATED
                        info.external_attr = 0o100600 << 16
                        with _open_private(target / name) as source, package.open(info, "w", force_zip64=True) as member:
                            shutil.copyfileobj(source, member, 1024 * 1024)
                output.flush()
                os.fsync(output.fileno())
            sync_directory(target)
            return self._completed(target, expected_definition=definition_sha, inspect=False)
        except BaseException:
            shutil.rmtree(target)
            raise
        finally:
            workbook.close()
            # openpyxl removes its worksheet staging files on successful save.
            # Close and remove only staging paths owned by this failed workbook.
            for sheet in workbook.worksheets:
                writer = getattr(sheet, "_writer", None)
                if writer is not None and isinstance(writer.out, str) and os.path.exists(writer.out):
                    try:
                        sheet.close()
                    finally:
                        Path(writer.out).unlink(missing_ok=True)

    def _completed(self, path, *, expected_definition, inspect=True):
        delivery = WorkbookDelivery(path)
        manifest = delivery.inspect() if inspect else delivery.manifest
        if manifest["definition_sha256"] != expected_definition:
            _error("DEFINITION_CHANGED")
        if manifest["id"] != path.name:
            _error("DELIVERY_ID_CHANGED")
        if inspect:
            try:
                delivery.verify_archive(path / "handoff.zip")
            except zipfile.BadZipFile:
                _error("COMPLETE_ARCHIVE_REQUIRED")
        files = [{"name": name, **(_file_record(path / name) if name == "handoff.zip" else
                   {"bytes": len(delivery.raw), "sha256": digest(delivery.raw)} if name == "manifest.json" else manifest["files"][name]), "mime": mime}
                 for name, mime in _MIMES.items()]
        return {"schema": _SCHEMA, "id": manifest["id"], "name": manifest["name"], "revision": manifest["revision"],
                "title": manifest["title"], "definition_sha256": expected_definition, "directory": str(path),
                "manifest_sha256": digest(delivery.raw), "row_count": manifest["row_count"],
                "sheets": manifest["sheets"], "files": files, "completed_at": manifest["created_at"]}

    def _progress(self, job_id, values):
        with self.database._connection() as db:
            db.execute("INSERT INTO sf_analysis_workbook_control(id,progress) VALUES(?,?) ON CONFLICT(id) DO UPDATE SET progress=excluded.progress", (job_id, _json({**values, "updated_at": _now()})))

    def progress(self, job_id):
        with self.database._connection(readonly=True) as db:
            row = db.execute("SELECT progress,cancel_requested FROM sf_analysis_workbook_control WHERE id=?", (_id(job_id),)).fetchone()
        return {**parse(row["progress"].encode()), "cancel_requested": bool(row["cancel_requested"])} if row else {}

    def cancel(self, job_id):
        job_id = _id(job_id)
        with self.database._connection() as db:
            row = db.execute("SELECT status FROM sf_analysis_jobs WHERE id=? AND kind='workbook'", (job_id,)).fetchone()
            if row is None:
                _error("NOT_FOUND")
            if row["status"] == "RUNNING":
                db.execute("INSERT INTO sf_analysis_workbook_control(id,cancel_requested,progress) VALUES(?,1,'{}') ON CONFLICT(id) DO UPDATE SET cancel_requested=1", (job_id,))
        with self._mutex:
            if job_id in self._signals:
                self._signals[job_id].set()
        return self.progress(job_id)

    def close(self):
        with self._mutex:
            self._closed = True
            for signal in self._signals.values():
                signal.set()

    def _finish(self, job_id, status, *, result=None, error=None):
        with self.database._connection() as db:
            db.execute("UPDATE sf_analysis_jobs SET status=?,result=?,error=?,finished_at=? WHERE id=? AND kind='workbook'", (status, _json(result) if result else None, error, _now(), job_id))

    def run(self, job_id, spec):
        job_id = _id(job_id)
        path = self.directory / job_id
        with self._mutex:
            signal = self._signals.setdefault(job_id, threading.Event())
            if self._closed or self.progress(job_id).get("cancel_requested"):
                signal.set()
        try:
            definition = self.definition(spec["name"], revision=spec["revision"])
            if definition["definition_sha256"] != spec["definition_sha256"]:
                _error("DEFINITION_CHANGED")
            result = self.build(definition["definition"], job_id, path, cancel=signal.is_set,
                                progress=lambda value: self._progress(job_id, value))
            self._finish(job_id, "COMPLETE", result=result)
        except BaseException as exc:
            try:
                result = self._completed(path, expected_definition=spec["definition_sha256"])
            except (BuyerError, OSError, ValueError, TypeError, KeyError):
                code = getattr(exc, "code", None) or type(exc).__name__
                self._finish(job_id, "CANCELLED" if code == "ANALYSIS_WORKBOOK_CANCELLED" else "FAILED", error=str(code)[:256])
            else:
                self._finish(job_id, "COMPLETE", result=result)
        finally:
            with self._mutex:
                self._signals.pop(job_id, None)

    def recover_completed(self):
        with self.database._connection(readonly=True) as db:
            rows = db.execute("SELECT id,request FROM sf_analysis_jobs WHERE kind='workbook' AND status IN ('INTERRUPTED','FAILED','CANCELLED')").fetchall()
        for row in rows:
            spec = parse(row["request"].encode())
            path = self.directory / row["id"]
            if not (path / "handoff.zip").is_file():
                continue
            try:
                result = self._completed(path, expected_definition=spec["definition_sha256"])
            except (BuyerError, OSError, ValueError, TypeError, KeyError):
                continue
            self._finish(row["id"], "COMPLETE", result=result)

    def history(self, *, before=None, limit=25):
        _page(before, limit)
        with self.database._connection(readonly=True) as db:
            rows = db.execute("SELECT sequence,id,status,created_at,finished_at,request,result,error FROM sf_analysis_jobs WHERE kind='workbook' AND (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?", (before, before, limit + 1)).fetchall()
        items = []
        for row in rows[:limit]:
            request = parse(row["request"].encode())
            item = {key: row[key] for key in ("sequence", "id", "status", "created_at", "finished_at", "error")}
            item.update(name=request["name"], revision=request["revision"], progress=self.progress(row["id"]))
            if row["result"]:
                result = parse(row["result"].encode())
                item.update(row_count=result["row_count"], sheets=len(result["sheets"]), files=result["files"], title=result["title"], manifest_sha256=result["manifest_sha256"])
            items.append(item)
        return {"items": items, "next_before": rows[limit - 1]["sequence"] if len(rows) > limit else None}

    @contextmanager
    def download(self, job_id, name):
        job_id = _id(job_id)
        if name not in _MIMES:
            _error("FILE_INVALID")
        with self.database._connection(readonly=True) as db:
            row = db.execute("SELECT result FROM sf_analysis_jobs WHERE id=? AND kind='workbook' AND status='COMPLETE'", (job_id,)).fetchone()
        if row is None or row["result"] is None:
            _error("COMPLETE_DELIVERY_REQUIRED")
        result = parse(row["result"].encode())
        path = self.directory / job_id
        delivery = WorkbookDelivery(path, expected_manifest_sha256=result["manifest_sha256"])
        record = next((f for f in result["files"] if f["name"] == name), None)
        if record is None:
            _error("FILE_INVALID")
        if name == "handoff.zip":
            with _open_private(path / name) as stream:
                if os.fstat(stream.fileno()).st_size != record["bytes"] or hashlib.file_digest(stream, "sha256").hexdigest() != record["sha256"]:
                    _error("FILE_CHANGED")
                stream.seek(0)
                yield stream, record
        else:
            with delivery.open(name) as stream:
                yield stream, record


def main():
    parser = argparse.ArgumentParser(description="Inspect, receive or copy a complete customer workbook handoff offline.")
    commands = parser.add_subparsers(dest="command", required=True)
    inspect = commands.add_parser("inspect")
    inspect.add_argument("--delivery", required=True)
    inspect.add_argument("--manifest-sha256")
    copy = commands.add_parser("copy")
    copy.add_argument("--delivery", required=True)
    copy.add_argument("--destination", required=True)
    copy.add_argument("--manifest-sha256")
    receive = commands.add_parser("receive")
    receive.add_argument("--archive", required=True)
    receive.add_argument("--destination", required=True)
    receive.add_argument("--sha256")
    receive.add_argument("--max-bytes", type=int, default=1024 * 1024 * 1024)
    args = parser.parse_args()
    if args.command == "receive":
        delivery = WorkbookDelivery.receive(args.archive, args.destination, expected_sha256=args.sha256, max_bytes=args.max_bytes)
    else:
        delivery = WorkbookDelivery(args.delivery, expected_manifest_sha256=args.manifest_sha256)
        if args.command == "copy":
            delivery = delivery.copy_to(args.destination)
    print(_json(delivery.inspect()))


if __name__ == "__main__":
    main()

