    'CITATION_MERCHANT_ORIGINAL_REQUEST_REQUIRED');
  need(!Object.hasOwn(reviewRequest,'workspace')&&!Object.hasOwn(reviewRequest,'dossierId'),
    'CITATION_MERCHANT_USE_ORIGINAL_REVIEW_REQUEST');
