    need(!state.preparedArtifacts[name]||same(state.preparedArtifacts[name],selected),'CITATION_MERCHANT_PREPARED_ARTIFACT_CHANGED');
    need(!data.includes(Buffer.from(token)),'CITATION_MERCHANT_SESSION_IN_REPORT');
