#!/usr/bin/env node
// MIT. Enrich an existing original dossier and retain complete Crossref editions.
import {parseArgs} from 'node:util';
import {resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {openDossierStore} from './dossier.mjs';
import {receiveCrossrefEdition,receiveCrossrefBuyerResult,enrichCrossrefDossier,compareCrossrefMetadata,validateCrossrefEdition} from './crossref.mjs';
import {readBytes,parseJson,writeBytes,jsonBytes,need} from '../node/store.mjs';
import {createCrossrefSource} from '../../sf30-seller-sdk/crossref/source.mjs';
import {readCrossrefConfig} from '../../sf30-seller-sdk/crossref/config.mjs';
import {crossrefSourceOptions} from '../../sf30-seller-sdk/crossref/merchant.mjs';

const usage='Crossref in the original research dossier\n\n'+
  '  import --store DIR --id ID --question ID --revision N --file CAPTURE_PACK_JSON [--label TEXT]\n'+
  '  import-buyer --store DIR --id ID --question ID --revision N --buyer-state DIR --runtime DIR --intent ID [--label TEXT]\n'+
  '  enrich --store DIR --id ID --question ID --revision N --config CROSSREF_CONFIG --state SOURCE_DIR [--all-sources] [--metadata-only] [--label TEXT]\n'+
  '  compare --store DIR --id ID --before N --after N [--out JSON]\n';
export async function main(args=process.argv.slice(2)){
  const command=args[0];if(!command||['help','--help','-h'].includes(command)){process.stdout.write(usage);return;}
  const keys=['store','id','question','revision','file','label','buyer-state','runtime','intent','config','state','before','after','out','max-update-pages'];
  const {values}=parseArgs({args:args.slice(1),strict:true,options:{
    ...Object.fromEntries(keys.map(key=>[key,{type:'string'}])),'all-sources':{type:'boolean'},'metadata-only':{type:'boolean'}}});
  need(values.store&&values.id,'DOSSIER_STORE_AND_ID_REQUIRED');
  const store=await openDossierStore(resolve(values.store));
  const revision=Number(values.revision),common={questionId:values.question,expectedRevision:revision,...(values.label?{label:values.label}:{})};
  let result;
  if(command==='compare'){
    const before=await store.get(values.id,{revision:Number(values.before)}),after=await store.get(values.id,{revision:Number(values.after)});
    result=compareCrossrefMetadata(before,after);
  }else{
    need(values.revision!==undefined&&Number.isSafeInteger(revision)&&revision>=0&&values.question,'DOSSIER_QUESTION_AND_REVISION_REQUIRED');
    if(command==='import'){
      need(values.file,'CROSSREF_CAPTURE_PACK_REQUIRED');
      const input=parseJson(await readBytes(resolve(values.file),64*1024*1024));
      if(input.schema==='sf88-research-results-v1'){
        validateCrossrefEdition(input);
        result=await store.receive(values.id,{...common,provider:'crossref',label:values.label??input.label,
          rawBytes:await readBytes(resolve(values.file),64*1024*1024)});
      }else{
        need(input.schema==='stellar-forge.crossref-capture-pack.v1'&&Array.isArray(input.captures),'CROSSREF_CAPTURE_PACK_REQUIRED');
        result=await receiveCrossrefEdition(store,values.id,{...common,captures:input.captures,dois:input.dois,
          sourceReference:input.sourceReference??''});
      }
    }else if(command==='import-buyer'){
      need(values['buyer-state']&&values.runtime&&values.intent,'ORIGINAL_BUYER_INPUT_REQUIRED');
      const {Buyer}=await import('../node/client.mjs');
      const buyer=new Buyer({stateDirectory:resolve(values['buyer-state']),runtimeDirectory:resolve(values.runtime)});
      const saved=await buyer.operation(values.intent).recover();need(saved,'ORIGINAL_RESULT_NOT_RECORDED');
      result=await receiveCrossrefBuyerResult(store,values.id,{...common,result:saved,intentId:values.intent});
    }else{
      need(command==='enrich'&&values.config&&values.state,'CROSSREF_ENRICH_INPUT_REQUIRED');
      const compiled=await readCrossrefConfig(values.config);
      const source=await createCrossrefSource(crossrefSourceOptions(compiled,{sourceDirectory:resolve(values.state)}));
      const controller=new AbortController(),cancel=()=>controller.abort();
      process.once('SIGINT',cancel);process.once('SIGTERM',cancel);
      try{
        result=await enrichCrossrefDossier(store,values.id,{...common,source,selectedOnly:!values['all-sources'],
          includeUpdates:!values['metadata-only'],signal:controller.signal,
          maxUpdatePages:values['max-update-pages']===undefined?1000:Number(values['max-update-pages'])});
      }finally{process.removeListener('SIGINT',cancel);process.removeListener('SIGTERM',cancel);await source.close();}
    }
  }
  if(values.out)await writeBytes(resolve(values.out),jsonBytes(result),{exclusive:true});
  const {dossier,...summary}=result;
  process.stdout.write(JSON.stringify(dossier?summary:{dossierId:result.id??values.id,revision:result.revision,...(command==='compare'?result:{})},null,2)+'\n');
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  main().catch(error=>{process.stderr.write(JSON.stringify({error:error.code??'CROSSREF_DOSSIER_COMMAND_FAILED'})+'\n');process.exitCode=1;});
}

#!/usr/bin/env node
// MIT. Local-only source-document intake; this command never fetches a URL.
import fs from 'node:fs/promises';
import path from 'node:path';
import {randomUUID} from 'node:crypto';
import {buildCrossrefDocumentEdition, validateCrossrefDocumentEdition} from './crossref-documents.mjs';
import {sha256, need, object} from '../../sf30-seller-sdk/crossref/metadata.mjs';

const HELP = 'Usage: node crossref-document-cli.mjs --provenance FILE --source-dir DIRECTORY --query TEXT --output FILE\n' +
  '  [--label TEXT] [--doi DOI ...] [--updates-doi DOI ...] [--supporting RELATIVE_FILE ...]\n' +
  'The provenance JSON supplies sources[{filename,source_url,bytes,sha256}]. Original source and provenance bytes are retained.\n' +
  'Optional per-source retrieved_at and provenance preserve observed information; an absent upstream timestamp stays null.\n';

function options(argv) {
  const result = {dois:[], updatesDois:[], supporting:[]};
  const singular = new Set(['provenance','source-dir','query','output','label']);
  const multiple = new Set(['doi','updates-doi','supporting']);
  for (let index = 0; index < argv.length; index++) {
    const argument = argv[index];
    if (argument === '--help' || argument === '-h') { result.help = true; continue; }
    need(argument.startsWith('--'), 'CROSSREF_DOCUMENT_CLI_ARGUMENT_INVALID');
    const key = argument.slice(2);
    need(singular.has(key) || multiple.has(key), 'CROSSREF_DOCUMENT_CLI_OPTION_UNKNOWN');
    const value = argv[++index];
    need(typeof value === 'string' && value.length > 0 && !value.startsWith('--'), 'CROSSREF_DOCUMENT_CLI_VALUE_REQUIRED');
    if (singular.has(key)) {
      need(result[key] === undefined, 'CROSSREF_DOCUMENT_CLI_OPTION_DUPLICATED');
      result[key] = value;
    } else result[key === 'doi' ? 'dois' : key === 'updates-doi' ? 'updatesDois' : 'supporting'].push(value);
  }
  if (!result.help) for (const key of ['provenance','source-dir','query','output'])
    need(typeof result[key] === 'string', 'CROSSREF_DOCUMENT_CLI_REQUIRED_OPTION');
  return result;
}
async function boundedFile(file, maxBytes) {
  const handle = await fs.open(file, 'r');
  try {
    const info = await handle.stat();
    need(info.isFile() && info.size > 0 && info.size <= maxBytes, 'CROSSREF_DOCUMENT_FILE_SIZE_INVALID');
    const parts = [], buffer = Buffer.alloc(Math.min(64 * 1024, info.size + 1));
    let total = 0;
    while (true) {
      const {bytesRead} = await handle.read(buffer, 0, buffer.length, null);
      if (!bytesRead) break;
      total += bytesRead;
      need(total <= maxBytes, 'CROSSREF_DOCUMENT_FILE_SIZE_INVALID');
      parts.push(Buffer.from(buffer.subarray(0, bytesRead)));
    }
    need(total === info.size, 'CROSSREF_DOCUMENT_FILE_CHANGED');
    return Buffer.concat(parts, total);
  } finally { await handle.close(); }
}
async function sourceFile(root, relative) {
  need(typeof relative === 'string' && relative && !path.isAbsolute(relative) &&
    !/^[A-Za-z]:|[\\\u0000-\u001f\u007f]/.test(relative) &&
    relative.split('/').every(part => part && part !== '.' && part !== '..'), 'CROSSREF_DOCUMENT_SOURCE_PATH_INVALID');
  const actual = await fs.realpath(path.resolve(root, relative));
  const within = path.relative(root, actual);
  need(within && !within.startsWith('..' + path.sep) && within !== '..' && !path.isAbsolute(within),
    'CROSSREF_DOCUMENT_SOURCE_PATH_OUTSIDE_ROOT');
  return actual;
}
async function saveExact(file, bytes) {
  await fs.mkdir(path.dirname(file), {recursive:true});
  let previous;
  try { previous = await boundedFile(file, 64 * 1024 * 1024); }
  catch (error) { if (error.code !== 'ENOENT') throw error; }
  if (previous) {
    need(previous.equals(bytes), 'CROSSREF_DOCUMENT_OUTPUT_EXISTS_DIFFERENT');
    return {reused:true};
  }
  const temporary = file + '.pending-' + randomUUID();
  const handle = await fs.open(temporary, 'wx', 0o600);
  let linked = false;
  try {
    await handle.writeFile(bytes); await handle.sync(); await handle.close();
    try { await fs.link(temporary, file); linked = true; }
    catch (error) {
      if (error.code !== 'EEXIST') throw error;
      const concurrent = await boundedFile(file, 64 * 1024 * 1024);
      need(concurrent.equals(bytes), 'CROSSREF_DOCUMENT_OUTPUT_EXISTS_DIFFERENT');
    }
    const directory = await fs.open(path.dirname(file), 'r');
    try { await directory.sync(); } finally { await directory.close(); }
    return {reused:!linked};
  } finally {
    await handle.close().catch(() => {});
    await fs.unlink(temporary).catch(error => { if (error.code !== 'ENOENT') throw error; });
  }
}

async function main() {
  const input = options(process.argv.slice(2));
  if (input.help) { process.stdout.write(HELP); return; }
  const root = await fs.realpath(input['source-dir']);
  const manifestPath = await fs.realpath(input.provenance);
  const manifestBytes = await boundedFile(manifestPath, 16 * 1024 * 1024);
  let manifest;
  try { manifest = JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(manifestBytes)); }
  catch { need(false, 'CROSSREF_DOCUMENT_MANIFEST_JSON_INVALID'); }
  need(object(manifest) && Array.isArray(manifest.sources) && manifest.sources.length > 0 &&
    manifest.sources.length <= 1998, 'CROSSREF_DOCUMENT_MANIFEST_INVALID');
  const manifestSha256 = sha256(manifestBytes);
  const documents = [];
  for (const source of manifest.sources) {
    need(object(source) && typeof source.filename === 'string' && typeof source.source_url === 'string' &&
      Number.isSafeInteger(source.bytes) && source.bytes > 0 &&
      typeof source.sha256 === 'string' && /^[0-9a-f]{64}$/.test(source.sha256),
      'CROSSREF_DOCUMENT_MANIFEST_SOURCE_INVALID');
    const file = await sourceFile(root, source.filename);
    const body = await boundedFile(file, 16 * 1024 * 1024);
    need(body.length === source.bytes && sha256(body) === source.sha256, 'CROSSREF_DOCUMENT_MANIFEST_BYTES_MISMATCH');
    documents.push({
      filename:source.filename, body, sourceUrl:source.source_url, role:'source',
      retrievedAt:source.retrieved_at ?? source.retrievedAt ?? null,
      provenance:{
        manifestSha256, sourceEntry:source, transfer:manifest.transport ?? null,
        retainedAt:manifest.retained_at ?? null, originalProvenance:source.provenance ?? null
      }
    });
  }
  const manifestRelative = path.relative(root, manifestPath);
  const manifestName = manifestRelative && !manifestRelative.startsWith('..' + path.sep) &&
    manifestRelative !== '..' && !path.isAbsolute(manifestRelative)
    ? manifestRelative.split(path.sep).join('/') : path.basename(manifestPath);
  documents.push({filename:manifestName, body:manifestBytes, role:'provenance',
    provenance:{kind:'original-source-manifest', schema:manifest.schema ?? null}});
  for (const relative of input.supporting) {
    const body = await boundedFile(await sourceFile(root, relative), 16 * 1024 * 1024);
    documents.push({filename:relative, body, role:'supporting-document', provenance:{kind:'supplied-supporting-document'}});
  }
  const envelope = buildCrossrefDocumentEdition({
    documents, query:input.query, ...(input.label ? {label:input.label} : {}),
    ...(input.dois.length ? {dois:input.dois} : {}),
    ...(input.updatesDois.length ? {updatesDois:input.updatesDois} : {})
  });
  validateCrossrefDocumentEdition(envelope);
  const bytes = Buffer.from(JSON.stringify(envelope, null, 2) + '\n');
  need(bytes.length <= 64 * 1024 * 1024, 'RESEARCH_RESPONSE_TOO_LARGE');
  const output = path.resolve(input.output);
  const saved = await saveExact(output, bytes);
  const readback = await boundedFile(output, 64 * 1024 * 1024);
  need(readback.equals(bytes), 'CROSSREF_DOCUMENT_OUTPUT_READBACK_MISMATCH');
  process.stdout.write(JSON.stringify({
    schema:'stellar-forge.crossref-document-intake-receipt.v1', provider:envelope.provider,
    output, bytes:bytes.length, sha256:sha256(bytes), reused:saved.reused,
    sourceDocuments:envelope.usage.sourcePages, originalDocuments:envelope.originalDocuments.length,
    results:envelope.results.length, coverage:envelope.usage.coverage,
    requestedDois:envelope.usage.requestedDois, updateRequestedDois:envelope.usage.updateRequestedDois,
    updates:envelope.usage.updates.map(({documents,...row}) => row),
    warnings:envelope.warnings
  }, null, 2) + '\n');
}
main().catch(error => {
  process.stderr.write(JSON.stringify({code:error.code ?? 'CROSSREF_DOCUMENT_INTAKE_FAILED', message:error.message}) + '\n');
  process.exitCode = 1;
});

// MIT. Retained Crossref source documents join the original Research edition format.
import {
  EDITION_SCHEMA, SOURCE_TERMS, ORIGIN, normalizeDoi, doiList,
  sha256, need, fail, object, projectCrossrefWork
} from '../../sf30-seller-sdk/crossref/metadata.mjs';

export const CROSSREF_DOCUMENT_SCHEMA = 'stellar-forge.crossref-source-document.v1';
export const CROSSREF_DOCUMENT_EDITION_SCHEMA = 'stellar-forge.crossref-document-edition.v1';
const MAX_BODY = 16 * 1024 * 1024;
const MAX_RAW = 40 * 1024 * 1024;
const MAX_EDITION = 64 * 1024 * 1024;
const ROLES = new Set(['source', 'provenance', 'supporting-document']);

function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  if (object(value)) return Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])]));
  return value;
}
const stable = value => JSON.stringify(canonical(value));
function cloneJson(value, code = 'CROSSREF_DOCUMENT_PROVENANCE_INVALID') {
  const seen = new Set();
  function visit(item, depth) {
    need(depth <= 64, code);
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return;
    if (typeof item === 'number') { need(Number.isFinite(item), code); return; }
    need((Array.isArray(item) || (object(item) && [Object.prototype, null].includes(Object.getPrototypeOf(item)))) && !seen.has(item), code);
    seen.add(item);
    for (const child of Array.isArray(item) ? item : Object.values(item)) visit(child, depth + 1);
    seen.delete(item);
  }
  visit(value, 0);
  return JSON.parse(JSON.stringify(value));
}
function filename(value) {
  need(typeof value === 'string' && value.length > 0 && value.length <= 1024 &&
    !/^[\/\\]|^[A-Za-z]:/.test(value) && !/[\\\u0000-\u001f\u007f]/.test(value) &&
    value.split('/').every(part => part && part !== '.' && part !== '..'), 'CROSSREF_DOCUMENT_FILENAME_INVALID');
  return value;
}
function sourceUrl(value, required) {
  if (value === undefined || value === null) {
    need(!required, 'CROSSREF_DOCUMENT_SOURCE_URL_REQUIRED');
    return null;
  }
  need(typeof value === 'string' && value.length <= 20000, 'CROSSREF_DOCUMENT_SOURCE_URL_INVALID');
  let url;
  try { url = new URL(value); } catch { fail('CROSSREF_DOCUMENT_SOURCE_URL_INVALID'); }
  need(url.protocol === 'https:' && !url.username && !url.password && !url.hash,
    'CROSSREF_DOCUMENT_SOURCE_URL_INVALID');
  if (required) need(url.origin === ORIGIN, 'CROSSREF_DOCUMENT_OFFICIAL_SOURCE_REQUIRED');
  return value;
}
function decodeJson(bytes, code) {
  try { return JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(bytes)); }
  catch { fail(code); }
}

/** Exact bytes and documentary provenance; no HTTP-capture fields are synthesized. */
export function parseCrossrefDocument(input) {
  need(object(input), 'CROSSREF_DOCUMENT_REQUIRED');
  const role = input.role ?? 'source';
  need(ROLES.has(role), 'CROSSREF_DOCUMENT_ROLE_INVALID');
  let bytes;
  if (input.body instanceof Uint8Array) bytes = Buffer.from(input.body);
  else {
    need(typeof input.bodyBase64 === 'string' &&
      /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(input.bodyBase64),
      'CROSSREF_DOCUMENT_BYTES_REQUIRED');
    bytes = Buffer.from(input.bodyBase64, 'base64');
    need(bytes.toString('base64') === input.bodyBase64, 'CROSSREF_DOCUMENT_ENCODING_INVALID');
  }
  need(bytes.length > 0 && bytes.length <= MAX_BODY, 'CROSSREF_DOCUMENT_SIZE_LIMIT', 413);
  const bodySha256 = sha256(bytes);
  if (input.bodySha256 !== undefined) need(input.bodySha256 === bodySha256, 'CROSSREF_DOCUMENT_BODY_HASH_MISMATCH');
  if (input.bodyBytes !== undefined) need(input.bodyBytes === bytes.length, 'CROSSREF_DOCUMENT_BODY_LENGTH_MISMATCH');
  const retrievedAt = input.retrievedAt ?? null;
  need(retrievedAt === null || (typeof retrievedAt === 'string' && Number.isFinite(Date.parse(retrievedAt))),
    'CROSSREF_DOCUMENT_TIME_INVALID');
  need(object(input.provenance ?? {}), 'CROSSREF_DOCUMENT_PROVENANCE_INVALID');
  const provenance = cloneJson(input.provenance ?? {});
  need(Buffer.byteLength(JSON.stringify(provenance)) <= 256 * 1024, 'CROSSREF_DOCUMENT_PROVENANCE_SIZE_LIMIT', 413);
  const identity = {
    schema:CROSSREF_DOCUMENT_SCHEMA, filename:filename(input.filename), role,
    sourceUrl:sourceUrl(input.sourceUrl, role === 'source'), retrievedAt, provenance,
    bodyBytes:bytes.length, bodySha256
  };
  const documentSha256 = sha256(stable(identity));
  const documentId = 'crdoc_' + documentSha256;
  if (input.schema !== undefined) need(input.schema === CROSSREF_DOCUMENT_SCHEMA, 'CROSSREF_DOCUMENT_SCHEMA_INVALID');
  if (input.documentSha256 !== undefined) need(input.documentSha256 === documentSha256, 'CROSSREF_DOCUMENT_HASH_MISMATCH');
  if (input.documentId !== undefined) need(input.documentId === documentId, 'CROSSREF_DOCUMENT_ID_MISMATCH');
  const record = {...identity, documentId, documentSha256, bodyBase64:bytes.toString('base64')};
  if (role === 'provenance') {
    need(object(decodeJson(bytes, 'CROSSREF_DOCUMENT_PROVENANCE_JSON_INVALID')),
      'CROSSREF_DOCUMENT_PROVENANCE_JSON_INVALID');
  }
  if (role !== 'source') return {record, bytes, value:null, request:null};
  const value = decodeJson(bytes, 'CROSSREF_DOCUMENT_JSON_INVALID');
  need(object(value) && value.status === 'ok' && object(value.message),
    'CROSSREF_DOCUMENT_RESPONSE_CONTRACT_INVALID');
  const url = new URL(record.sourceUrl);
  let request;
  if (url.pathname.startsWith('/works/') && url.pathname.length > 7) {
    let requested;
    try { requested = normalizeDoi(decodeURIComponent(url.pathname.slice(7))); }
    catch { fail('CROSSREF_DOCUMENT_REQUEST_DOI_INVALID'); }
    need(value['message-type'] === 'work', 'CROSSREF_DOCUMENT_RESPONSE_TYPE_MISMATCH');
    need(normalizeDoi(value.message.DOI) === requested, 'CROSSREF_DOCUMENT_RESPONSE_DOI_MISMATCH');
    request = {kind:'work', doi:requested, url:record.sourceUrl};
  } else {
    need(url.pathname === '/works' || url.pathname === '/works/', 'CROSSREF_DOCUMENT_ENDPOINT_UNSUPPORTED');
    need(value['message-type'] === 'work-list' && Array.isArray(value.message.items) &&
      Number.isSafeInteger(value.message['total-results']) && value.message['total-results'] >= 0 &&
      value.message.items.every(row => { try { return object(row) && Boolean(normalizeDoi(row.DOI)); } catch { return false; } }),
      'CROSSREF_DOCUMENT_LIST_INVALID');
    for (const key of ['rows', 'cursor', 'offset', 'filter', 'select'])
      need(url.searchParams.getAll(key).length <= 1, 'CROSSREF_DOCUMENT_QUERY_AMBIGUOUS');
    const numberParam = (key, minimum, maximum) => {
      if (!url.searchParams.has(key)) return null;
      const raw = url.searchParams.get(key);
      need(/^\d+$/.test(raw), 'CROSSREF_DOCUMENT_QUERY_NUMBER_INVALID');
      const number = Number(raw);
      need(Number.isSafeInteger(number) && number >= minimum && number <= maximum, 'CROSSREF_DOCUMENT_QUERY_NUMBER_INVALID');
      return number;
    };
    const explicitRows = numberParam('rows', 0, 1000);
    const reportedRows = value.message['items-per-page'];
    const rows = explicitRows ?? (Number.isSafeInteger(reportedRows) && reportedRows >= 0 && reportedRows <= 1000 ? reportedRows : null);
    const offset = numberParam('offset', 0, Number.MAX_SAFE_INTEGER);
    const cursor = url.searchParams.get('cursor');
    need(cursor === null || (cursor.length > 0 && cursor.length <= 12000 && !/[\u0000-\u001f\u007f]/.test(cursor)),
      'CROSSREF_DOCUMENT_CURSOR_INVALID');
