        else if (seenPositions.has(next)) issues.add('CROSSREF_DOCUMENT_CURSOR_NOT_ADVANCING');
        else nextCursor = next;
        expected = nextCursor;
      } else {
        if (position !== null && request.rows !== null && request.rows > 0) nextOffset = position + request.rows;
        expected = nextOffset;
      }
    }
  }
