      if (note !== undefined) selection.note = text(note, 'EVIDENCE_NOTE_INVALID', 100000, true);
      if (classification !== undefined) {
        need(['supports', 'contradicts', 'background', 'unreviewed'].includes(classification), 'CLASSIFICATION_INVALID');
