    /^epq_[a-f0-9]{64}$/.test(queryId||'')&&/^d_[a-f0-9-]{36}$/.test(dossierId||''),
    'EUROPE_PMC_MERCHANT_ORIGINAL_SELECTION_REQUIRED');
