import {need,object} from '../node/store.mjs';
import {inspectResearchSources,inspectResearchComparison} from './source-inspection.mjs';

import {RESEARCH_WORKSPACE_API,RESEARCH_WORKSPACE_CONNECTION,RESEARCH_SECTIONS,RESEARCH_PAGE_LIMIT,RESEARCH_CONTROL_LIMIT,RESEARCH_COMPARISON_SECTIONS} from './workspace-contracts.mjs';
export {RESEARCH_WORKSPACE_API,RESEARCH_WORKSPACE_CONNECTION,RESEARCH_SECTIONS,RESEARCH_PAGE_LIMIT,RESEARCH_CONTROL_LIMIT,RESEARCH_COMPARISON_SECTIONS} from './workspace-contracts.mjs';
export const researchWorkspaceId = directory => 'research_' + createHash('sha256').update(directory).digest('hex');
export const researchSummary = value => Object.fromEntries(
  ['schema','id','title','description','revision','createdAt','updatedAt','questionCount','editionCount','selectedCount','findingCount','citationReviewCount']
    .filter(key => Object.hasOwn(value,key)).map(key => [key,value[key]]));
export const researchRevision = value => {
  need(Number.isSafeInteger(value)&&value>=1&&value<100000000,'REVISION_INVALID');return value;
};
export function researchPage(values,{offset=0,limit=30}={}){
  need(Array.isArray(values)&&Number.isSafeInteger(offset)&&offset>=0&&offset<=values.length&&
    Number.isSafeInteger(limit)&&limit>=1&&limit<=RESEARCH_PAGE_LIMIT,'RESEARCH_PAGE_INVALID');
  const items=values.slice(offset,offset+limit),nextOffset=offset+items.length<values.length?offset+items.length:null;
  return {offset,limit,total:values.length,items,nextOffset,complete:nextOffset===null};
}
export function researchConnection(value){
  need(object(value)&&typeof value.url==='string'&&value.url.length<=2048,'RESEARCH_CONNECTION_INVALID');
  let url;try{url=new URL(value.url);}catch{need(false,'RESEARCH_CONNECTION_INVALID');}
  need(url.protocol==='http:'&&url.hostname==='127.0.0.1'&&url.port&&url.pathname==='/'&&
    !url.username&&!url.password&&!url.search&&/^#token=[a-f0-9]{64}$/.test(url.hash),'RESEARCH_CONNECTION_INVALID');
  need(value.schema===undefined||value.schema===RESEARCH_WORKSPACE_CONNECTION,'RESEARCH_CONNECTION_INVALID');
  need(value.mode===undefined||value.mode==='RESEARCH_DOSSIER_WORKSPACE','RESEARCH_CONNECTION_INVALID');
  need(value.workspaceId===undefined||/^research_[a-f0-9]{64}$/.test(value.workspaceId),'RESEARCH_CONNECTION_INVALID');
  need(value.instanceId===undefined||/^[a-f0-9-]{36}$/.test(value.instanceId),'RESEARCH_CONNECTION_INVALID');
  return {origin:url.origin,token:url.hash.slice(7),workspaceId:value.workspaceId,instanceId:value.instanceId};
}
export async function researchSection(store,id,{section,revision,offset=0,limit=30,questionId,query='',selected}={}){
  need(RESEARCH_SECTIONS.includes(section),'RESEARCH_SECTION_INVALID');
  need(typeof query==='string'&&query.length<=1000,'RESEARCH_QUERY_INVALID');
  need(selected===undefined||typeof selected==='boolean','RESEARCH_SELECTION_INVALID');
  need(questionId===undefined||typeof questionId==='string'&&/^q_[a-f0-9-]{36}$/.test(questionId),'QUESTION_NOT_FOUND');
  if(revision!==undefined)researchRevision(revision);
  need(offset===0||revision!==undefined,'RESEARCH_PAGE_REVISION_REQUIRED');
  const metadata=await store.getMetadata(id,{revision});
  if(questionId!==undefined)need(metadata.questions.some(row=>row.id===questionId),'QUESTION_NOT_FOUND');
  let values;
  if(section==='sources'){
    const view=await store.get(id,{revision:metadata.revision,references:false,includeHistory:false});
    values=view.sources.filter(row=>(questionId===undefined||row.citations.some(c=>c.questionId===questionId))&&
      (selected===undefined||row.selected===selected));
  }else if(section==='revisions'){
    need(questionId===undefined&&selected===undefined&&!query,'RESEARCH_FILTER_INVALID');
    values=await store.listRevisions(id,{revision:metadata.revision});
  }else{
    need(selected===undefined||section==='selections','RESEARCH_FILTER_INVALID');
    values=metadata[section].filter(row=>(questionId===undefined||(section==='questions'?row.id:row.questionId)===questionId)&&
      (selected===undefined||row.selected===selected));
  }
  if(query){const text=query.toLocaleLowerCase();values=values.filter(row=>JSON.stringify(row).toLocaleLowerCase().includes(text));}
  const page=researchPage(values,{offset,limit});
  if(section==='sources')page.items=inspectResearchSources(page.items);
  return {dossier:researchSummary(metadata),section,revision:metadata.revision,...page,
    next:page.nextOffset===null?null:{revision:metadata.revision,offset:page.nextOffset,limit}};
}

export function researchComparison(value,{section='overview',offset=0,limit=30}={}){
  const sections={added:value.added,removed:value.removed,changed:value.changed,questions:value.questions,
    editions:value.editions,availability:value.availability,'findings-added':value.findings.added,
    'findings-removed':value.findings.removed,'findings-changed':value.findings.changed};
  need(section==='overview'||RESEARCH_COMPARISON_SECTIONS.includes(section),'RESEARCH_COMPARISON_SECTION_INVALID');
  const result={before:value.before,after:value.after,counts:Object.fromEntries(Object.entries(sections).map(([key,rows])=>[key,rows.length])),section};
  if(section==='overview')return result;
  const page=researchPage(sections[section],{offset,limit});
  if(section==='added'||section==='removed')page.items=inspectResearchSources(page.items);
  if(section==='changed')page.items=inspectResearchComparison({added:[],removed:[],changed:page.items}).changed;
  return {...result,page};
}
export function researchCrossrefReview(value,{section='overview',offset=0,limit=30}={}){
  need(['overview','dois','records','added','removed','changed','warnings'].includes(section),'RESEARCH_CROSSREF_SECTION_INVALID');
  const {dois,...payload}=value.plan.payload;
  const plan={...value.plan,payload:{...payload,doiCount:dois.length}};
  const result={...value,plan,review:value.review?{
    coverage:value.review.coverage,usage:value.review.usage,recordCount:value.review.records.length,
    warningCount:value.review.warnings.length,comparison:{
      schema:value.review.comparison.schema,before:value.review.comparison.before,after:value.review.comparison.after,
      added:value.review.comparison.added.length,removed:value.review.comparison.removed.length,
      changed:value.review.comparison.changed.length}}:null,section};
  if(section==='overview')return result;
  const rows=section==='dois'?dois:section==='records'?value.review?.records:section==='warnings'?value.review?.warnings:
    value.review?.comparison[section];
  need(Array.isArray(rows),'CROSSREF_EDITION_NOT_READY');
  return {...result,page:researchPage(rows,{offset,limit})};
}

/** OpenAlex retained-cohort analysis. Pure ESM: no network, storage, or dependencies.
 * Source semantics: https://help.openalex.org/data/works/attributes/
 * https://help.openalex.org/data/authorships/ and https://help.openalex.org/data/
 */
const PREFIXES = Object.freeze({works:'W',authors:'A',institutions:'I',sources:'S',topics:'T',funders:'F',publishers:'P',awards:'G'});
const DECISION_STATES = new Set(['include','exclude','undecided']);
const FIELD_NAMES = ['doi','title','publication_year','publication_date','type','language','cited_by_count','authorships','primary_location','open_access','topics','keywords','funders','awards','biblio','is_retracted','updated_date'];
const isObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const text = value => typeof value === 'string' ? value : null;
const numeric = value => typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : null;
const array = value => Array.isArray(value) ? value : [];
const clone = value => value === undefined ? null : JSON.parse(JSON.stringify(value));
const has = (value, key) => Object.prototype.hasOwnProperty.call(value, key);
const compareText = (left, right) => String(left ?? '').localeCompare(String(right ?? ''), 'en');

function entityName(entity) {
  if (!has(PREFIXES, entity)) throw new TypeError('Unsupported research entity: ' + String(entity));
  return entity;
}

/** Canonicalize an OpenAlex identity; never merge records by DOI, title, or name. */
export function researchIdentity(value, {entity = 'works'} = {}) {
  entityName(entity);
  if (isObject(value)) value = value.id ?? value.ids?.openalex;
  if (typeof value !== 'string') return null;
  const match = value.trim().match(/^(?:(?:https?:\/\/)?openalex\.org\/)?(?:(works|authors|institutions|sources|topics|funders|publishers|awards)\/)?([WAISTFPG][0-9]+)\/?$/i);
  if (!match || (match[1] && match[1].toLowerCase() !== entity) || match[2][0].toUpperCase() !== PREFIXES[entity]) return null;
  return 'https://openalex.org/' + match[2].toUpperCase();
}

function stable(value) {
  if (Array.isArray(value)) return '[' + value.map(stable).join(',') + ']';
  if (isObject(value)) return '{' + Object.keys(value).sort().filter(key => value[key] !== undefined).map(key => JSON.stringify(key) + ':' + stable(value[key])).join(',') + '}';
  return JSON.stringify(value) ?? 'null';
}

function differentFields(before, after) {
  return [...new Set([...Object.keys(before), ...Object.keys(after)])].sort().filter(key => has(before,key) !== has(after,key) || stable(before[key]) !== stable(after[key]));
}

function indexRecords(records, entity) {
  if (!Array.isArray(records)) throw new TypeError('Research records must be an array of original entity objects.');
  const byId = new Map(), duplicates = [], unidentified = [];
  records.forEach((record, index) => {
    const id = researchIdentity(record, {entity});
    if (!id || !isObject(record)) {
      unidentified.push({index,providedId:isObject(record) ? text(record.id ?? record.ids?.openalex) : null,title:isObject(record) ? text(record.title ?? record.display_name) : null,reason:isObject(record) ? 'missing_or_invalid_openalex_id' : 'record_is_not_an_object'});
      return;
    }
    if (byId.has(id)) {
      const first = byId.get(id);
      const changedFields = differentFields({...first.record,id}, {...record,id});
      duplicates.push({id,index,keptIndex:first.index,conflicting:changedFields.length > 0,changedFields});
    } else byId.set(id, {id,index,record});
  });
  return {byId,duplicates,unidentified};
}

export function researchDecision(decisions, id) {
  const raw = decisions instanceof Map ? decisions.get(id) : isObject(decisions) && has(decisions,id) ? decisions[id] : undefined;
  const status = isObject(raw) && DECISION_STATES.has(raw.status) ? raw.status : 'undecided';
  return {status,notes:isObject(raw) && typeof raw.notes === 'string' ? raw.notes : '',tags:isObject(raw) ? array(raw.tags).filter(value => typeof value === 'string') : [],updatedAt:isObject(raw) ? text(raw.updatedAt) : null};
}

function reference(value, entity) {
  const object = isObject(value) ? value : {id:value};
  return {id:researchIdentity(object,{entity}),providerId:text(object.id),name:text(object.display_name),orcid:text(object.orcid),ror:text(object.ror),countryCode:text(object.country_code),type:text(object.type)};
}

function uniqueReferences(values) {
  const seen = new Set(), result = [];
  for (const value of values) {
    if (value.id && seen.has(value.id)) continue;
    if (value.id) seen.add(value.id);
    result.push(value);
  }
  return result;
}

function normalizeRecord(record, entity, decisions, index) {
  const id = researchIdentity(record,{entity});
  const authorships = array(record.authorships).filter(isObject);
  const authors = authorships.map(item => ({...reference(item.author,'authors'),rawName:text(item.raw_author_name),position:text(item.author_position),isCorresponding:typeof item.is_corresponding === 'boolean' ? item.is_corresponding : null,institutions:uniqueReferences(array(item.institutions).map(value => reference(value,'institutions'))),countries:array(item.countries).filter(value => typeof value === 'string')}));
  const institutions = uniqueReferences([...authors.flatMap(author => author.institutions),...array(record.institutions).map(value => reference(value,'institutions'))]);
  const topics = array(record.topics).filter(isObject).map(item => ({...reference(item,'topics'),score:numeric(item.score),subfield:isObject(item.subfield) ? clone(item.subfield) : null,field:isObject(item.field) ? clone(item.field) : null,domain:isObject(item.domain) ? clone(item.domain) : null}));
  const primary = has(record,'primary_topic') ? record.primary_topic : array(record.topics)[0];
  const primaryTopic = isObject(primary) ? {...reference(primary,'topics'),score:numeric(primary.score),subfield:clone(primary.subfield),field:clone(primary.field),domain:clone(primary.domain)} : null;
  const awards = array(record.awards).filter(isObject).map(item => ({...reference(item,'awards'),funderId:researchIdentity(item.funder_id ?? item.funder?.id,{entity:'funders'}),funderName:text(item.funder_display_name ?? item.funder?.display_name),funderAwardId:text(item.funder_award_id),doi:text(item.doi)}));
  const funders = uniqueReferences([...array(record.funders).map(value => reference(value,'funders')),...awards.filter(item => item.funderId).map(item => reference({id:item.funderId,display_name:item.funderName},'funders'))]);
  const location = isObject(record.primary_location) ? record.primary_location : {};
  const source = isObject(location.source) ? reference(location.source,'sources') : null;
  const openAccess = isObject(record.open_access) ? record.open_access : {};
  const biblio = isObject(record.biblio) ? record.biblio : {};
  const year = Number.isInteger(record.publication_year) && record.publication_year > 0 ? record.publication_year : null;
  return {
    id,providerId:text(record.id ?? record.ids?.openalex),shortId:id.slice(id.lastIndexOf('/') + 1),inputIndex:index,
    title:text(record.title ?? record.display_name),doi:text(record.doi ?? record.ids?.doi),
    publicationYear:year,publicationDate:text(record.publication_date),type:text(record.type),language:text(record.language),
    citedByCount:numeric(record.cited_by_count),providerWorksCount:numeric(record.works_count),
    isOpenAccess:typeof openAccess.is_oa === 'boolean' ? openAccess.is_oa : null,oaStatus:text(openAccess.oa_status),oaUrl:text(openAccess.oa_url),
    isRetracted:typeof record.is_retracted === 'boolean' ? record.is_retracted : null,updatedDate:text(record.updated_date),
    authors,institutions,topics,primaryTopic,funders,awards,source,
    keywords:array(record.keywords).filter(isObject).map(item => ({id:text(item.id),name:text(item.display_name),score:numeric(item.score)})),
    biblio:{volume:text(biblio.volume),issue:text(biblio.issue),firstPage:text(biblio.first_page),lastPage:text(biblio.last_page)},
    containerTitle:isObject(record.volume) ? text(record.volume.display_name) : null,
    landingPageUrl:text(location.landing_page_url),pdfUrl:text(location.pdf_url),countryCode:text(record.country_code),homepageUrl:text(record.homepage_url),
    decision:researchDecision(decisions,id),fieldPresence:Object.fromEntries(FIELD_NAMES.map(field => [field,has(record,field)])),
    authorshipsAtCap:authorships.length >= 100,
    unresolvedAuthors:authors.filter(item => !item.id).length,unresolvedInstitutions:institutions.filter(item => !item.id).length,
    unresolvedTopics:topics.filter(item => !item.id).length,unresolvedFunders:funders.filter(item => !item.id).length
  };
}

function groups(rows, select, {overlap = true, unit = 'works', order = 'count'} = {}) {
  const entries = new Map();
  for (const row of rows) {
    const seen = new Set();
    for (const membership of select(row)) {
      if (!membership || membership.id === null || membership.id === undefined || seen.has(String(membership.id))) continue;
      const id = String(membership.id);
      seen.add(id);
      let group = entries.get(id);
      if (!group) {
        group = {...membership,id,name:membership.name ?? id,workCount:0,recordCount:0,includedRecordCount:0,includedWorkCount:0,citationsReceived:0,citationRecords:0,workIds:[],recordIds:[]};
        entries.set(id,group);
      }
      if (!group.name && membership.name) group.name = membership.name;
      group.workCount += 1;
      group.recordCount += 1;
      group.includedRecordCount += row.decision.status === 'include' ? 1 : 0;
      group.includedWorkCount += row.decision.status === 'include' ? 1 : 0;
      if (row.citedByCount !== null && unit === 'works') {group.citationsReceived += row.citedByCount;group.citationRecords += 1;}
      group.workIds.push(row.id);
      group.recordIds.push(row.id);
    }
  }
  const values = [...entries.values()].map(group => ({...group,citationsReceived:unit === 'works' && group.citationRecords > 0 ? group.citationsReceived : null,shareOfRetainedRecords:rows.length ? group.recordCount / rows.length : 0,unit,overlapping:overlap,...(unit === 'works' ? {} : {workCount:null,includedWorkCount:null,citationsReceived:null,citationRecords:null,workIds:[]})}));
  values.sort(order === 'year' ? (a,b) => a.id === 'unknown' ? 1 : b.id === 'unknown' ? -1 : Number(a.id)-Number(b.id) : (a,b) => b.recordCount-a.recordCount || compareText(a.name,b.name) || compareText(a.id,b.id));
  return values;
}

function decisionTable(rows, entity) {
  return ['include','exclude','undecided'].map(status => {
    const selected = rows.filter(row => row.decision.status === status);
    return {id:status,name:status,recordCount:selected.length,workCount:entity === 'works' ? selected.length : null,recordIds:selected.map(row => row.id),shareOfRetainedRecords:rows.length ? selected.length/rows.length : 0,overlapping:false,unit:entity};
  });
}

function countsFor(rows, intake, entity) {
  const citations = rows.filter(row => row.citedByCount !== null);
  return {
    recordsReceived:intake.recordsReceived,uniqueRecords:rows.length,duplicates:intake.duplicates.length,
    conflictingDuplicates:intake.duplicates.filter(item => item.conflicting).length,unidentifiedRecords:intake.unidentified.length,
    included:rows.filter(row => row.decision.status === 'include').length,excluded:rows.filter(row => row.decision.status === 'exclude').length,undecided:rows.filter(row => row.decision.status === 'undecided').length,
    citationCountSum:entity === 'works' && citations.length ? citations.reduce((sum,row) => sum+row.citedByCount,0) : null,
    citationRecords:citations.length,citationRecordsMissing:rows.length-citations.length,
    openAccessRecords:rows.filter(row => row.isOpenAccess === true).length,openAccessUnknown:rows.filter(row => row.isOpenAccess === null).length,
    retractedRecords:rows.filter(row => row.isRetracted === true).length,retractionStatusUnknown:rows.filter(row => row.isRetracted === null).length,
    authorshipsAtCap:rows.filter(row => row.authorshipsAtCap).length,
    unresolvedAuthorOccurrences:rows.reduce((sum,row) => sum+row.unresolvedAuthors,0),
    unresolvedInstitutionOccurrences:rows.reduce((sum,row) => sum+row.unresolvedInstitutions,0)
  };
}

/** Analyze rows in retained edition page order. First occurrence of each ID wins. */
export function analyzeResearch(records, {entity = 'works',decisions = {}} = {}) {
  entityName(entity);
  const indexed = indexRecords(records,entity);
  const rows = [...indexed.byId.values()].map(item => normalizeRecord(item.record,entity,decisions,item.index));
  const works = entity === 'works';
  const options = {unit:entity};
  const membership = select => works ? groups(rows,select,options) : [];
  const single = select => groups(rows,select,{...options,overlap:false});
  const originals = [...indexed.byId.values()].map(item => item.record);
  const selectedFields = works ? FIELD_NAMES : ['display_name','works_count','cited_by_count','country_code','type','homepage_url','updated_date'];
  const fieldCoverage = selectedFields.map(field => ({
    field,present:originals.filter(record => has(record,field)).length,
    missing:originals.filter(record => !has(record,field)).length,
    nullValues:originals.filter(record => has(record,field) && record[field] === null).length,
    emptyArrays:originals.filter(record => Array.isArray(record[field]) && record[field].length === 0).length
  }));
  const tables = {
    records:rows,
    authors:membership(row => row.authors.filter(item => item.id).map(({id,providerId,name,orcid}) => ({id,providerId,name,orcid}))),
    institutions:membership(row => row.institutions.filter(item => item.id)),
    topics:membership(row => row.topics.filter(item => item.id).map(({id,providerId,name,subfield,field,domain}) => ({id,providerId,name,subfield,field,domain}))),
    primaryTopics:works ? groups(rows,row => row.primaryTopic?.id ? [{id:row.primaryTopic.id,name:row.primaryTopic.name,subfield:row.primaryTopic.subfield,field:row.primaryTopic.field,domain:row.primaryTopic.domain}] : [],{...options,overlap:false}) : [],
    funders:membership(row => row.funders.filter(item => item.id)),
    sources:works ? groups(rows,row => row.source?.id ? [row.source] : [],{...options,overlap:false}) : [],
    years:works ? groups(rows,row => [{id:row.publicationYear ?? 'unknown',name:row.publicationYear === null ? 'Not supplied' : String(row.publicationYear)}],{...options,overlap:false,order:'year'}) : [],
    types:single(row => [{id:row.type ?? 'unknown',name:row.type ?? 'Not supplied'}]),
    languages:works ? single(row => [{id:row.language ?? 'unknown',name:row.language ?? 'Not supplied'}]) : [],
    openAccess:works ? single(row => [{id:row.oaStatus ?? 'unknown',name:row.oaStatus ?? 'Not supplied'}]) : [],
    countries:works ? membership(row => [...new Set([...row.authors.flatMap(author => author.countries),...row.institutions.map(item => item.countryCode).filter(Boolean)])].map(code => ({id:code,name:code}))) : single(row => [{id:row.countryCode ?? 'unknown',name:row.countryCode ?? 'Not supplied'}]),
    decisions:decisionTable(rows,entity),fieldCoverage
  };
  const intake = {recordsReceived:records.length,duplicates:indexed.duplicates,unidentified:indexed.unidentified};
  const presentIds = new Set(rows.map(row => row.id));
  const decisionEntries = decisions instanceof Map ? [...decisions.keys()] : isObject(decisions) ? Object.keys(decisions) : [];
  return {
    schema:'sf88.research-analysis.v1',entity,counts:countsFor(rows,intake,entity),tables,
    identity:{key:'canonical_openalex_id',duplicatePolicy:'first_occurrence_in_edition_page_order',duplicateOccurrences:indexed.duplicates,unidentifiedRecords:indexed.unidentified},
    review:{decisionKey:'canonical_openalex_id',orphanDecisionIds:decisionEntries.filter(id => !presentIds.has(id)),selection:'include'},
    methods:{
      scope:'Distinct identified ' + entity + ' retained in this edition.',
      memberships:works ? 'Each identified work contributes at most once to each group. Author, institution, topic, funder and country groups overlap; their counts must not be added to obtain cohort size.' : 'Each identified retained entity contributes at most once to each applicable group. Provider works_count and cited_by_count remain per-entity metadata; overlapping research portfolios are not pooled.',
      citations:works ? 'Citation sums use supplied cited_by_count values for distinct retained works. Missing values stay missing. These are provider citation counts at retrieval, not citations between cohort members.' : 'Provider citation counts remain in individual entity rows. They may refer to overlapping works and are not summed across entities.',
      authors:'Author and institution groups use identifiers, never matching names. Authorships can be capped at 100 in the provider response. Unresolved references remain visible on each record.',
      funding:'Funder groups combine current funders and awards.funder_id, deduplicated within each work. Work membership counts do not measure grant amounts.',
      topics:'Topics are provider classifications. Primary topic is the explicit primary_topic or first returned topics entry, as documented by OpenAlex.',
      coverage:'Query coverage is supplied separately by the edition collector. Retained counts do not establish that an entire query has been retrieved.',
      bibliography:'Bibliography fields come from retained metadata. Supplied author names are kept verbatim; family names and missing bibliographic fields are not inferred.',
      references:['https://help.openalex.org/data/works/attributes/','https://help.openalex.org/data/authorships/','https://help.openalex.org/data/works/citations/','https://help.openalex.org/data/','https://help.openalex.org/api/paging/']
    }
  };
}

/** Apply the workspace's current review map without changing retained metadata. */
export function withResearchDecisions(analysis, decisions) {
  if (!analysis?.tables?.records || !analysis.identity) throw new TypeError('A research analysis is required.');
  if (decisions === undefined) return analysis;
  const rows = analysis.tables.records.map(row => ({...row,decision:researchDecision(decisions,row.id)}));
  const included = new Set(rows.filter(row => row.decision.status === 'include').map(row => row.id));
  const tables = Object.fromEntries(Object.entries(analysis.tables).map(([key,values]) => [key,key === 'records' ? rows : key === 'decisions' ? decisionTable(rows,analysis.entity) : values.map(row => row.recordIds || row.workIds ? {...row,includedRecordCount:(row.recordIds ?? row.workIds).filter(id => included.has(id)).length,includedWorkCount:analysis.entity === 'works' ? row.workIds.filter(id => included.has(id)).length : null} : row)]));
  const intake = {recordsReceived:analysis.counts.recordsReceived,duplicates:analysis.identity.duplicateOccurrences,unidentified:analysis.identity.unidentifiedRecords};
  const ids = new Set(rows.map(row => row.id));
  const keys = decisions instanceof Map ? [...decisions.keys()] : isObject(decisions) ? Object.keys(decisions) : [];
  return {...analysis,tables,counts:countsFor(rows,intake,analysis.entity),review:{...analysis.review,orphanDecisionIds:keys.filter(id => !ids.has(id))}};
}

/** Compare the exact retained metadata of two editions by canonical identity. */
export function compareResearch(beforeRecords, afterRecords, {entity = 'works'} = {}) {
  entityName(entity);
  const before = indexRecords(beforeRecords,entity),after = indexRecords(afterRecords,entity);
  const added = [],removed = [],changed = [];
  let unchanged = 0;
  for (const [id,item] of after.byId) {
    if (!before.byId.has(id)) {added.push(normalizeRecord(item.record,entity,{},item.index));continue;}
    const prior = before.byId.get(id);
    const changedFields = differentFields({...prior.record,id},{...item.record,id});
    if (!changedFields.length) {unchanged += 1;continue;}
    changed.push({id,title:text(item.record.title ?? item.record.display_name),changedFields,before:normalizeRecord(prior.record,entity,{},prior.index),after:normalizeRecord(item.record,entity,{},item.index)});
  }
  for (const [id,item] of before.byId) if (!after.byId.has(id)) removed.push(normalizeRecord(item.record,entity,{},item.index));
  return {
    schema:'sf88.research-comparison.v1',entity,counts:{before:before.byId.size,after:after.byId.size,added:added.length,removed:removed.length,changed:changed.length,unchanged},
    added,removed,changed,
    identity:{key:'canonical_openalex_id',duplicatePolicy:'first_occurrence_in_edition_page_order',beforeDuplicates:before.duplicates,afterDuplicates:after.duplicates,beforeUnidentified:before.unidentified,afterUnidentified:after.unidentified},
    method:'Added and removed mean membership changes between the retained editions. Changed means at least one supplied metadata field differs after canonicalizing the primary ID. Query identity and completeness belong to the edition metadata.'
  };
}

/** Standalone reports and bibliography exports for retained OpenAlex editions. */
import {withResearchDecisions} from './analysis.mjs';

const label = value => value === null || value === undefined ? '' : String(value);
const html = value => label(value).replace(/[&<>"']/g,char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const list = value => Array.isArray(value) ? value : [];
const oneLine = value => label(value).replace(/[\r\n\u2028\u2029]+/g,' ');
const json = value => JSON.stringify(value,null,2) + '\n';
const integerFormat = new Intl.NumberFormat('en-US');
const count = value => typeof value === 'number' && Number.isFinite(value) ? integerFormat.format(value) : 'Not supplied';
const percent = value => typeof value === 'number' && Number.isFinite(value) ? (value*100).toFixed(1) + '%' : '';
const nameOf = item => item.name ?? item.rawName ?? item.id ?? 'Name not supplied';
const names = values => list(values).map(nameOf);
const ids = values => list(values).map(value => value.id).filter(Boolean);

function httpUrl(value) {
  try {const url = new URL(value);return ['https:','http:'].includes(url.protocol) ? url.href : null;} catch {return null;}
}
function link(url,value) {
  const safe = httpUrl(url);
  return safe ? '<a href="' + html(safe) + '" rel="noopener noreferrer">' + html(value) + '</a>' : html(value);
}
function doiValue(row) {return label(row.doi).replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'');}
function doiUrl(row) {
  const value = doiValue(row);
  return /^10\.[0-9]{4,9}\//.test(value) ? 'https://doi.org/' + encodeURIComponent(value).replace(/%2F/gi,'/') : null;
}
function anchor(row) {return 'record-' + row.shortId;}

/** RFC 4180 output, with spreadsheet formula prefixes escaped for text cells. */
function csvCell(value) {
  let string = value === null || value === undefined ? '' : typeof value === 'object' ? JSON.stringify(value) : String(value);
  if (typeof value === 'string' && (/^[\u0000-\u0020]*[=+\-@]/.test(string) || /^[\t\r\n]/.test(string))) string = "'" + string;
  return '"' + string.replace(/"/g,'""') + '"';
}
function csv(columns,rows) {
  return [columns.map(column => csvCell(column.label)).join(','),...rows.map(row => columns.map(column => csvCell(column.value(row))).join(','))].join('\r\n') + '\r\n';
}
const column = (name,key = name) => ({label:name,value:row => row[key]});
const RECORD_COLUMNS = [
  column('openalex_id','id'),column('provider_id','providerId'),column('title'),column('doi'),
  column('publication_year','publicationYear'),column('publication_date','publicationDate'),column('type'),column('language'),
  column('cited_by_count','citedByCount'),column('provider_works_count','providerWorksCount'),
  {label:'authors',value:row => names(row.authors)},{label:'author_ids',value:row => ids(row.authors)},
  {label:'institutions',value:row => names(row.institutions)},{label:'institution_ids',value:row => ids(row.institutions)},
  {label:'primary_source',value:row => row.source?.name},{label:'primary_source_id',value:row => row.source?.id},
  {label:'topics',value:row => names(row.topics)},{label:'topic_ids',value:row => ids(row.topics)},
  {label:'primary_topic',value:row => row.primaryTopic?.name},{label:'primary_topic_id',value:row => row.primaryTopic?.id},
  {label:'funders',value:row => names(row.funders)},{label:'funder_ids',value:row => ids(row.funders)},
  {label:'award_ids',value:row => ids(row.awards)},{label:'keywords',value:row => names(row.keywords)},
  column('is_open_access','isOpenAccess'),column('open_access_status','oaStatus'),column('open_access_url','oaUrl'),
  column('is_retracted','isRetracted'),column('updated_date','updatedDate'),
  {label:'volume',value:row => row.biblio.volume},{label:'issue',value:row => row.biblio.issue},
  {label:'first_page',value:row => row.biblio.firstPage},{label:'last_page',value:row => row.biblio.lastPage},
  {label:'review_status',value:row => row.decision.status},{label:'review_notes',value:row => row.decision.notes},
  {label:'review_tags',value:row => row.decision.tags},{label:'review_updated_at',value:row => row.decision.updatedAt},
  column('authorships_at_provider_cap','authorshipsAtCap'),column('unresolved_author_occurrences','unresolvedAuthors'),
  column('unresolved_institution_occurrences','unresolvedInstitutions'),column('input_index','inputIndex')
];
const GROUP_COLUMNS = [
  column('id'),column('name'),column('record_count','recordCount'),column('work_count','workCount'),
  column('included_record_count','includedRecordCount'),column('included_work_count','includedWorkCount'),column('share_of_retained_records','shareOfRetainedRecords'),
  column('citations_received','citationsReceived'),column('records_with_citation_count','citationRecords'),
  column('country_code','countryCode'),column('type'),column('ror'),column('orcid'),
  {label:'subfield_id',value:row => row.subfield?.id},{label:'subfield_name',value:row => row.subfield?.display_name},
  {label:'field_id',value:row => row.field?.id},{label:'field_name',value:row => row.field?.display_name},
  {label:'domain_id',value:row => row.domain?.id},{label:'domain_name',value:row => row.domain?.display_name},
  column('overlapping'),column('unit'),column('work_ids','workIds'),column('record_ids','recordIds')
];

function tex(value) {
  const escapes = {'\\':'\\textbackslash{}','{':'\\{','}':'\\}','%':'\\%','&':'\\&','_':'\\_','#':'\\#','$':'\\$','~':'\\textasciitilde{}','^':'\\textasciicircum{}'};
  return oneLine(value).replace(/[\\{}%&_#$~^]/g,char => escapes[char]);
}
function bibliographyType(row) {
  return ({article:'article',review:'article',book:'book','book-chapter':'incollection','proceedings-article':'inproceedings',dissertation:'phdthesis',report:'techreport'})[row.type] ?? 'misc';
}
function bibtex(rows) {
  return rows.map(row => {
    const type = bibliographyType(row),fields = [];
    const add = (key,value,{escaped = false} = {}) => {if (value !== null && value !== undefined && value !== '') fields.push('  ' + key + ' = {' + (escaped ? value : tex(value)) + '}');};
    add('title',row.title);
    const authorNames = row.authors.map(author => author.name ?? author.rawName).filter(Boolean);
    if (authorNames.length) add('author',authorNames.map(name => '{' + tex(name) + '}').join(' and '),{escaped:true});
    add('year',row.publicationYear);add('doi',doiValue(row));add('url',doiUrl(row) ?? httpUrl(row.landingPageUrl) ?? row.id);
    if (['article','incollection','inproceedings'].includes(type)) add(type === 'article' ? 'journal' : 'booktitle',type === 'article' ? row.source?.name : row.containerTitle);
    add('volume',row.biblio.volume);add('number',row.biblio.issue);
    const pages = row.biblio.firstPage && row.biblio.lastPage && row.biblio.firstPage !== row.biblio.lastPage ? row.biblio.firstPage + '--' + row.biblio.lastPage : row.biblio.firstPage ?? row.biblio.lastPage;
    add('pages',pages);add('language',row.language);
    add('note','OpenAlex ' + row.shortId + '; review: ' + row.decision.status + (row.isRetracted === true ? '; provider marks retracted' : ''));
    return '@' + type + '{OpenAlex_' + row.shortId + ',\n' + fields.join(',\n') + '\n}';
  }).join('\n\n') + (rows.length ? '\n' : '');
}
function ris(rows) {
  const types = {article:'JOUR',review:'JOUR',book:'BOOK','book-chapter':'CHAP','proceedings-article':'CPAPER',dissertation:'THES',report:'RPRT',dataset:'DATA'};
  return rows.map(row => {
    const fields = [];
    const add = (tag,value) => {if (value !== null && value !== undefined && value !== '') fields.push(tag + '  - ' + oneLine(value));};
    add('TY',types[row.type] ?? 'GEN');add('ID',row.id);add('TI',row.title);
    for (const author of row.authors) add('AU',author.name ?? author.rawName);
    add('PY',row.publicationYear);add('DA',row.publicationDate?.replace(/-/g,'/'));add('T2',row.source?.name);
    add('VL',row.biblio.volume);add('IS',row.biblio.issue);add('SP',row.biblio.firstPage);add('EP',row.biblio.lastPage);
    add('DO',doiValue(row));add('UR',doiUrl(row) ?? httpUrl(row.landingPageUrl) ?? row.id);add('LA',row.language);
    for (const keyword of row.keywords) add('KW',keyword.name);
    for (const tag of row.decision.tags) add('KW',tag);
    add('N1','OpenAlex ' + row.shortId + '; review: ' + row.decision.status + (row.isRetracted === true ? '; provider marks retracted' : ''));
    if (row.decision.notes) add('N1',row.decision.notes);
    fields.push('ER  - ');
    return fields.join('\r\n');
  }).join('\r\n\r\n') + (rows.length ? '\r\n' : '');
}

/** Deferred deterministic serializers. Each file is rendered only when requested. */
export function researchExportPlan(analysis, {title = 'Research edition',query = null,coverage = null,decisions,comparison = null} = {}) {
  const view = withResearchDecisions(analysis,decisions);
  const rows = view.tables.records,selected = rows.filter(row => row.decision.status === 'include');
  const files = {
    'research-analysis.json':() => json({title,query,coverage,analysis:view,...(comparison ? {comparison} : {})}),
    'records.csv':() => csv(RECORD_COLUMNS,rows),
    'selected-records.csv':() => csv(RECORD_COLUMNS,selected),
    'review-decisions.csv':() => csv([column('openalex_id','id'),{label:'status',value:row => row.decision.status},{label:'notes',value:row => row.decision.notes},{label:'tags',value:row => row.decision.tags},{label:'updated_at',value:row => row.decision.updatedAt}],rows),
    'duplicate-occurrences.csv':() => csv([column('id'),column('input_index','index'),column('kept_input_index','keptIndex'),column('conflicting'),column('changed_fields','changedFields')],view.identity.duplicateOccurrences),
    'unidentified-records.csv':() => csv([column('input_index','index'),column('provider_id','providedId'),column('title'),column('reason')],view.identity.unidentifiedRecords),
    'field-coverage.csv':() => csv([column('field'),column('present'),column('missing'),column('null_values','nullValues'),column('empty_arrays','emptyArrays')],view.tables.fieldCoverage)
  };
  for (const [name,table] of Object.entries(view.tables)) if (!['records','fieldCoverage','decisions'].includes(name)) files[name.replace(/[A-Z]/g,char => '-' + char.toLowerCase()) + '.csv'] = () => csv(GROUP_COLUMNS,table);
  if (view.entity === 'works') {
    files['references.bib'] = () => bibtex(rows);files['references.ris'] = () => ris(rows);
    files['selected-references.bib'] = () => bibtex(selected);files['selected-references.ris'] = () => ris(selected);
  }
  if (comparison) {
    files['edition-comparison.json'] = () => json(comparison);
    files['edition-added.csv'] = () => csv(RECORD_COLUMNS,comparison.added);
    files['edition-removed.csv'] = () => csv(RECORD_COLUMNS,comparison.removed);
    files['edition-changed.csv'] = () => csv([column('openalex_id','id'),column('title'),column('changed_fields','changedFields')],comparison.changed);
  }
  files['report.html'] = () => renderResearchReport({title,query,coverage,analysis:view,comparison});
  files['README.txt'] = () => [
    title,'','Entity: ' + view.entity,'Identified records: ' + view.counts.uniqueRecords,
    'Received occurrences: ' + view.counts.recordsReceived,'Retained query coverage: ' + (coverage?.state ?? 'UNSPECIFIED'),
    'Included review decisions: ' + selected.length,'',
    'records.csv includes all identified records; selected files include only status=include.',
    'Each named group CSV carries its exact member IDs and denominator. Groups can overlap.',
    'CSV text cells with spreadsheet formula prefixes receive a leading apostrophe. Exact text remains in research-analysis.json.',
    'BibTeX and RIS use supplied names and bibliographic fields. Missing values are omitted.',
    'The original provider response bytes, query identity and page receipts remain with the originating edition.',
    '',...Object.values(view.methods).filter(value => typeof value === 'string'),'',
    'Source references:',...view.methods.references,''
  ].join('\n');
  return files;
}

/** Complete in-memory bundle for callers that explicitly need all files together. */
export function researchExports(analysis, options) {
  return Object.fromEntries(Object.entries(researchExportPlan(analysis,options)).map(([name,render]) => [name,render()]));
}

function table(headers,body,{className = '',caption = ''} = {}) {
  return '<div class="table-wrap"><table' + (className ? ' class="' + html(className) + '"' : '') + '>' + (caption ? '<caption>' + html(caption) + '</caption>' : '') + '<thead><tr>' + headers.map(value => '<th scope="col">' + html(value) + '</th>').join('') + '</tr></thead><tbody>' + (body.length ? body.join('') : '<tr><td colspan="' + headers.length + '" class="muted">No retained records in this table.</td></tr>') + '</tbody></table></div>';
}
const cells = values => '<tr>' + values.map(value => '<td>' + value + '</td>').join('') + '</tr>';
function recordLinks(ids) {
  return '<details><summary>' + count(ids.length) + ' records</summary><div class="record-links">' + ids.map(id => '<a href="#record-' + html(id.slice(id.lastIndexOf('/') + 1)) + '">' + html(id.slice(id.lastIndexOf('/') + 1)) + '</a>').join(' ') + '</div></details>';
}
function groupSection(id,title,rows,note) {
  return '<section id="' + html(id) + '"><h3>' + html(title) + ' <span class="muted">(' + count(rows.length) + ')</span></h3><p class="table-note">' + html(note) + '</p><details' + (rows.length <= 12 ? ' open' : '') + '><summary>View all groups</summary>' + table(['Group','Records','Share of cohort','Included records','Citations of retained works','Membership'],rows.map(row => cells([
    link(row.id,row.name ?? row.id),count(row.recordCount),percent(row.shareOfRetainedRecords),
    count(row.includedRecordCount ?? row.includedWorkCount),
    row.unit !== 'works' ? '—' : row.citationsReceived === null || row.citationRecords === 0 ? 'Not supplied' : count(row.citationsReceived) + '<span class="muted"> across ' + count(row.citationRecords) + ' records</span>',
    recordLinks(row.recordIds ?? row.workIds ?? [])
  ]))) + '</details></section>';
}
function cohortRow(row,entity = 'works') {
  const search = [row.shortId,row.title,row.doi,...names(row.authors),...names(row.institutions),...names(row.topics),...names(row.funders),row.decision.notes,...row.decision.tags].filter(Boolean).join(' ').toLowerCase();
  const authors = names(row.authors);
  const authorCell = authors.length ? '<details><summary>' + html(authors.slice(0,3).join('; ')) + (authors.length > 3 ? ' +' + (authors.length-3) : '') + '</summary>' + row.authors.map(author => '<div>' + link(author.id,author.name ?? author.rawName ?? 'Name not supplied') + '</div>').join('') + '</details>' : '<span class="muted">Not supplied</span>';
  const bibliography = [row.source?.name,row.biblio.volume ? 'vol. ' + row.biblio.volume : null,row.biblio.issue ? 'no. ' + row.biblio.issue : null,row.biblio.firstPage ? 'p. ' + row.biblio.firstPage + (row.biblio.lastPage && row.biblio.lastPage !== row.biblio.firstPage ? '–' + row.biblio.lastPage : '') : null].filter(Boolean).join(' · ');
  const titleCell = link(row.id,row.title ?? row.shortId) + '<div class="record-id">' + html(row.shortId) + (row.doi ? ' · ' + link(doiUrl(row),row.doi) : '') + '</div>' + (bibliography ? '<div class="muted">' + html(bibliography) + '</div>' : '') + (row.isRetracted === true ? '<strong class="record-flag">Provider marks retracted</strong>' : '');
  const review = '<span class="tag">' + html(row.decision.status) + '</span>' + (row.decision.tags.length ? '<div class="muted">' + html(row.decision.tags.join(', ')) + '</div>' : '') + (row.decision.notes ? '<details><summary>Review note</summary><p class="notes">' + html(row.decision.notes) + '</p></details>' : '');
  if (entity !== 'works') return '<tr id="' + html(anchor(row)) + '" data-cohort-row data-search="' + html(search) + '" data-decision="' + html(row.decision.status) + '"><td>' + titleCell + '</td><td>' + html(row.type ?? 'Not supplied') + '</td><td>' + html(row.countryCode ?? 'Not supplied') + '</td><td class="numeric">' + count(row.providerWorksCount) + '</td><td class="numeric">' + count(row.citedByCount) + '</td><td>' + review + '</td></tr>';
  return '<tr id="' + html(anchor(row)) + '" data-cohort-row data-search="' + html(search) + '" data-decision="' + html(row.decision.status) + '"><td>' + titleCell + '</td><td>' + html(row.publicationYear ?? 'Not supplied') + '</td><td>' + authorCell + '</td><td class="numeric">' + count(row.citedByCount) + '</td><td>' + html(row.oaStatus ?? 'Not supplied') + '</td><td>' + review + '</td></tr>';
}
function comparisonSection(comparison) {
  if (!comparison) return '';
  const compact = rows => table(['OpenAlex ID','Title','Year'],rows.map(row => cells([link(row.id,row.shortId),html(row.title ?? ''),html(row.publicationYear ?? 'Not supplied')])));
  return '<section id="comparison"><h2>Edition changes</h2><p>' + count(comparison.counts.added) + ' added, ' + count(comparison.counts.removed) + ' removed, ' + count(comparison.counts.changed) + ' changed and ' + count(comparison.counts.unchanged) + ' unchanged identified records.</p><p class="table-note">' + html(comparison.method) + '</p><details><summary>Added records</summary>' + compact(comparison.added) + '</details><details><summary>Removed records</summary>' + compact(comparison.removed) + '</details><details><summary>Changed metadata</summary>' + table(['Record','Changed fields','Retained views'],comparison.changed.map(change => cells([
    link(change.id,change.title ?? change.id),html(change.changedFields.join(', ')),
    '<details><summary>Before and after</summary><pre>' + html(json({before:change.before,after:change.after})) + '</pre></details>'
  ]))) + '</details></section>';
}

/** Full standalone HTML, with no external assets, scripts, fonts, or network calls. */
export function renderResearchReport({title = 'Research edition',query = null,coverage = null,analysis,comparison = null} = {}) {
  if (!analysis?.tables?.records) throw new TypeError('A research analysis is required.');
  const {counts,tables} = analysis;
  const state = coverage?.state ?? 'UNSPECIFIED';
